function diagnosticText(value) {
  return value instanceof Error ? value.message : String(value);
}

function registryHasId(registry, id) {
  return Boolean(
    registry?.entries?.some((entry) => entry.id?.id === id) ||
    registry?.image_cleanup?.some((entry) => entry.id?.id === id),
  );
}

const STARTUP_LOG_ERROR_WARNING_LINE = /\[(?:ERROR|WARN(?:ING)?)\]/iu;
const STARTUP_LOG_ERROR_LINE_CAP = 20;
const STARTUP_LOG_TAIL_BYTES = 4096;

function formatSinceOpenLog(text) {
  const slice = String(text);
  const lines = slice
    .split(/\r?\n/u)
    .filter((line) => STARTUP_LOG_ERROR_WARNING_LINE.test(line))
    .slice(0, STARTUP_LOG_ERROR_LINE_CAP);
  const tail = Buffer.from(slice, "utf8").subarray(-STARTUP_LOG_TAIL_BYTES).toString("utf8");
  return { lines, tail };
}

async function collectIndependently(collect) {
  try {
    return { ok: true, value: await collect() };
  } catch (error) {
    return { ok: false, error: diagnosticText(error) };
  }
}

async function probeRendererState(session, rendererTimeoutMs) {
  if (!session || typeof session.execute !== "function") return "unavailable";
  let timer;
  try {
    const result = await Promise.race([
      session.execute(`
        ${closeControlLookup}
        return {
          readyState: document.readyState,
          hasTauri: typeof window.__TAURI_INTERNALS__ === "object",
          windowControlsMounted: Boolean(labelled || fallback),
          bodyText: (document.body && document.body.innerText ? document.body.innerText : "").slice(0, 500),
        };
      `),
      new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error("renderer probe timed out")), rendererTimeoutMs);
      }),
    ]);
    if (result && typeof result === "object" && typeof result.bodyText === "string") {
      return { ...result, bodyText: result.bodyText.slice(0, 500) };
    }
    return result;
  } catch (error) {
    return `unavailable (${diagnosticText(error)})`;
  } finally {
    clearTimeout(timer);
  }
}

function formatRegistryObservation({ registryResult, lastReadError, probeId, orphanImageId }) {
  const parts = [];
  if (registryResult.ok) {
    parts.push(
      `readable; probe ${probeId} ${registryHasId(registryResult.value, probeId) ? "present" : "absent"}`,
    );
    if (orphanImageId !== undefined) {
      parts.push(
        `orphan image ${orphanImageId} ${
          registryHasId(registryResult.value, orphanImageId) ? "present" : "absent"
        }`,
      );
    }
  } else {
    parts.push(`unreadable (${registryResult.error})`);
  }
  if (lastReadError) parts.push(`last read/parse error: ${diagnosticText(lastReadError)}`);
  return parts.join("; ");
}

/**
 * Production callers pass `session` and the since-open log reader. This helper
 * has no timeout parameter; it calls waitFor without a timeout option so the
 * 45 s default applies. A throwing registry read is an observation: polling
 * continues and the last error is kept for timeout evidence. Injected waiter,
 * clock, renderer deadline and driver diagnostics are test seams.
 */
export async function waitForStartupReconciliation({
  label,
  readRegistry,
  isReconciled,
  probeId = "verify-unowned-book",
  orphanImageId,
  session,
  readLogSinceOpen,
  waitFor: waitForImpl = waitFor,
  now = Date.now,
  rendererTimeoutMs = 5_000,
  driverDiagnostics: driverDiagnosticsImpl = driverDiagnostics,
} = {}) {
  const startedAt = now();
  let lastReadError;
  const observe = async () => {
    try {
      const registry = await readRegistry();
      return isReconciled(registry) ? registry : false;
    } catch (error) {
      lastReadError = error;
      return false;
    }
  };

  let registry;
  try {
    registry = await waitForImpl(label, observe);
  } catch (waitError) {
    const elapsedMs = now() - startedAt;
    const registryResult = await collectIndependently(readRegistry);
    const logResult = await collectIndependently(async () =>
      readLogSinceOpen ? await readLogSinceOpen() : "",
    );
    const rendererResult = await collectIndependently(() =>
      probeRendererState(session, rendererTimeoutMs),
    );
    const driverResult = await collectIndependently(() =>
      driverDiagnosticsImpl ? driverDiagnosticsImpl() : "",
    );
    const logEvidence = logResult.ok ? formatSinceOpenLog(logResult.value ?? "") : null;
    const logSection = logEvidence
      ? [
          `application-log errors/warnings (capped at ${STARTUP_LOG_ERROR_LINE_CAP}):`,
          logEvidence.lines.join("\n") || "(none)",
          `application-log tail (last ${STARTUP_LOG_TAIL_BYTES / 1024} KiB):`,
          logEvidence.tail || "(empty)",
        ].join("\n")
      : `application-log unavailable (${logResult.error})`;
    const rendererEvidence = rendererResult.ok
      ? rendererResult.value
      : `unavailable (${rendererResult.error})`;
    const rendererSection = `renderer: ${
      typeof rendererEvidence === "string" ? rendererEvidence : JSON.stringify(rendererEvidence)
    }`;
    const driverSection = driverResult.ok
      ? `driver:\n${driverResult.value || "(empty)"}`
      : `driver unavailable (${driverResult.error})`;
    throw new Error(
      [
        `timed out waiting for ${label} after ${elapsedMs} ms`,
        `registry: ${formatRegistryObservation({
          registryResult,
          lastReadError,
          probeId,
          orphanImageId,
        })}`,
        logSection,
        rendererSection,
        driverSection,
      ].join("\n"),
      { cause: waitError },
    );
  }

  console.log(`  .. ${STARTUP_RECONCILIATION_LATENCY_PHRASE} (${label}): ${now() - startedAt} ms`);
  return registry;
}

/**
 * Captures the log-file byte offset at call time. ENOENT is empty (the file is
 * often created by the session that is about to open); any other read/stat
 * error is thrown so diagnostics can record `unavailable (...)`.
 */
export async function createSinceOpenLogReader(logFile) {
  let openOffset = 0;
  try {
    openOffset = (await stat(logFile)).size;
  } catch (error) {
    if (error?.code !== "ENOENT") throw error;
  }
  return async () => {
    try {
      const bytes = await readFile(logFile);
      return bytes.subarray(Math.min(openOffset, bytes.length)).toString("utf8");
    } catch (error) {
      if (error?.code === "ENOENT") return "";
      throw error;
    }
  };
}

export async function openAssertionSession({
  label,
  openSession = () => Session.open(APP_BINARY),
  createLogReader,
  driverDiagnostics: driverDiagnosticsImpl = driverDiagnostics,
} = {}) {
  console.log(`  .. ${ASSERTION_SESSION_OPEN_PHRASE} (${label})`);
  if (typeof createLogReader !== "function") {
    throw new Error("openAssertionSession requires createLogReader");
  }
  const readLogSinceOpen = await createLogReader();
  try {
    return { session: await openSession(), readLogSinceOpen };
  } catch (error) {
    console.error(`  .. assertion WebDriver session failed: ${diagnosticText(error)}`);
    const driverResult = await collectIndependently(() =>
      driverDiagnosticsImpl ? driverDiagnosticsImpl() : "",
    );
    console.error(
      `  .. tauri-driver output:\n${
        driverResult.ok ? driverResult.value || "(empty)" : `unavailable (${driverResult.error})`
      }`,
    );
    const logResult = await collectIndependently(async () =>
      typeof readLogSinceOpen === "function" ? await readLogSinceOpen() : "",
    );
    console.error(
      `  .. preserved-profile application log:\n${
        logResult.ok ? logResult.value || "(empty)" : `unavailable (${logResult.error})`
      }`,
    );
    throw error;
  }
}

const failures = [];
const rootPermissionRestorations = new Map();
function restoreRootPermissions() {
  const errors = [];
  for (const [path, mode] of rootPermissionRestorations) {
    try {
      chmodSync(path, mode);
    } catch (cause) {
      errors.push(new Error(`permission restoration failed for ${path}`, { cause }));
      continue;
    }
    rootPermissionRestorations.delete(path);
  }
  if (errors.length)
    throw new AggregateError(errors, "RF9 disposable root permission restoration failed");
}
function restoreRootPermissionsForCleanup(context) {
  try {
    restoreRootPermissions();
  } catch (error) {
    console.error(`verify:app ${context} permission cleanup failed:`, error);
    process.exitCode = 1;
  }
}
const check = (condition, description, detail) => {
  console.log(`${condition ? "  ok  " : "FAIL  "}${description}`);
  if (!condition) {
    failures.push(description);
    if (detail) console.log(`      ${detail}`);
  }
};

async function assertion(label, action, report = check) {
  try {
    await action();
    report(true, label);
    return true;
  } catch (error) {
    report(false, label, error.message);
    return false;
  }
}

const PRACTICE_STORAGE_VERSION = 1;
const PRACTICE_SHARD_SEAL_BYTES = 128 * 1024;
const practiceStateKey = (fen) => fen.split(" ").slice(0, 4).join(" ");
const sha256 = (value) => createHash("sha256").update(value).digest("hex");
const practiceDeckHash = (fileId, game) => sha256(`${fileId}\0${game}`);
const practiceMoveUci = (move) =>
  `${makeSquare(move.from)}${makeSquare(move.to)}${move.promotion ?? ""}`;

function practiceLegalMoves(position) {
  const moves = [];
  for (const [from, destinations] of position.allDests()) {
    if (destinations.isEmpty()) continue;
    const piece = position.board.get(from);
    for (const to of destinations) {
      const move = { from, to };
      if (piece?.role === "pawn" && (to >= 56 || to < 8)) move.promotion = "queen";
      moves.push(move);
    }
  }
  return moves;
}

function buildPracticeFixtureTree() {
  let randomState = 0x4f1a2b3c;
  const nextRandom = () => {
    randomState = (Math.imul(randomState, 1664525) + 1013904223) >>> 0;
    return randomState / 4294967296;
  };
  const movesFor = (position, seen) => {
    const moves = practiceLegalMoves(position).filter((move) => !position.board.get(move.to));
    moves.sort(() => nextRandom() - 0.5);
    return moves.filter((move) => {
      const next = position.clone();
      next.play(move);
      return !seen.has(practiceStateKey(makeFen(next.toSetup())));
    });
  };
  const makeNode = (position, move) => {
    const next = position.clone();
    const san = makeSan(next, move);
    next.play(move);
    return { position: next, san, children: [] };
  };
  const setup = parseFen("7k/6rr/8/8/8/8/RR6/K7 w - - 0 1").unwrap();
  const root = { position: Chess.fromSetup(setup).unwrap(), children: [] };
  const seen = new Set([practiceStateKey(makeFen(root.position.toSetup()))]);
  // buildFromTree excludes the root when the repertoire has no explicit start path.
  const target = 12_501;
  const whiteNodes = [root];
  let cards = 0;
  // Breadth-first keeps the RAV tree shallow enough for tab persistence. Each white node has one
  // answer; each black node contributes at most two unseen replies (two is within the plan's
  // four-reply ceiling and keeps the generated tree close to the measured 30k-node fixture).
  for (let index = 0; index < whiteNodes.length && cards < target; index += 1) {
    const whiteNode = whiteNodes[index];
    const answer = movesFor(whiteNode.position, seen)[0];
    if (!answer) continue;
    const blackNode = makeNode(whiteNode.position, answer);
    whiteNode.children = [blackNode];
    const blackKey = practiceStateKey(makeFen(blackNode.position.toSetup()));
    seen.add(blackKey);
    cards += 1;
    const replies = movesFor(blackNode.position, seen).slice(0, 2);
    for (const reply of replies) {
      const child = makeNode(blackNode.position, reply);
      blackNode.children.push(child);
      seen.add(practiceStateKey(makeFen(child.position.toSetup())));
      whiteNodes.push(child);
    }
  }
  if (cards !== target) throw new Error(`could not extend practice fixture to ${target} cards`);
  return root;
}

function clonePracticeFixtureTree(node) {
  const clone = {
    position: node.position.clone(),
    san: node.san,
    children: [],
  };
  const pending = [[node, clone]];
  while (pending.length > 0) {
    const [source, target] = pending.pop();
    for (const child of source.children) {
      const childClone = { position: child.position.clone(), san: child.san, children: [] };
      target.children.push(childClone);
      pending.push([child, childClone]);
    }
  }
  return clone;
}

function collectPracticePositions(root) {
  // Independent oracle: keep expected fixture cards separate from the product's opening.ts logic.
  const seen = new Set();
  const positions = [];
  const visit = (node) => {
    const fen = makeFen(node.position.toSetup());
    const key = practiceStateKey(fen);
    if (
      node !== root &&
      node.children.length > 0 &&
      node.position.turn === "white" &&
      !seen.has(key)
    ) {
      seen.add(key);
      const firstMove = node.children[0];
      positions.push({
        fen,
        answer: firstMove.san,
        uci: practiceMoveUciFromNodes(node, firstMove),
      });
    }
    for (let index = node.children.length - 1; index >= 0; index -= 1) {
      pending.push(node.children[index]);
    }
  };
  const pending = [root];
  while (pending.length > 0) visit(pending.pop());
  return positions;
}

function practiceMoveUciFromNodes(parent, child) {
  const move = practiceLegalMoves(parent.position).find(
    (candidate) => makeSan(parent.position, candidate) === child.san,
  );
  if (!move) throw new Error(`could not resolve fixture move ${child.san}`);
  return practiceMoveUci(move);
}

function prunePracticeFixtureTree(root, count) {
  const orderedCards = [];
  const seen = new Set();
  const pending = [root];
  while (pending.length > 0) {
    const node = pending.pop();
    const fen = makeFen(node.position.toSetup());
    const key = practiceStateKey(fen);
    if (
      node !== root &&
      node.children.length > 0 &&
      node.position.turn === "white" &&
      !seen.has(key)
    ) {
      seen.add(key);
      orderedCards.push(node);
    }
    for (let index = node.children.length - 1; index >= 0; index -= 1) {
      pending.push(node.children[index]);
    }
  }
  const retainedCards = orderedCards.slice(0, count);
  const kept = new Set(retainedCards);
  const keep = new Map();
  const postorder = [{ node: root, visited: false }];
  while (postorder.length > 0) {
    const frame = postorder.pop();
    if (frame.visited) {
      const retain = kept.has(frame.node) || frame.node.children.some((child) => keep.get(child));
      keep.set(frame.node, retain);
      frame.node.children = frame.node.children.filter(
        (child, index) => (kept.has(frame.node) && index === 0) || keep.get(child),
      );
    } else {
      postorder.push({ node: frame.node, visited: true });
      for (const child of frame.node.children) postorder.push({ node: child, visited: false });
    }
  }
  return retainedCards.map((node) => ({
    fen: makeFen(node.position.toSetup()),
    answer: node.children[0].san,
    uci: practiceMoveUciFromNodes(node, node.children[0]),
  }));
}

function practicePgn(root) {
  const emit = (node) => {
    if (node.children.length === 0) return "";
    let result = ` ${node.children[0].san}`;
    for (const alternative of node.children.slice(1)) result += ` (${emitLine(alternative)})`;
    return result + emit(node.children[0]);
  };
  const emitLine = (node) => `${node.san}${emit(node)}`;
  const fen = makeFen(root.position.toSetup());
  return `[Event "verify:practice"]\n[Site "verify:app"]\n[SetUp "1"]\n[FEN "${fen}"]\n[Result "*"]\n\n${emit(root)} *\n`;
}

function emptyPracticeCard() {
  return { ...createEmptyCard(), due: new Date("2026-01-01T00:00:00.000Z").toISOString() };
}

function practicePositionsDocument(positions) {
  return positions.map(({ fen, answer, weight }) => ({
    fen,
    answer,
    card: emptyPracticeCard(),
    ...(typeof weight === "number" ? { weight } : {}),
  }));
}

async function seedNativePracticeDeck(practiceDirectory, fileId, game, positions, reviewCount) {
  const hash = practiceDeckHash(fileId, game);
  const entries = Array.from({ length: reviewCount }, (_, index) => {
    const entry = { index, kind: "seed" };
    return { id: `seed-review-${String(index).padStart(6, "0")}`, rev: index + 1, entry };
  });
  const shards = [];
  let current = {
    version: PRACTICE_STORAGE_VERSION,
    fileId,
    game,
    generation: 0,
    ordinal: 0,
    entries: [],
  };
  for (const entry of entries) {
    const candidate = { ...current, entries: [...current.entries, entry] };
    if (
      current.entries.length > 0 &&
      Buffer.byteLength(JSON.stringify(candidate)) > PRACTICE_SHARD_SEAL_BYTES
    ) {
      shards.push(current);
      current = { ...current, ordinal: current.ordinal + 1, entries: [entry] };
    } else {
      current = candidate;
    }
  }
  if (current.entries.length > 0) shards.push(current);
  // Exercise fifty automatic review writes without depending on the session's new-move limit.
  const positionValues = practicePositionsDocument(positions).map((position, index) =>
    index < 50 ? { ...position, card: { ...position.card, reps: 1 } } : position,
  );
  const lastEntry = entries.at(-1);
  const envelope = {
    version: PRACTICE_STORAGE_VERSION,
    fileId,
    game,
    revision: reviewCount,
    generation: 0,
    lastEntryId: lastEntry.id,
    lastEntryDigest: sha256(JSON.stringify(lastEntry.entry)),
    appliedEntries: reviewCount,
    orphanEntries: 0,
    orphanAcknowledgedCount: 0,
    legacySource: "none",
    migratedAt: null,
    migratedEntries: null,
    migratedPositionsDigest: null,
    positions: positionValues,
  };
  await mkdir(practiceDirectory, { recursive: true });
  await writeFile(join(practiceDirectory, `${hash}-positions.json`), JSON.stringify(envelope));
  for (const shard of shards) {
    await writeFile(
      join(practiceDirectory, `${hash}-g0-reviews-${shard.ordinal}.json`),
      JSON.stringify(shard),
    );
  }
  return { positions: positionValues, reviewIds: entries.map(({ id }) => id) };
}

async function seedRendererLocalStorage(session, items) {
  await session.execute(
    `for (const [key, value] of Object.entries(arguments[0])) localStorage.setItem(key, value);
     return true`,
    [items],
  );
}

async function pathAuthorityEntry(id, displayName, nativePath, purpose, operations, targetIsDir) {
  const metadata = await stat(nativePath, { bigint: true });
  return {
    id: { id },
    display_name: displayName,
    class: targetIsDir ? "persistentCustomRoot" : "persistentFile",
    operations,
    path: {
      platform: "unix",
      bytes: Buffer.from(nativePath).toString("base64").replace(/=+$/, ""),
    },
    identity: { a: Number(metadata.dev), b: Number(metadata.ino) },
    target_is_dir: targetIsDir,
    purpose,
  };
}

function findRunningApplication(label) {
  const running = appProcesses();
  const application = running.find(({ cmd }) => cmd.includes(APP_BINARY));
  if (!application) throw new Error(`${label} application process was not running`);
  const webkitServicePids = running
    .filter(
      ({ ppid, cmd }) =>
        ppid === application.pid && /WebKitWebProcess|WebKitNetworkProcess/.test(cmd),
    )
    .map(({ pid }) => pid);
  return {
    application,
    webkitServicePids,
    trackedPids: [application.pid, ...webkitServicePids],
    running,
  };
}

async function requestCloseThroughTitlebar(session, label) {
  await waitFor(`${label} window controls`, () =>
    session.execute(closeControlProbe).catch(() => false),
  );
  const { application, webkitServicePids, trackedPids, running } = findRunningApplication(label);
  await session.execute(closeControlAction);
  return { application, webkitServicePids, trackedPids, running };
}

async function closeApplicationThroughTitlebar(session, label) {
  const { application, webkitServicePids, trackedPids, running } =
    await requestCloseThroughTitlebar(session, label);
  const gone = await waitFor(
    `${label} application pid ${application.pid} and recorded WebKit service pids to exit`,
    () => trackedPids.every((pid) => !processExists(pid)),
    { timeoutMs: 30_000 },
  ).catch(() => false);
  return {
    application,
    webkitServicePids,
    running,
    gone,
    survivors: trackedPids.filter(processExists),
  };
}

const quitConfirmDialogProbe = `(() => {
  const dialog = [...document.querySelectorAll('[role="dialog"]')].find((node) =>
    node.innerText.includes("Unsaved changes"),
  );
  if (!dialog) return false;
  const quit = [...dialog.querySelectorAll("button")].find(
    (node) => node.textContent.trim() === "Quit without saving",
  );
  return quit ? dialog : false;
})()`;

async function decodeWorkspaceActiveTabTree(session, rawWorkspace) {
  const workspace = rawWorkspace && deserializeStorageValue(rawWorkspace);
  if (!workspace || !Array.isArray(workspace.tabs)) {
    return { workspace: null, tabs: [], tab: null, treeKey: null, tree: null };
  }
  const tab = workspace.tabs.find((entry) => entry.value === workspace.activeTab) ?? null;
  const treeKey = tab ? (tab.treeKey ?? tab.value) : null;
  const rawTree =
    typeof treeKey === "string"
      ? await session.execute("return sessionStorage.getItem(arguments[0])", [treeKey])
      : null;
  const tree = rawTree && deserializeStorageValue(rawTree)?.state;
  return { workspace, tabs: workspace.tabs, tab, treeKey, tree };
}

async function readActiveTabTree(session) {
  const observed = await session.execute(`return {
    rawWorkspace: sessionStorage.getItem("workspace"),
    keys: Object.keys(sessionStorage),
  };`);
  const decoded = await decodeWorkspaceActiveTabTree(session, observed.rawWorkspace);
  if (!decoded.workspace) return { workspace: null, tab: null, tree: null };
  return {
    workspace: decoded.workspace,
    tab: decoded.tab,
    tree: decoded.tree,
    treeKey: decoded.treeKey,
    sessionKeys: observed.keys,
  };
}

/** Open the Info-tab PGN editor, replace its text, and click Update. */
async function updateActiveTreePgnInEditor(
  session,
  nextPgnOrBuilder,
  {
    locate = (label, script, args) => reachableStableCoordinates(session, label, script, args),
    wait = (label, script, args = []) => waitFor(label, () => session.execute(script, args)),
    keyboardId = "quit-gate-keyboard",
    beforeRead,
    readyLabel = "real PGN editor edit",
    diagnoseEditorValue = false,
  } = {},
) {
  const info = await locate(
    "Info tab",
    `[...document.querySelectorAll('[role="tab"]')].find(node => node.textContent.trim() === 'Info')`,
  );
  await clickAt(session, info.x, info.y);
  await locate("PGN editor", `document.querySelector('#pgn-editor')`);
  if (beforeRead) await beforeRead();
  const editedPgn =
    typeof nextPgnOrBuilder === "function"
      ? nextPgnOrBuilder(
          await session.execute("return document.querySelector('#pgn-editor').value"),
        )
      : nextPgnOrBuilder;
  const editor = await session.call("POST", "/element", {
    using: "css selector",
    value: "#pgn-editor",
  });
  const editorId = encodeURIComponent(editor["element-6066-11e4-a52e-4f735466cecf"]);
  const editorPosition = await locate(
    "focused PGN editor",
    `document.querySelector('#pgn-editor')`,
  );
  await clickAt(session, editorPosition.x, editorPosition.y);
  await wait("real PGN editor focus", "return document.activeElement?.id === 'pgn-editor'");
  await session.call("POST", "/actions", {
    actions: [
      {
        type: "key",
        id: keyboardId,
        actions: [
          { type: "keyDown", value: "\uE009" },
          { type: "keyDown", value: "a" },
          { type: "keyUp", value: "a" },
          { type: "keyUp", value: "\uE009" },
          { type: "keyDown", value: "\uE003" },
          { type: "keyUp", value: "\uE003" },
        ],
      },
    ],
  });
  await wait(
    "real PGN editor keyboard replacement clears the text",
    "return document.querySelector('#pgn-editor')?.value === ''",
  );
  // WebKitGTK's element/value drops LF characters, so enter every line break as a key.
  for (const [index, line] of editedPgn.split("\n").entries()) {
    if (index > 0)
      await session.call("POST", "/actions", {
        actions: [
          {
            type: "key",
            id: keyboardId,
            actions: [
              { type: "keyDown", value: "\uE007" },
              { type: "keyUp", value: "\uE007" },
            ],
          },
        ],
      });
    if (line) await session.call("POST", `/element/${editorId}/value`, { text: line });
  }
  const editorReady = wait(
    readyLabel,
    "return document.querySelector('#pgn-editor')?.value === arguments[0]",
    [editedPgn],
  );
  await (diagnoseEditorValue
    ? editorReady.catch(async (error) => {
        const actual = await session
          .execute("return document.querySelector('#pgn-editor')?.value ?? null")
          .catch((diagnosticError) => `unavailable: ${diagnosticError.message}`);
        throw new Error(
          `${error.message}, actual value: ${JSON.stringify(actual)}, expected length: ${editedPgn.length}`,
          { cause: error },
        );
      })
    : editorReady);
  const update = await locate(
    "PGN Update",
    `[...document.querySelectorAll('button')].find(node => node.textContent.trim() === 'Update' && node.parentElement.querySelector('#pgn-editor'))`,
  );
  await clickAt(session, update.x, update.y);
}

/** Open the Info-tab PGN editor, replace the Event header, Update, and wait until the tree is dirty. */
async function dirtyActiveTreeEventHeader(
  session,
  event,
  {
    locate,
    wait,
    keyboardId = "quit-gate-keyboard",
    missingHeaderError = "active tree has no Event header",
    beforeRead,
    diagnoseEditorValue = false,
    waitForDirty,
  } = {},
) {
  await updateActiveTreePgnInEditor(
    session,
    (originalPgn) => {
      const eventHeader = /^\[Event "[^"\r\n]*"\]/m;
      if (!eventHeader.test(originalPgn)) throw new Error(missingHeaderError);
      return originalPgn.replace(eventHeader, `[Event "${event}"]`);
    },
    {
      locate,
      wait,
      keyboardId,
      beforeRead,
      readyLabel: "real PGN editor Event edit",
      diagnoseEditorValue,
    },
  );
  if (waitForDirty) return waitForDirty();
  return waitFor(
    "real PGN Update publishes the unsaved Event edit",
    async () => {
      const snapshot = await readActiveTabTree(session);
      return snapshot.tree?.dirty === true && snapshot.tree.headers?.event === event
        ? snapshot
        : false;
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
}

async function openRestoreSession(label) {
  const session = await Session.open(APP_BINARY);
  await waitFor(`the ${label} renderer to expose Tauri`, () =>
    session.execute("return typeof window.__TAURI_INTERNALS__ === 'object'").catch(() => false),
  );
  await waitFor(`the ${label} renderer to mount its window controls`, () =>
    session.execute(closeControlProbe).catch(() => false),
  );
  return session;
}

async function releaseSession(session, label) {
  const released = await session.quit();
  if (!released.released)
    console.log(`  .. ${label} WebDriver session release returned: ${released.error}`);
}

/** Extract the mainline SAN move list from a persisted tree root. */
export function mainlineMovesFromTree(root) {
  const moves = [];
  let node = root;
  while (node?.children?.[0]) {
    node = node.children[0];
    if (typeof node.san === "string") moves.push(node.san);
  }
  return moves;
}

/** Return the node at `path` inside `root`, or `null` when absent. */
export function treeNodeAtPath(root, path) {
  let node = root;
  for (const index of Array.isArray(path) ? path : []) {
    node = node?.children?.[index];
    if (!node) return null;
  }
  return node ?? null;
}

/** Compare a live workspace snapshot against the expected tabs, order, active tab, moves and current move. */
export function evaluateWorkspaceRestoreSnapshot(snapshot, expected) {
  const actualOrder = snapshot.tabs.map((tab) => tab.value);
  const actualTypes = snapshot.tabs.map((tab) => tab.type);
  const domOrder = snapshot.domTabs.map((tab) => tab.id);
  const domSelected = snapshot.domTabs.filter((tab) => tab.selected).map((tab) => tab.id);
  return {
    tabsAndOrder: {
      ok:
        JSON.stringify(actualOrder) === JSON.stringify(expected.tabOrder) &&
        JSON.stringify(domOrder) === JSON.stringify(expected.tabOrder) &&
        JSON.stringify(actualTypes) === JSON.stringify(expected.tabTypes),
      detail:
        `expected order=${JSON.stringify(expected.tabOrder)} types=${JSON.stringify(expected.tabTypes)}; ` +
        `got storage=${JSON.stringify(actualOrder)} dom=${JSON.stringify(domOrder)} types=${JSON.stringify(actualTypes)}`,
    },
    activeTab: {
      ok:
        snapshot.workspace?.activeTab === expected.activeTab &&
        domSelected.length === 1 &&
        domSelected[0] === expected.activeTab,
      detail: `expected=${expected.activeTab}; got storage=${snapshot.workspace?.activeTab} dom=${JSON.stringify(domSelected)}`,
    },
    moveList: {
      ok:
        JSON.stringify(snapshot.moves) === JSON.stringify(expected.moves) &&
        snapshot.panelText.includes(expected.notation) &&
        snapshot.tree?.dirty === true,
      detail:
        `expected=${JSON.stringify(expected.moves)} (${expected.notation}); ` +
        `got=${JSON.stringify(snapshot.moves)} dirty=${snapshot.tree?.dirty}`,
    },
    currentMove: {
      ok:
        JSON.stringify(snapshot.position) === JSON.stringify(expected.position) &&
        snapshot.currentMoveSan === expected.currentMoveSan &&
        snapshot.currentMoveText === expected.currentMoveSan,
      detail:
        `expected pos=${JSON.stringify(expected.position)} san=${expected.currentMoveSan}; ` +
        `got pos=${JSON.stringify(snapshot.position)} san=${snapshot.currentMoveSan} dom=${JSON.stringify(snapshot.currentMoveText)}`,
    },
  };
}

async function readWorkspaceSnapshot(session) {
  const observed = await session.execute(`
    const tablist = document.querySelector('header [role="tablist"]');
    const tabNodes = [...(tablist?.querySelectorAll('[role="tab"]') ?? [])];
    const domTabs = tabNodes.map((node) => ({
      id: node.getAttribute('data-tab-id') || node.id.replace(/^board-tab-/, ''),
      selected: node.getAttribute('aria-selected') === 'true',
    }));
    const selectedDomTab = domTabs.find((entry) => entry.selected) ?? null;
    const panel = selectedDomTab
      ? document.getElementById('board-tab-panel-' + selectedDomTab.id)
      : null;
    const currentMoveCell = panel?.querySelector('[data-notation-current="true"] button[aria-current="true"]');
    return {
      path: location.pathname,
      readyState: document.readyState,
      rawWorkspace: sessionStorage.getItem('workspace'),
      domTabs,
      hasBoard: Boolean(panel?.querySelector('cg-board')),
      panelText: panel ? panel.innerText.replace(/\\s+/g, '') : '',
      currentMoveText: currentMoveCell ? currentMoveCell.textContent.trim() : null,
    };
  `);
  const decoded = await decodeWorkspaceActiveTabTree(session, observed.rawWorkspace);
  return {
    ...observed,
    workspace: decoded.workspace,
    tabs: decoded.tabs,
    activeTab: decoded.tab,
    treeKey: decoded.treeKey,
    tree: decoded.tree,
    moves: decoded.tree?.root ? mainlineMovesFromTree(decoded.tree.root) : [],
    position: Array.isArray(decoded.tree?.position) ? decoded.tree.position : null,
    currentMoveSan: decoded.tree?.root
      ? (treeNodeAtPath(decoded.tree.root, decoded.tree.position)?.san ?? null)
      : null,
  };
}

async function assertRestoredWorkspace(session, scenarioLabel, expected) {
  const snapshot = await waitFor(
    `${scenarioLabel} restored workspace to render`,
    async () => {
      const current = await readWorkspaceSnapshot(session).catch(() => null);
      if (
        !current ||
        current.readyState !== "complete" ||
        current.path !== "/" ||
        current.domTabs.length === 0 ||
        !current.domTabs.some((tab) => tab.selected)
      ) {
        return false;
      }
      if (
        current.activeTab?.value === expected.activeTab &&
        expected.currentMoveSan &&
        (!current.hasBoard || current.currentMoveText === null)
      ) {
        return false;
      }
      return current;
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  const verdicts = evaluateWorkspaceRestoreSnapshot(snapshot, expected);
  check(
    verdicts.tabsAndOrder.ok,
    `restore (${scenarioLabel}): restores the same tabs and tab order`,
    verdicts.tabsAndOrder.detail,
  );
  check(
    verdicts.activeTab.ok,
    `restore (${scenarioLabel}): restores the same active tab`,
    verdicts.activeTab.detail,
  );
  check(
    verdicts.moveList.ok,
    `restore (${scenarioLabel}): restores the same move list (still dirty)`,
    verdicts.moveList.detail,
  );
  check(
    verdicts.currentMove.ok,
    `restore (${scenarioLabel}): restores the same current move`,
    verdicts.currentMove.detail,
  );
  return snapshot;
}

async function killApplicationWithSignal(label, signal) {
  const { application, trackedPids } = findRunningApplication(label);
  process.kill(application.pid, signal);
  return waitFor(
    `${label} application and its WebKit processes to exit after ${signal}`,
    () => trackedPids.every((pid) => !processExists(pid)),
    { timeoutMs: 30_000 },
  )
    .then(() => true)
    .catch(() => {
      for (const pid of trackedPids.filter(processExists)) {
        try {
          process.kill(pid, "SIGKILL");
        } catch {
          // Process exited between the survival check and fallback kill.
        }
      }
      return false;
    });
}

/**
 * Real-app workspace-restore verification against `<app_data>/workspace-session/`:
 * (a) titlebar close with no quit dialog, (b) SIGTERM, (c) SIGKILL >= 2 s after last edit,
 * and (discard) "Close without saving" deletes the leaf so the tab does not come back.
 */
async function verifyWorkspaceRestore(profileDirectory) {
  const store = join(profileDirectory, ".local/share/com.chessriddle.studio/workspace-session");
  const leafPath = (key) => join(store, `${key}.json`);
  const readStoredTreeLeaf = async (key) => {
    const raw = await readFile(leafPath(key), "utf8").catch(() => null);
    return raw ? (deserializeStorageValue(raw)?.state ?? null) : null;
  };

  console.log(
    "  .. restore: opening Analysis Board, playing moves, opening second tab, selecting first",
  );
  const first = await openRestoreSession("restore-setup");
  await clickButton(first, "Analysis Board");
  await waitFor(
    "origin-none analysis board",
    async () => {
      const snapshot = await readWorkspaceSnapshot(first);
      return (
        snapshot.activeTab?.type === "analysis" &&
        snapshot.activeTab.gameOrigin?.kind === "none" &&
        !!snapshot.tree &&
        snapshot.hasBoard
      );
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  for (const [index, uci] of ["e2e4", "e7e5", "d2d4"].entries()) {
    await clickBoardMove(first, uci, index + 1);
  }
  await clickButton(first, "Previous move", true);
  await waitFor(
    "current move stepped back to 1... e5",
    async () => {
      const snapshot = await readWorkspaceSnapshot(first);
      return (
        JSON.stringify(snapshot.position) === JSON.stringify([0, 0]) &&
        snapshot.currentMoveSan === "e5" &&
        snapshot.currentMoveText === "e5"
      );
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  const newTabButton = await reachableStableCoordinates(
    first,
    "New Tab",
    `document.querySelector('header button[aria-label="New Tab"]')`,
  );
  await clickAt(first, newTabButton.x, newTabButton.y);
  const twoTabs = await waitFor(
    "second tab opened and selected",
    async () => {
      const snapshot = await readWorkspaceSnapshot(first);
      return snapshot.tabs.length === 2 &&
        snapshot.domTabs.length === 2 &&
        snapshot.activeTab?.value === snapshot.tabs[1].value
        ? snapshot
        : false;
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  const firstTabId = twoTabs.tabs[0].value;
  const secondTabId = twoTabs.tabs[1].value;
  const firstTabControl = await reachableStableCoordinates(
    first,
    "first workspace tab",
    `document.getElementById(${JSON.stringify(`board-tab-${firstTabId}`)})`,
  );
  await clickAt(first, firstTabControl.x, firstTabControl.y);
  const setupSnapshot = await waitFor(
    "first workspace tab selected with current move e5",
    async () => {
      const snapshot = await readWorkspaceSnapshot(first);
      return snapshot.activeTab?.value === firstTabId &&
        snapshot.hasBoard &&
        snapshot.currentMoveText === "e5"
        ? snapshot
        : false;
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  const expected = {
    tabOrder: [firstTabId, secondTabId],
    tabTypes: ["analysis", "new"],
    activeTab: firstTabId,
    firstTabTreeKey: setupSnapshot.treeKey,
    moves: ["e4", "e5", "d4"],
    notation: "1.e4e52.d4",
    position: [0, 0],
    currentMoveSan: "e5",
  };
  check(
    setupSnapshot.tree?.dirty === true &&
      JSON.stringify(setupSnapshot.moves) === JSON.stringify(expected.moves),
    "restore (setup): Analysis Board has 3 dirty moves, 2 tabs, and first tab active at 1... e5",
    `tabs=${JSON.stringify(expected.tabOrder)} active=${setupSnapshot.activeTab?.value} dirty=${setupSnapshot.tree?.dirty}`,
  );

  console.log("  .. restore (a): closing through titlebar with no quit dialog");
  const requested = await requestCloseThroughTitlebar(first, "restore-titlebar-close");
  let dialogSeen = false;
  const closed = await waitFor(
    "the window to close without a quit dialog",
    async () => {
      if (await first.execute(`return !!${quitConfirmDialogProbe}`).catch(() => false)) {
        dialogSeen = true;
      }
      return requested.trackedPids.every((pid) => !processExists(pid));
    },
    { timeoutMs: 30_000 },
  ).catch(() => false);
  check(
    !!closed && !dialogSeen,
    "restore (a): titlebar close with dirty workspace quits without quit dialog",
    dialogSeen ? "the quit dialog appeared" : undefined,
  );
  await releaseSession(first, "restore-titlebar-close");
  check(
    existsSync(join(store, "workspace.json")) && existsSync(leafPath(expected.firstTabTreeKey)),
    "restore (a): workspace-session/ holds workspace.json and the tab tree leaf after titlebar close",
  );

  console.log("  .. restore (a): restarting after titlebar close");
  const second = await openRestoreSession("restore-after-titlebar-close");
  await assertRestoredWorkspace(second, "a: after titlebar close", expected);

  console.log("  .. restore (b): sending SIGTERM to the running application");
  check(
    await killApplicationWithSignal("restore-sigterm", "SIGTERM"),
    "restore (b): application and WebKit processes exit on SIGTERM",
  );
  await releaseSession(second, "restore-sigterm");

  console.log("  .. restore (b): restarting after SIGTERM");
  const third = await openRestoreSession("restore-after-sigterm");
  await assertRestoredWorkspace(third, "b: after SIGTERM", expected);

  console.log("  .. restore (c): making a new edit, waiting >= 2 s, then sending SIGKILL");
  await clickButton(third, "Next move", true);
  await waitFor(
    "cursor moved to 2. d4 before playing 2... d5",
    async () => {
      const snapshot = await readWorkspaceSnapshot(third);
      return JSON.stringify(snapshot.position) === JSON.stringify([0, 0, 0]);
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  await clickBoardMove(third, "d7d5", 4);
  await clickButton(third, "Previous move", true);
  const lastEditAt = Date.now();
  await waitFor(
    "new edit (2... d5) with current move at 2. d4 in sessionStorage and DOM",
    async () => {
      const snapshot = await readWorkspaceSnapshot(third);
      return (
        JSON.stringify(snapshot.moves) === JSON.stringify(["e4", "e5", "d4", "d5"]) &&
        JSON.stringify(snapshot.position) === JSON.stringify([0, 0, 0]) &&
        snapshot.currentMoveSan === "d4" &&
        snapshot.currentMoveText === "d4"
      );
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  const remainingWaitMs = Math.max(
    0,
    WORKSPACE_RESTORE_SIGKILL_WAIT_MS - (Date.now() - lastEditAt),
  );
  if (remainingWaitMs > 0) await sleep(remainingWaitMs);
  const elapsedSinceEditMs = Date.now() - lastEditAt;
  const leafBeforeKill = await readStoredTreeLeaf(expected.firstTabTreeKey);
  check(
    elapsedSinceEditMs >= WORKSPACE_RESTORE_SIGKILL_MIN_AGE_MS &&
      JSON.stringify(mainlineMovesFromTree(leafBeforeKill?.root)) ===
        JSON.stringify(["e4", "e5", "d4", "d5"]) &&
      JSON.stringify(leafBeforeKill?.position) === JSON.stringify([0, 0, 0]),
    "restore (c): durable leaf on disk captured the latest edit before SIGKILL, >= 2 s after it",
    `elapsedMs=${elapsedSinceEditMs} leafMoves=${JSON.stringify(mainlineMovesFromTree(leafBeforeKill?.root))} leafPos=${JSON.stringify(leafBeforeKill?.position)}`,
  );
  expected.moves = ["e4", "e5", "d4", "d5"];
  expected.notation = "1.e4e52.d4d5";
  expected.position = [0, 0, 0];
  expected.currentMoveSan = "d4";

  check(
    await killApplicationWithSignal("restore-sigkill", "SIGKILL"),
    "restore (c): application and WebKit processes exit on SIGKILL",
  );
  await releaseSession(third, "restore-sigkill");

  console.log("  .. restore (c): restarting after SIGKILL");
  const fourth = await openRestoreSession("restore-after-sigkill");
  await assertRestoredWorkspace(fourth, "c: after SIGKILL", expected);

  console.log("  .. restore (discard): closing dirty tab via Close without saving");
  await closeSelectedWorkspaceTab(fourth);
  const discard = await reachableStableCoordinates(
    fourth,
    "Close without saving",
    `(() => {
      const dialog = [...document.querySelectorAll('[role="dialog"]')].find(node => node.innerText.includes('Unsaved changes'));
      return dialog && [...dialog.querySelectorAll('button')].find(node => node.textContent.trim() === 'Close without saving');
    })()`,
  );
  await clickAt(fourth, discard.x, discard.y);
  const leafGone = await waitFor(
    "discarded tab leaf to be removed from workspace-session/",
    async () => {
      const files = await readdir(store).catch(() => []);
      if (files.includes(`${expected.firstTabTreeKey}.json`)) return false;
      const raw = await readFile(join(store, "workspace.json"), "utf8").catch(() => null);
      const workspace = raw && deserializeStorageValue(raw);
      return (
        Array.isArray(workspace?.tabs) &&
        !workspace.tabs.some((tab) => tab.value === expected.activeTab)
      );
    },
  ).catch(() => false);
  check(
    !!leafGone,
    "restore (discard): Close without saving deletes the tab leaf and drops it from workspace.json",
  );
  const fourthClose = await closeApplicationThroughTitlebar(fourth, "restore-discard");
  if (!fourthClose.gone || fourthClose.survivors.length > 0) {
    throw new Error(
      `restore-discard processes survived close: ${fourthClose.survivors.join(", ")}`,
    );
  }
  await releaseSession(fourth, "restore-discard");

  console.log("  .. restore (discard): final restart confirms discarded tab does not return");
  const fifth = await openRestoreSession("restore-final");
  const finalSnapshot = await waitFor(
    "final workspace DOM to settle",
    async () => {
      const snapshot = await readWorkspaceSnapshot(fifth).catch(() => null);
      return snapshot?.readyState === "complete" &&
        snapshot.path === "/" &&
        snapshot.domTabs.length > 0 &&
        snapshot.domTabs.some((tab) => tab.selected)
        ? snapshot
        : false;
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  const finalFiles = await readdir(store).catch(() => []);
  check(
    !finalSnapshot.tabs.some((tab) => tab.value === expected.activeTab) &&
      !finalSnapshot.domTabs.some((tab) => tab.id === expected.activeTab) &&
      finalSnapshot.tabs.length === 1 &&
      finalSnapshot.tabs[0].value === secondTabId &&
      !finalFiles.includes(`${expected.firstTabTreeKey}.json`),
    "restore (discard): discarded dirty tab does not return and its leaf is gone",
    `tabs=${JSON.stringify(finalSnapshot.tabs.map((tab) => tab.value))} files=${JSON.stringify(finalFiles)}`,
  );
  const fifthClose = await closeApplicationThroughTitlebar(fifth, "restore-final");
  if (!fifthClose.gone || fifthClose.survivors.length > 0) {
    throw new Error(`restore-final processes survived close: ${fifthClose.survivors.join(", ")}`);
  }
  await releaseSession(fifth, "restore-final");
}

async function showLibraryOverview(session) {
  await waitFor(
    "Library overview navigation",
    () =>
      session.execute(`
    if (location.pathname === "/library") return true;
    const back = location.pathname.startsWith("/databases/") && document.querySelector('button[aria-label="Back"]');
    const link = document.querySelector('nav a[aria-label="Library"]');
    if (back) back.click();
    else if (link) link.click();
    return false;
  `),
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
}

async function databaseAlert(session, label) {
  const alert = await waitFor(
    label,
    async () => {
      await showLibraryOverview(session);
      return session.execute(
        `const alert = document.querySelector('[data-library-source="databases"] [role="alert"]');
         if (location.pathname !== "/library" || !alert) return false;
         return { message: alert.querySelector('p')?.textContent ?? null,
                  button: alert.querySelector('button')?.textContent?.trim() ?? null };`,
      );
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  let buttonDisplayed = false;
  if (alert.button === "Choose database folder") {
    const button = await session.call("POST", "/element", {
      using: "css selector",
      value: '[data-library-source="databases"] [role="alert"] button',
    });
    buttonDisplayed = await session.call(
      "GET",
      `/element/${encodeURIComponent(button["element-6066-11e4-a52e-4f735466cecf"])}/displayed`,
    );
  }
  return { ...alert, buttonDisplayed };
}

async function invokeAndWait(session, label, globalName, invokeExpression, successKey = "value") {
  const starterError = await session
    .execute(`
      window[${JSON.stringify(globalName)}] = null;
      (${invokeExpression}).then(
        value => { window[${JSON.stringify(globalName)}] = { [${JSON.stringify(successKey)}]: String(value) }; },
        error => { window[${JSON.stringify(globalName)}] = { rejected: typeof error === "object" ? JSON.stringify(error) : String(error) }; },
      );
      return true;
    `)
    .then(
      () => null,
      (error) => ({ error: error.message }),
    );
  if (starterError) return starterError;

  return await waitFor(
    label,
    () =>
      session
        .execute(`return window[${JSON.stringify(globalName)}] || false`)
        .catch((error) => ({ error: error.message })),
    { timeoutMs: IPC_PROBE_TIMEOUT_MS },
  ).catch((error) => ({ error: error.message }));
}

async function invokeJsonAndWait(session, label, globalName, invokeExpression) {
  const result = await invokeAndWait(
    session,
    label,
    globalName,
    `(${invokeExpression}).then(value => JSON.stringify(value))`,
    "json",
  );
  if (typeof result.json !== "string") return { result, value: undefined };
  try {
    return { result, value: JSON.parse(result.json) };
  } catch (error) {
    return { result, value: undefined, error: error.message };
  }
}

async function invokeIpc(session, globalName, command, args) {
  const result = await invokeJsonAndWait(
    session,
    command,
    globalName,
    `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)}, ${JSON.stringify(args)})`,
  );
  if (result.value === undefined)
    throw new Error(
      result.result.rejected ??
        result.result.error ??
        result.error ??
        `${command} returned no value`,
    );
  return result.value;
}

async function listFixtureEntries(invoke) {
  const listing = await invoke("list_file_workspace", {
    workspace: { id: { id: filesWorkspaceId }, kind: "fileWorkspace" },
    ticket: null,
  });
  return listing.entries;
}

function createWorkspacePgnFixture(invoke, workspace, name, pgn, type = "other") {
  return invoke("create_workspace_file", {
    workspace,
    parent: workspace,
    name,
    metadata: { type, tags: [] },
    content: { kind: "text", pgn },
  });
}

// WD0-WD7 exercise real release IPC against disposable Files inputs. No live engine is registered
// by this scenario. Native actor tests cover injected registry, sync and retirement failure paths.
// Root measured staging on 2026-10-22. Evidence directory:
// /tmp/build-fd2492e2-efa0-4ddf-9115-82d4cf3614a0. Each stage-<case>.exit is 1, the verifier's
// documented failure status. Each run used unchanged assertion code. An external Node debugger
// changed only harness-owned temporary filesystem inputs and restored them. Each stage log records
// its STAGE inputs restored marker.
// stage-registration.log moved the freshly created primary aside before registration. WD0 is its
// direct receipt. Later WD failures are dependencies, not additional direct receipts.
// stage-success.log removed the empty non-regular sidecar before real deletion IPC and restored it
// before listing. It directly fails WD1, WD2 and WD3 on the unexpected successful command. WD7's
// missing-rejection guard also fails. Two unrelated metadata assertions failed in that run and are
// not staging evidence. The later disk and listing runs did not repeat those failures.
// stage-disk.log recreated the primary immediately before WD4 and removed that recreation. It
// temporarily moved the unrelated fixture for WD5, then restored it. Exactly WD4 and WD5 fail and
// all other checks pass.
// stage-listing.log temporarily moved the owned workspace before the post-delete native listing
// and restored it before assertions. Exactly WD6 fails and all other checks pass.
// Each case's .exit records status 1. These exact check messages appear in the stage logs:
// FAIL  WD0 deletion fixture acquires a real registered handle before sidecar refusal
// FAIL  WD1 completed deletion rejects with a structured backend error
// FAIL  WD2 ordinary post-commit sidecar failure reports partial-removal
// FAIL  WD3 completed deletion reports exactly one removed primary target
// FAIL  WD4 post-commit rejection leaves the primary file deleted
// FAIL  WD5 post-commit deletion preserves the unrelated Files fixture
// FAIL  WD6 subsequent native listing excludes the deleted handle
// FAIL  WD7 serialized deletion rejection contains no private fixture path
// WD7's private-path leak branch is argued coverage. Sanitized native errors cannot contain a
// private path through a disposable filesystem input, so failing its missing-rejection guard does
// not stage a leak. Native wire-sanitization tests cover safe construction.
// WD3's wrong-numeric-count branch is not independently staged by filesystem input. Native
// physical-count tests cover it.
// native-old.log and native-old.exit show WD2 and WD3 failing with status 1 after the actual original
// Git workspace production hunks were restored, while all candidate tests stayed byte-identical.
// Exactly those two app checks failed. Root restored the exact source. This is the real-product
// revert witness, separate from the filesystem-only assertion matrix. After exact source
// restoration and rebuilding, native-restored.log reports all checks passed at exit 0. Every
// WD0-WD7 check passed and no metadata failure recurred. The canonical
// gate-native-revert.UjhVXT/completion.record records 0 native-revert
// 62f64d42c7b55bd510e437250fb52ba8a2435b01. Root inspected native-restored.png.
async function verifyWorkspaceDeletionOutcome(session, filesWorkspace) {
  const name = "verify-deletion-outcome";
  const primary = join(filesWorkspace, `${name}.pgn`);
  let sidecar = join(filesWorkspace, `${name}.info`);
  let trashedPrimary;
  const unrelated = join(filesWorkspace, `${filesRowName}.pgn`);
  const workspace = { id: { id: filesWorkspaceId }, kind: "fileWorkspace" };
  const invokeListing = `window.__TAURI_INTERNALS__.invoke("list_file_workspace", { workspace: ${JSON.stringify(workspace)}, ticket: null })`;
  console.log(`  .. deletion disposable inputs: ${primary}, ${sidecar}, ${unrelated}`);
  let entry;
  let setupError;
  let deletion = {};
  let rejection;
  let listing;
  try {
    await writeFile(primary, filesGamePgn);
    const before = await invokeJsonAndWait(
      session,
      "workspace deletion fixture registration",
      "__verifyAppDeletionBefore",
      invokeListing,
    );
    entry = before.value?.entries?.find((candidate) => candidate.name === name);
    if (!entry?.handle?.id?.id)
      throw new Error(`fixture handle unavailable: ${JSON.stringify(before)}`);
    const trashed = await invokeAndWait(
      session,
      "workspace deletion fixture trash",
      "__verifyAppDeletionTrash",
      `window.__TAURI_INTERNALS__.invoke("trash_workspace_entry", { workspace: ${JSON.stringify(workspace)}, entry: ${JSON.stringify(entry.handle)} })`,
    );
    if (typeof trashed.value !== "string" || !/^[0-9a-f-]{36}$/.test(trashed.value))
      throw new Error(`trash item unavailable: ${JSON.stringify(trashed)}`);
    sidecar = join(filesWorkspace, ".en-croissant-trash", trashed.value, `${name}.info`);
    trashedPrimary = join(filesWorkspace, ".en-croissant-trash", trashed.value, `${name}.pgn`);
    // Corrupt only the disposable sidecar after the real move has committed.
    await rm(sidecar, { force: true });
    await mkdir(sidecar);
    deletion = await invokeAndWait(
      session,
      "workspace deletion outcome",
      "__verifyAppDeletionOutcome",
      `window.__TAURI_INTERNALS__.invoke("delete_workspace_trash_item", { workspace: ${JSON.stringify(workspace)}, item: ${JSON.stringify(trashed.value)} })`,
    );
    if (typeof deletion.rejected === "string") {
      try {
        rejection = JSON.parse(deletion.rejected);
      } catch {
        // The rejection assertions below also reject an unstructured backend failure.
      }
    }
    listing = await invokeJsonAndWait(
      session,
      "workspace deletion reconciliation listing",
      "__verifyAppDeletionAfter",
      invokeListing,
    );
  } catch (error) {
    setupError = error.message;
  }
  const detail = setupError ?? deletion.rejected ?? deletion.error;
  check(
    !setupError && !!entry?.handle?.id?.id,
    "WD0 deletion fixture acquires a real registered handle before sidecar refusal",
    detail,
  );
  check(
    rejection?.tag === "backend-error",
    "WD1 completed deletion rejects with a structured backend error",
    detail,
  );
  check(
    rejection?.category === "partial-removal",
    "WD2 ordinary post-commit sidecar failure reports partial-removal",
    detail,
  );
  check(
    rejection?.message ===
      "Partially removed: 1 entries were deleted before failing: invalid input" ||
      rejection?.message ===
        "Partially removed: 1 entries were deleted before failing: I/O failure",
    "WD3 completed deletion reports exactly one removed primary target",
    detail,
  );
  check(
    !setupError && !existsSync(primary) && !existsSync(trashedPrimary),
    "WD4 post-commit rejection leaves the primary file deleted",
    detail,
  );
  check(existsSync(unrelated), "WD5 post-commit deletion preserves the unrelated Files fixture");
  check(
    !!entry?.handle?.id?.id &&
      Array.isArray(listing?.value?.entries) &&
      !listing.value.entries.some((candidate) => candidate.handle?.id?.id === entry.handle.id.id),
    "WD6 subsequent native listing excludes the deleted handle",
    setupError ?? listing?.result?.rejected ?? listing?.result?.error,
  );
  check(
    rejection?.tag === "backend-error" &&
      !deletion.rejected.includes(filesWorkspace) &&
      !deletion.rejected.includes(JSON.stringify(filesWorkspace).slice(1, -1)),
    "WD7 serialized deletion rejection contains no private fixture path",
    detail,
  );
  await rm(sidecar, { recursive: true, force: true });
}

async function verifyLosslessFileGameSave(session, filesWorkspace) {
  const workspace = { id: { id: filesWorkspaceId }, kind: "fileWorkspace" };
  const sentence =
    "The game in the file contains moves or comments ChessRiddle Studio cannot keep. Saving over it would delete them. You can save your version as a new game.";
  const fixtures = [
    {
      name: "verify-lossy-source",
      event: "Lossy",
      pgn: '[Event "Lossy"]\n\n1. e4 e5 2. Nf9 Nc6 3. Bb5 *\n',
    },
    {
      name: "verify-trailing-comment",
      event: "Trailing",
      pgn: '[Event "Trailing"]\n\n1. e4 e5 1-0 {White won on time}\n',
    },
  ];
  const locate = (label, expression, args = []) =>
    reachableStableCoordinates(session, label, expression, args);
  const button = (label) =>
    locate(
      label,
      `[...document.querySelectorAll('[data-file-freshness] button')].find(node => node.textContent.trim() === arguments[0])`,
      [label],
    );
  const save = () =>
    session.call("POST", "/actions", {
      actions: [
        {
          type: "key",
          id: "lossless-file-save",
          actions: [
            { type: "keyDown", value: "\uE009" },
            { type: "keyDown", value: "s" },
            { type: "keyUp", value: "s" },
            { type: "keyUp", value: "\uE009" },
          ],
        },
      ],
    });
  const screenshot = async (name) => {
    if (!screenshotPath) return;
    const path = `${screenshotPath}.${name}.png`;
    await writeFile(path, Buffer.from(await session.screenshot(), "base64"));
    console.log(`  .. lossless-save screenshot: ${path}`);
  };
  for (const [index, fixture] of fixtures.entries()) {
    const path = join(filesWorkspace, `${fixture.name}.pgn`);
    const editedEvent = `verify:edited-${fixture.event}`;
    const before = Buffer.from(fixture.pgn);
    let owner;
    const opened = await assertion(
      `${index === 0 ? "LS1" : "LS6"} ${fixture.event} fixture opens from its real registered PGN file`,
      async () => {
        await writeFile(path, before);
        const listed = await invokeJsonAndWait(
          session,
          `${fixture.event} fixture registration`,
          "__verifyLosslessSaveListing",
          `window.__TAURI_INTERNALS__.invoke("list_file_workspace", { workspace: ${JSON.stringify(workspace)}, ticket: null })`,
        );
        const entry = listed.value?.entries?.find((candidate) => candidate.name === fixture.name);
        if (!entry?.handle?.id?.id)
          throw new Error(`fixture handle unavailable: ${JSON.stringify(listed)}`);
        const row = await filesRowCoordinates(session, fixture.name);
        await doubleClickAt(session, row.x, row.y);
        owner = await waitFor(`${fixture.event} file tree`, async () => {
          const snapshot = await readActiveTabTree(session);
          return (
            snapshot.tab?.gameOrigin.kind === "file" &&
            snapshot.tab.gameOrigin.file.handle.id.id === entry.handle.id.id &&
            snapshot.tab.gameOrigin.gameNumber === 0 &&
            snapshot.tree?.headers.event === fixture.event &&
            snapshot.tree.sourceStamp &&
            snapshot
          );
        });
      },
    );
    const edited = await assertion(
      `${index === 0 ? "LS2" : "LS7"} ${fixture.event} tree is edited through the real PGN editor`,
      async () => {
        if (!opened) throw new Error("file opening failed");
        await dirtyActiveTreeEventHeader(session, editedEvent, {
          keyboardId: `lossless-edit-${index}`,
        });
      },
    );
    if (index === 0) {
      const refused = await assertion(
        "LS3 lossy in-place Save shows the exact loss explanation",
        async () => {
          if (!edited) throw new Error("tree editing failed");
          await save();
          const panel = await waitFor("lossy-source conflict panel", () =>
            session.execute(
              `const gate = document.querySelector('[data-tab-id=' + JSON.stringify(arguments[0]) + '][data-file-freshness^="conflict:"]');
             return gate && { text: gate.innerText };`,
              [owner.tab.value],
            ),
          );
          await screenshot("lossy-conflict");
          if (!panel.text.includes(sentence)) throw new Error(`observed panel: ${panel.text}`);
        },
      );
      await assertion(
        "LS4 lossy conflict offers Reload from disk and Save my version as a new game…",
        async () => {
          if (!refused) throw new Error("save refusal failed");
          const reload = await button("Reload from disk");
          const append = await button("Save my version as a new game…");
          if (reload.disabled || append.disabled) throw new Error("a recovery action is disabled");
        },
      );
      await assertion(
        "LS5 refused in-place Save leaves the original file bytes unchanged",
        async () => {
          const after = await readFile(path);
          console.log(`  .. LS5 SHA-256 before=${sha256(before)} after=${sha256(after)}`);
          if (!edited || !refused || !before.equals(after))
            throw new Error("save refusal or byte preservation failed");
        },
      );
      // Append recovery calls pickPgnFile, which opens native GTK chrome outside WebDriver.
      // Do not replace that picker or append through IPC and claim the user action was verified.
      console.log(
        "  .. LS append recovery BLOCKED: Save my version as a new game… requires the native GTK file picker",
      );
      if (refused) {
        const reload = await button("Reload from disk");
        await clickAt(session, reload.x, reload.y);
        await waitFor("lossy fixture cleanup reload", () =>
          session.execute(
            `return Boolean(document.querySelector('[data-tab-id=' + JSON.stringify(arguments[0]) + '][data-file-freshness^="verified:"]'));`,
            [owner.tab.value],
          ),
        );
      }
    } else {
      await assertion(
        "LS8 trailing-comment in-place Save succeeds without a conflict",
        async () => {
          if (!edited) throw new Error("tree editing failed");
          await save();
          await waitFor("trailing-comment saved tree and file", async () => {
            const snapshot = await readActiveTabTree(session);
            const text = await readFile(path, "utf8");
            const verified = await session.execute(
              `return Boolean(document.querySelector('[data-tab-id=' + JSON.stringify(arguments[0]) + '][data-file-freshness^="verified:"]'));`,
              [owner.tab.value],
            );
            return (
              snapshot.tab?.value === owner.tab.value &&
              snapshot.tree?.dirty === false &&
              snapshot.tree.headers.event === editedEvent &&
              text.includes(`[Event "${editedEvent}"]`) &&
              verified
            );
          });
          await screenshot("trailing-saved");
        },
      );
      await assertion(
        "LS9 saved trailing-comment file retains White won on time and the edit",
        async () => {
          const after = await readFile(path);
          console.log(`  .. LS9 SHA-256 before=${sha256(before)} after=${sha256(after)}`);
          const text = after.toString("utf8");
          if (!text.includes("White won on time") || !text.includes(`[Event "${editedEvent}"]`))
            throw new Error(`saved PGN: ${text}`);
        },
      );
    }
  }
}

async function verifySelectedRootPermissions(session, puzzleRoot, engineRoot) {
  const puzzle = { id: { id: "verify-permission-puzzles" }, kind: "puzzleRoot" };
  const engine = { id: { id: "verify-permission-engines" }, kind: "engineRoot" };
  const child = join(engineRoot, "blocked-child");
  console.log(`  .. root-permission disposable inputs: ${puzzleRoot}, ${engineRoot}, ${child}`);
  for (const path of [puzzleRoot, engineRoot, child])
    rootPermissionRestorations.set(path, statSync(path).mode & 0o777);
  const ipc = (command, args) =>
    `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)}, ${JSON.stringify(args)})`;
  const invoke = (command, args) =>
    invokeJsonAndWait(session, command, "__verifyRootPermission", ipc(command, args));
  const rejection = (response) => {
    try {
      return JSON.parse(response.result.rejected);
    } catch {
      return null;
    }
  };
  const safePermission = (error) =>
    error?.tag === "backend-error" &&
    error.category === "permission" &&
    error.message === "I/O failure" &&
    error.rootFailure === "permission";
  let ownedProbe;
  const workflowFailure = (response) =>
    response.value?.id === ownedProbe?.id && response.value?.outcome?.state === "failed"
      ? response.value.outcome.result
      : undefined;
  const healthyWorkflow = (response) => {
    const error = workflowFailure(response);
    return (
      error?.tag === "backend-error" &&
      error.category === "invalid-input" &&
      error.message === "Invalid input: invalid artifact SHA-256" &&
      error.rootFailure === undefined
    );
  };
  const workflowProbe = async (stage, catalog) => {
    const ticket = await invoke("prepare_download", {});
    const id = randomUUID();
    ownedProbe = { id, stage, ticket: ticket.value };
    const response = await invoke("install_engine_workflow", {
      id,
      jobId: ticket.value,
      request: {
        intent: { kind: "add", engine_id: randomUUID() },
        root: engine,
        progressId: `verify-root-permission:${id}`,
        url: catalog.downloadLink,
        sha256: "z".repeat(64),
        signature: catalog.signature,
        relativePath: catalog.path,
        name: catalog.name,
        version: catalog.version,
        elo: catalog.elo ?? null,
        downloadSize: catalog.downloadSize ?? null,
      },
    });
    const error = workflowFailure(response);
    if (error)
      ownedProbe.notification =
        error.rootFailure === "permission"
          ? "ChessRiddle Studio is not allowed to read this engine folder. Choose another in Settings."
          : error.message;
    return response;
  };
  const dismissNotification = async (stage, notification, allowAbsent = false) => {
    await waitFor(`root permission ${stage} notification close`, () =>
      session.execute(
        `
        const description = [...document.querySelectorAll('.mantine-Notification-description')].find(node =>
          node.textContent === arguments[0] && node.getBoundingClientRect().height > 0 &&
          getComputedStyle(node).visibility !== 'hidden');
        if (!description) return arguments[1];
        const close = description?.closest('.mantine-Notification-root')?.querySelector('button.mantine-Notification-closeButton');
        if (!close || close.disabled) return false;
        close.click();
        return true;
      `,
        [notification, allowAbsent],
      ),
    );
    await waitFor(`root permission ${stage} notification disappearance`, () =>
      session.execute(
        `return ![...document.querySelectorAll('.mantine-Notification-description')].some(node => node.textContent === arguments[0]);`,
        [notification],
      ),
    );
  };
  const settleProbe = async () => {
    if (!ownedProbe) return;
    const { id, stage, notification, ticket } = ownedProbe;
    await waitFor(`root permission ${stage} completion acknowledgement`, async () => {
      const pending = await invoke("pending_engine_completions", {});
      return Array.isArray(pending.value) && !pending.value.some((entry) => entry.id === id);
    });
    // Release is idempotent after admission, and also frees a reservation refused before claim.
    if (ticket !== undefined) {
      const released = await invoke("release_download", { id: ticket });
      if (released.value !== null)
        throw new Error(
          `root permission ${stage} reservation release failed: ${JSON.stringify(released)}`,
        );
    }
    ownedProbe = undefined;
    if (notification) await dismissNotification(stage, notification);
  };
  const visible = (message, { beforeProbe } = {}) =>
    waitFor(message, async () => {
      await beforeProbe?.();
      return session.execute(
        `
    return [...document.querySelectorAll('.mantine-Notification-description')].some(node =>
      node.textContent === arguments[0] && node.getBoundingClientRect().height > 0 &&
      getComputedStyle(node).visibility !== 'hidden');
  `,
        [message],
      );
    }).catch(() => false);
  const click = (label) =>
    waitFor(`root permission action ${label}`, () =>
      session.execute(
        `
    const button = [...document.querySelectorAll('button')].find(node =>
      (${ACCESSIBLE_TEXT}(node) === arguments[0] || node.getAttribute('aria-label') === arguments[0]) && !node.disabled);
    if (!button) return false;
    button.click();
    return true;
  `,
        [label],
      ),
    );
  const savedEngines = await session.execute("return localStorage.getItem('engines')");
  try {
    const catalog = JSON.parse(
      await readFile(new URL("../src/catalogs/engines.json", import.meta.url), "utf8"),
    ).find((entry) => entry.type === "local" && entry.os === "linux");
    const before = await invoke("list_puzzle_databases", { ticket: null });
    const selectedPuzzle = await invoke("get_puzzle_workspace", {});
    const selectedEngine = await invoke("get_engine_workspace", {});
    const acquired = await workflowProbe("RF0", catalog);
    const ready =
      Array.isArray(before.value) &&
      before.value.length === 0 &&
      healthyWorkflow(acquired) &&
      selectedPuzzle.value?.root?.id?.id === puzzle.id.id &&
      selectedEngine.value?.root?.id?.id === engine.id.id;
    check(
      ready,
      "RF0 selected puzzle and engine roots accept real IPC before access loss",
      JSON.stringify({ before, acquired, selectedPuzzle, selectedEngine }),
    );
    await settleProbe();
    if (!ready) return;

    chmodSync(puzzleRoot, 0o300);
    const puzzleDenied = await invoke("list_puzzle_databases", { ticket: null });
    check(
      safePermission(rejection(puzzleDenied)),
      "RF1 puzzle read denial preserves Permission and I/O failure with a permission root label",
      JSON.stringify(puzzleDenied),
    );
    await goToBoards(session);
    await click("Puzzles");
    // A new puzzle tab opens on ChessRiddle whenever that connection is available (d-20261110-01).
    // The permission notice belongs to the offline databases, so select that source first.
    const puzzleGuidance = await visible(
      "ChessRiddle Studio is not allowed to read this puzzle folder. Choose another in Settings.",
      {
        beforeProbe: () =>
          session.execute(`
            const offline = document.querySelector('input[type="radio"][value="offline"]');
            if (offline && !offline.checked) offline.click();
            return true;
          `),
      },
    );
    check(
      puzzleGuidance,
      "RF5 puzzle permission guidance is visible through the actual renderer",
      puzzleGuidance
        ? undefined
        : JSON.stringify(
            await session
              .execute(
                `return { path: location.pathname, offlineSource: document.querySelector('input[type="radio"][value="offline"]')?.checked ?? null, notifications: [...document.querySelectorAll('.mantine-Notification-root')].map(node => node.innerText) };`,
              )
              .catch((error) => String(error)),
          ),
    );
    chmodSync(puzzleRoot, 0o700);

    chmodSync(engineRoot, 0o300);
    const destinationDenied = await workflowProbe("RF2", catalog);
    check(
      safePermission(workflowFailure(destinationDenied)),
      "RF2 engine destination read denial preserves Permission and I/O failure with a permission root label",
      JSON.stringify(destinationDenied),
    );
    await settleProbe();
    await goToEngines(session);
    await click("Add New");
    await click("Install");
    check(
      await visible(
        "ChessRiddle Studio is not allowed to read this engine folder. Choose another in Settings.",
      ),
      "RF6 Add permission guidance is visible through the actual renderer",
    );
    if (screenshotPath) {
      await writeFile(screenshotPath, Buffer.from(await session.screenshot(), "base64"));
      console.log(`  ..  Add permission guidance screenshot written to ${screenshotPath}`);
    }
    await click("Close dialog");
    await dismissNotification(
      "RF6",
      "ChessRiddle Studio is not allowed to read this engine folder. Choose another in Settings.",
      true,
    );

    // Public workflow search denial now replaces the removed registration IPC probe.
    // Later private registration is covered by root_failure_engine_later_adoption_publication_and_registration.
    // Former browser RF4 child denial is covered through actual private registration in
    // root_failure_engine_healthy_root_child_permission_denial_is_unlabelled.
    chmodSync(engineRoot, 0o400);
    const laterDenied = await workflowProbe("RF3", catalog);
    check(
      safePermission(workflowFailure(laterDenied)),
      "RF3 public engine workflow root search denial preserves Permission and I/O failure with a permission root label",
      JSON.stringify(laterDenied),
    );
    await settleProbe();
    chmodSync(engineRoot, 0o700);
    check(
      (await session.execute("return localStorage.getItem('engines')")) === savedEngines &&
        (await readFile(join(child, "engine"), "utf8")) === "not an executable\n",
      "RF7 permission failures retain saved engines and unrelated filesystem bytes",
    );
    const recovered = await invoke("list_puzzle_databases", { ticket: null });
    const recoveredPuzzle = await invoke("get_puzzle_workspace", {});
    const recoveredEngine = await invoke("get_engine_workspace", {});
    const destination = await workflowProbe("RF8", catalog);
    check(
      Array.isArray(recovered.value) &&
        recovered.value.length === 0 &&
        recoveredPuzzle.value?.root?.id?.id === puzzle.id.id &&
        recoveredEngine.value?.root?.id?.id === engine.id.id &&
        healthyWorkflow(destination),
      "RF8 restoring access recovers the same selected roots",
      JSON.stringify({ recovered, recoveredPuzzle, recoveredEngine, destination }),
    );
    await settleProbe();
  } finally {
    try {
      restoreRootPermissions();
    } finally {
      await settleProbe();
    }
  }
}

// Conversion assertion staging receipts. Root observed these native application runs.
// Negative evidence base: /tmp/build-943062b9-1e23-42b1-83a0-e262a3eac635/
// native-fault.log, native-seed.log, native-setup.log and corresponding native-fault.actual-exit, native-seed.actual-exit, native-setup.actual-exit.
// Disposable fault producer based on a98d07e5 changed only operations.rs cancel_conversion to return Ok(true).
// A disposable PGN with 100 valid games let ignored cancellation settle within the existing budget.
// CC0 passed. Actual exit 1 with these direct failures:
// FAIL CC1 prepared conversion cancellation returns typed Cancellation before claim (outcome undefined).
// FAIL CC2 native progress triggers running and same-target queued ticket cancellation (both succeeded despite [true, true] acknowledgements).
// FAIL CC3 cancelled native imports preserve existing content and DataRevision (count/revision 1/1 became 202/4).
// FAIL CC4 a fresh conversion ticket retries successfully after cancellation (count/revision reached 203/5).
// FAIL CC5 settled native conversion tickets are retired (completed ticket remained active).
// Seed probe restored the correct producer, changed only the disposable seed PGN to two games and saved its original bytes.
// Actual exit 1: FAIL CC0 conversion fixture seeds exactly one native game (count 2, revision 1).
// CC1-CC5 were dependent failures, not direct receipts. An unrelated freshness timing miss under load was not changed or used for staging.
// Setup probe used the correct producer and a disposable preexisting database at the harness target path. No live or production database was edited.
// Actual exit 1, setup refusal separate from assertions:
// FAIL CC0 conversion setup unavailable: Conflict: database filename already exists
// FAIL CC1 conversion setup unavailable: Conflict: database filename already exists
// FAIL CC2 conversion setup unavailable: Conflict: database filename already exists
// FAIL CC3 conversion setup unavailable: Conflict: database filename already exists
// FAIL CC4 conversion setup unavailable: Conflict: database filename already exists
// FAIL CC5 conversion setup unavailable: Conflict: database filename already exists
// Original fixture bytes were saved, then all three disposable negative profiles were deleted after process shutdown.
// Producer source was restored clean and rebuilt successfully, and the owned staging worktree was removed through kit.
// The positive run used fresh unmodified inputs produced by the unchanged harness.
// Root final proof ran the unchanged verifier after C1 repair on base HEAD 09e4afb4 plus the C1 source patch.
// The completion record was polled and validated with status 0:
// /home/felixb/.claude/drain-state/drain-90a2aa88.d/gates-943062b9-1e23-42b1-83a0-e262a3eac635/gate-native-final.0qolvr/completion.record
// pnpm build ran, then pnpm verify:app --screenshot /tmp/build-943062b9-1e23-42b1-83a0-e262a3eac635/verify-ui/final.png.
// CC0-CC5 and the full verifier passed with observed exit 0.
// Its /tmp/chessfable-verify-nedV5q profile was absent after completion. This is local runtime proof, not Windows or macOS proof.
// Expanded root receipts: tasks/handoffs/2026-10-15-local-pgn-cancellation-execution.md
export async function verifyConversionCancellationContract({
  invoke,
  cancelledPair,
  snapshot,
  seed,
  source,
  database,
  report = check,
}) {
  const importArgs = (file, ticket) => ({
    progressId: `verify-conversion:${randomUUID()}`,
    files: [file],
    database,
    timestamp: null,
    title: "Cancellation proof",
    description: null,
    ticket,
  });
  let before;
  const seeded = await assertion(
    "CC0 conversion fixture seeds exactly one native game",
    async () => {
      if (!seed || !source) throw new Error("dedicated conversion PGNs were not listed");
      await invoke("convert_pgn", importArgs(seed, null));
      before = await snapshot();
      if (before.count !== 1 || before.revision !== 1)
        throw new Error(`unexpected seed: ${JSON.stringify(before)}`);
    },
    report,
  );
  const requireSeed = () => {
    if (!seeded) throw new Error("conversion seed failed");
  };
  await assertion(
    "CC1 prepared conversion cancellation returns typed Cancellation before claim",
    async () => {
      requireSeed();
      const ticket = await invoke("prepare_conversion", {});
      try {
        if ((await invoke("cancel_conversion", { ticket })) !== true)
          throw new Error("reserved cancel was not acknowledged");
        let rejected;
        try {
          await invoke("convert_pgn", importArgs(seed, ticket));
        } catch (cause) {
          rejected = cause;
        }
        if (rejected?.category !== "cancellation")
          throw new Error(`wrong reserved outcome: ${JSON.stringify(rejected)}`);
      } finally {
        await invoke("release_conversion", { ticket });
      }
    },
    report,
  );
  let pair;
  await assertion(
    "CC2 native progress triggers running and same-target queued ticket cancellation",
    async () => {
      requireSeed();
      pair = await cancelledPair(importArgs(source, null));
      if (
        !pair.started ||
        pair.running?.category !== "cancellation" ||
        pair.queued?.category !== "cancellation" ||
        pair.acknowledged?.some((value) => value !== true) ||
        pair.acknowledged?.length !== 2
      )
        throw new Error(`wrong running/queued outcome: ${JSON.stringify(pair)}`);
    },
    report,
  );
  await assertion(
    "CC3 cancelled native imports preserve existing content and DataRevision",
    async () => {
      requireSeed();
      if (!pair) throw new Error("running/queued import did not settle");
      const after = await snapshot();
      if (JSON.stringify(after) !== JSON.stringify(before))
        throw new Error(`rollback mismatch: ${JSON.stringify({ before, after })}`);
    },
    report,
  );
  await assertion(
    "CC4 a fresh conversion ticket retries successfully after cancellation",
    async () => {
      requireSeed();
      const ticket = await invoke("prepare_conversion", {});
      try {
        await invoke("convert_pgn", importArgs(seed, ticket));
      } finally {
        await invoke("release_conversion", { ticket });
      }
      const after = await snapshot();
      if (after.count !== 2 || after.revision !== 2)
        throw new Error(`retry mismatch: ${JSON.stringify(after)}`);
    },
    report,
  );
  await assertion(
    "CC5 settled native conversion tickets are retired",
    async () => {
      if (!pair) throw new Error("running/queued import did not settle");
      if (pair.tickets?.length !== 2 || pair.tickets[0] === pair.tickets[1])
        throw new Error("two distinct conversion tickets were not retained");
      for (const ticket of pair.tickets) {
        await invoke("release_conversion", { ticket });
        if ((await invoke("cancel_conversion", { ticket })) !== false)
          throw new Error("completed ticket remained active");
      }
    },
    report,
  );
}

async function verifyConversionCancellation(session, ownedRoot) {
  // This reader is restricted to this run's newly created disposable database.
  const snapshot = () => {
    const db = new DatabaseSync(join(ownedRoot, "verify-conversion-cancellation.db3"), {
      readOnly: true,
    });
    try {
      const count = db.prepare("SELECT COUNT(*) AS count FROM Games").get().count;
      const revision = Number(
        db.prepare("SELECT Value FROM Info WHERE Name = 'DataRevision'").get()?.Value ?? 0,
      );
      const games = count <= 2 ? db.prepare("SELECT * FROM Games ORDER BY ID").all() : [];
      return { count, revision, games };
    } finally {
      db.close();
    }
  };
  const invoke = async (command, args) => {
    const response = await invokeJsonAndWait(
      session,
      command,
      "__verifyConversionIPC",
      `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)}, ${JSON.stringify(args)})`,
    );
    if (response.value === undefined) {
      if (response.result.rejected) {
        let rejection;
        try {
          rejection = JSON.parse(response.result.rejected);
        } catch {
          throw new Error(response.result.rejected);
        }
        throw rejection;
      }
      throw new Error(response.error ?? response.result.error ?? `${command} returned no value`);
    }
    return response.value;
  };
  const cancelledPair = async (args) => {
    const runningTicket = await invoke("prepare_conversion", {});
    const queuedTicket = await invoke("prepare_conversion", {});
    const running = { ...args, ticket: runningTicket };
    const queued = { ...args, progressId: `verify-queued:${randomUUID()}`, ticket: queuedTicket };
    await session.execute(
      `
      const native = window.__TAURI_INTERNALS__;
      const running = arguments[0], queued = arguments[1];
      const state = window.__verifyConversionPair = { started: false, tickets: [running.ticket, queued.ticket] };
      const outcome = error => ({ category: error && error.category, message: error && error.message });
      window.__verifyConversionHandler = native.transformCallback(event => {
        if (event.payload.id !== running.progressId || state.started) return;
        state.started = true;
        native.invoke('convert_pgn', queued).then(() => { state.queued = { category: 'success' }; }, error => { state.queued = outcome(error); });
        Promise.all([running.ticket, queued.ticket].map(ticket => native.invoke('cancel_conversion', { ticket })))
          .then(values => { state.acknowledged = values; }, error => { state.acknowledged = [outcome(error)]; });
      });
      return true;
    `,
      [running, queued],
    );
    const listener = await invokeJsonAndWait(
      session,
      "conversion listener registration",
      "__verifyConversionListener",
      `window.__TAURI_INTERNALS__.invoke('plugin:event|listen', { event: 'convert-progress', target: { kind: 'Any' }, handler: window.__verifyConversionHandler })`,
    );
    try {
      await session.execute(
        `
        window.__TAURI_INTERNALS__.invoke('convert_pgn', arguments[0]).then(
          () => { window.__verifyConversionPair.running = { category: 'success' }; },
          error => { window.__verifyConversionPair.running = { category: error && error.category, message: error && error.message }; });
        return true;
      `,
        [running],
      );
      return await waitFor(
        "native conversion pair settlement",
        () =>
          session.execute(`
        const state = window.__verifyConversionPair;
        return state.running && (!state.started || (state.queued && state.acknowledged)) ? state : false;
      `),
        { timeoutMs: FILES_PROBE_TIMEOUT_MS },
      );
    } finally {
      await invoke("cancel_conversion", { ticket: runningTicket });
      await invoke("cancel_conversion", { ticket: queuedTicket });
      await invoke("plugin:event|unlisten", { event: "convert-progress", eventId: listener.value });
      await session.execute(
        `window.__TAURI_EVENT_PLUGIN_INTERNALS__.unregisterListener('convert-progress', arguments[0]); return true`,
        [listener.value],
      );
    }
  };
  let entries;
  let database;
  try {
    entries = await listFixtureEntries(invoke);
    const root = (await invoke("get_database_workspace", {})).root;
    database = await invoke("create_workspace_database", {
      root,
      filename: "verify-conversion-cancellation.db3",
    });
  } catch (cause) {
    for (const label of ["CC0", "CC1", "CC2", "CC3", "CC4", "CC5"])
      check(false, `${label} conversion setup unavailable`, cause.message);
    return;
  }
  await verifyConversionCancellationContract({
    invoke,
    cancelledPair,
    snapshot,
    database,
    seed: entries.find((entry) => entry.name === conversionSeedName)?.handle,
    source: entries.find((entry) => entry.name === conversionSourceName)?.handle,
  });
}

async function verifyProgressContract(session) {
  const id = `verify-progress:${randomUUID()}`;
  const ipc = (command, args) =>
    `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)}, ${JSON.stringify(args)})`;
  const invoke = (command, args) =>
    invokeJsonAndWait(session, command, "__verifyProgressResult", ipc(command, args));
  const canonical = canonicalProgressGeneration;
  const exact = (value, expected) => canonical(value) && value === expected;
  await session.execute(`
    window.__verifyProgressEvents = [];
    window.__verifyProgressHandler = window.__TAURI_INTERNALS__.transformCallback(event => {
      window.__verifyProgressEvents.push(event.payload);
    });
    return true;
  `);
  const registration = await invokeJsonAndWait(
    session,
    "progress listener registration",
    "__verifyProgressRegistration",
    `window.__TAURI_INTERNALS__.invoke("plugin:event|listen", { event: "progress-event", target: { kind: "Any" }, handler: window.__verifyProgressHandler })`,
  );
  check(
    typeof registration.value === "number",
    "progress native event listener registers",
    JSON.stringify(registration),
  );
  const event = async (description, predicate, generation, extra) => {
    const observed = await waitFor(
      description,
      () =>
        session.execute(
          `return window.__verifyProgressEvents.find(payload => payload.id === arguments[0] && (${predicate})) || false`,
          [id],
        ),
      { timeoutMs: IPC_PROBE_TIMEOUT_MS },
    ).catch((error) => ({ error: error.message }));
    check(
      exact(observed.generation, generation) && extra(observed),
      description,
      JSON.stringify(observed),
    );
    return observed;
  };
  try {
    // Native jobs mint progress. This probe only reads, clears, and listens.
    const absent = await invoke("get_progress", { id });
    check(
      absent.value === null,
      "progress absent id has no native snapshot",
      JSON.stringify(absent),
    );
    const malformedClear = await invoke("clear_progress", { id: null });
    check(
      typeof malformedClear.result.rejected === "string",
      "progress invalid clear rejects as a native IPC operation",
      JSON.stringify(malformedClear),
    );
    const cleared = await invoke("clear_progress", { id });
    if (expectClearRejection) {
      let rejection = null;
      try {
        if (typeof cleared.result.rejected === "string")
          rejection = JSON.parse(cleared.result.rejected);
      } catch {
        // The assertion below identifies a malformed rejection envelope too.
      }
      check(
        rejection?.tag === "backend-error" && rejection.category === "conflict",
        "progress deliberate clear failure returns a typed native rejection",
        JSON.stringify(cleared),
      );
    } else {
      const generation = cleared.value;
      check(
        canonical(generation) &&
          (expectedProgressGeneration === undefined || generation === expectedProgressGeneration),
        "progress clear return has exact canonical string generation",
        JSON.stringify(cleared),
      );
      if (!canonical(generation)) return;
      await event(
        "progress cleared event has exact canonical string generation",
        "payload.cleared === true",
        generation,
        (payload) =>
          payload.finished === true && payload.state === "cancelled" && payload.progress === 0,
      );
      const empty = await invoke("get_progress", { id });
      check(
        empty.value === null,
        "progress clear removes the native snapshot",
        JSON.stringify(empty),
      );
    }
  } finally {
    await session.execute(
      `window.__TAURI_EVENT_PLUGIN_INTERNALS__.unregisterListener("progress-event", arguments[0]); return true;`,
      [registration.value],
    );
    const unlisten = await invokeJsonAndWait(
      session,
      "progress listener cleanup",
      "__verifyProgressUnlisten",
      `window.__TAURI_INTERNALS__.invoke("plugin:event|unlisten", { event: "progress-event", eventId: ${JSON.stringify(registration.value)} })`,
    );
    check(
      unlisten.value === null,
      "progress native event listener is released",
      JSON.stringify(unlisten),
    );
    await session.execute(
      `window.__TAURI_INTERNALS__.unregisterCallback(window.__verifyProgressHandler); delete window.__verifyProgressEvents; delete window.__verifyProgressHandler; return true;`,
    );
  }
}

/**
 * Native Help menus are GTK chrome, so the row's Feedback button is the
 * reachable entry. Never click Send: this scenario must not reach the network.
 */
async function verifyFeedbackScreenshot(session) {
  const wait = (label, probe) => waitFor(label, probe, { timeoutMs: FEEDBACK_CAPTURE_TIMEOUT_MS });
  const feedbackDialogOpen = () =>
    session.execute(`
      return [...document.querySelectorAll('[role="dialog"]')].some((dialog) =>
        [...dialog.querySelectorAll("button")].some(
          (button) => button.textContent.trim() === "Take screenshot",
        ),
      );
    `);
  const dismissFeedbackDialog = async () => {
    await session
      .execute("delete window.__verifyAppFeedbackScreenshot; return true;")
      .catch(() => false);
    const previewPresent = await session
      .execute(
        `return Boolean(document.querySelector('[role="dialog"] img[alt="Image preview"]'));`,
      )
      .catch(() => false);
    if (previewPresent) {
      await clickButton(session, "Remove image", true);
      await wait("feedback image preview to leave", () =>
        session
          .execute(`return !document.querySelector('[role="dialog"] img[alt="Image preview"]');`)
          .catch(() => false),
      );
    }
    if (await feedbackDialogOpen().catch(() => false)) {
      await clickButton(session, "Close dialog", true);
      await wait("feedback dialog to leave", () =>
        feedbackDialogOpen()
          .then((open) => !open)
          .catch(() => false),
      );
    }
  };

  try {
    await assertion("the row Feedback control opens the feedback dialog", async () => {
      await clickFeedback(session);
      await wait("the feedback dialog", feedbackDialogOpen);
    });
    await assertion(
      "Take screenshot attaches a decodable preview with more than one colour",
      async () => {
        await clickButton(session, "Take screenshot");
        await wait("the feedback image preview", () =>
          session
            .execute(
              `const img = document.querySelector('[role="dialog"] img[alt="Image preview"]');
               return Boolean(img && img.src);`,
            )
            .catch(() => false),
        );
        const path = `${screenshotPath ?? join(tmpdir(), `chessfable-feedback-${process.pid}`)}.feedback-preview.png`;
        await writeFile(path, Buffer.from(await session.screenshot(), "base64"));
        console.log(`  .. feedback-preview screenshot: ${path}`);
        const decoded = await wait("feedback screenshot preview to decode", async () => {
          const failure = await session.execute(`
            const alert = document.querySelector('[role="dialog"] [role="alert"]');
            return alert && alert.textContent
              ? { error: "undecodable", message: alert.textContent }
              : false;
          `);
          if (failure) return failure;
          return session.execute(`
            const preview = document.querySelector('[role="dialog"] img[alt="Image preview"]');
            const src = preview && typeof preview.src === "string" ? preview.src : "";
            if (!src.startsWith("data:")) return false;
            let state = window.__verifyAppFeedbackScreenshot;
            if (!state || state.src !== src) {
              state = { src, done: false, value: false };
              window.__verifyAppFeedbackScreenshot = state;
              const probe = new Image();
              probe.onload = () => {
                if (window.__verifyAppFeedbackScreenshot?.src !== src) return;
                const width = probe.naturalWidth;
                const height = probe.naturalHeight;
                if (!(width > 0 && height > 0)) {
                  window.__verifyAppFeedbackScreenshot.value = {
                    error: "blank",
                    width,
                    height,
                    colors: 0,
                    samples: 0,
                  };
                  window.__verifyAppFeedbackScreenshot.done = true;
                  return;
                }
                try {
                  const canvas = document.createElement("canvas");
                  canvas.width = width;
                  canvas.height = height;
                  const ctx = canvas.getContext("2d");
                  if (!ctx) {
                    window.__verifyAppFeedbackScreenshot.value = {
                      error: "undecodable",
                      width,
                      height,
                      colors: 0,
                      samples: 0,
                    };
                    window.__verifyAppFeedbackScreenshot.done = true;
                    return;
                  }
                  ctx.drawImage(probe, 0, 0);
                  const cols = 8;
                  const rows = 8;
                  const colors = new Set();
                  for (let y = 0; y < rows; y++) {
                    for (let x = 0; x < cols; x++) {
                      const px = Math.min(width - 1, Math.floor(((x + 0.5) * width) / cols));
                      const py = Math.min(height - 1, Math.floor(((y + 0.5) * height) / rows));
                      const pixel = ctx.getImageData(px, py, 1, 1).data;
                      colors.add([pixel[0], pixel[1], pixel[2], pixel[3]].join(","));
                    }
                  }
                  window.__verifyAppFeedbackScreenshot.value = {
                    width,
                    height,
                    colors: colors.size,
                    samples: cols * rows,
                  };
                  window.__verifyAppFeedbackScreenshot.done = true;
                } catch (error) {
                  if (window.__verifyAppFeedbackScreenshot?.src !== src) return;
                  window.__verifyAppFeedbackScreenshot.value = {
                    error: "undecodable",
                    message: String(error && error.message ? error.message : error),
                    width,
                    height,
                    colors: 0,
                    samples: 0,
                  };
                  window.__verifyAppFeedbackScreenshot.done = true;
                }
              };
              probe.onerror = () => {
                if (window.__verifyAppFeedbackScreenshot?.src !== src) return;
                window.__verifyAppFeedbackScreenshot.value = {
                  error: "undecodable",
                  width: 0,
                  height: 0,
                  colors: 0,
                  samples: 0,
                };
                window.__verifyAppFeedbackScreenshot.done = true;
              };
              probe.src = src;
              return false;
            }
            return state.done ? state.value : false;
          `);
        });
        if (decoded.error) throw new Error(`preview ${decoded.error}: ${JSON.stringify(decoded)}`);
        if (!(decoded.width > 0 && decoded.height > 0))
          throw new Error(`preview has no dimensions: ${JSON.stringify(decoded)}`);
        if (!(decoded.samples >= 64))
          throw new Error(`preview sampled fewer than 64 pixels: ${JSON.stringify(decoded)}`);
        if (!(decoded.colors >= 2))
          throw new Error(`preview is blank or single-colour: ${JSON.stringify(decoded)}`);
      },
    );
  } finally {
    try {
      await dismissFeedbackDialog();
      const remaining = await feedbackDialogOpen().catch(() => true);
      check(!remaining, "the feedback dialog closes without sending");
    } catch (error) {
      check(false, "the feedback dialog closes without sending", error.message);
    }
  }
}

function canonicalProgressGeneration(value) {
  return (
    typeof value === "string" &&
    /^(0|[1-9][0-9]*)$/.test(value) &&
    value.length <= 20 &&
    BigInt(value) <= 18446744073709551615n
  );
}

async function loadPracticeDeckThroughIpc(session, fileId, game, globalName) {
  return invokeJsonAndWait(
    session,
    `load_practice_deck for ${fileId} to settle`,
    globalName,
    `window.__TAURI_INTERNALS__.invoke("load_practice_deck", ${JSON.stringify({ fileId, game })})`,
  );
}

async function loadAllPracticeReviews(session, fileId, game, globalPrefix, expectedEpoch) {
  const ids = [];
  const entries = [];
  let cursor = null;
  let page = 0;
  do {
    const loaded = await invokeJsonAndWait(
      session,
      `load_practice_reviews page ${page} for ${fileId} to settle`,
      `${globalPrefix}${page}`,
      `window.__TAURI_INTERNALS__.invoke("load_practice_reviews", ${JSON.stringify({
        fileId,
        game,
        cursor,
        limit: PRACTICE_REVIEW_PAGE_LIMIT,
        expectedEpoch,
      })})`,
    );
    if (!loaded.value || !Array.isArray(loaded.value.entries)) {
      return {
        ids,
        entries,
        complete: false,
        error: loaded.result.rejected ?? loaded.error ?? "practice review page was malformed",
      };
    }
    entries.push(...loaded.value.entries);
    ids.push(...loaded.value.entries.map(({ id }) => id));
    cursor = loaded.value.nextCursor;
    page += 1;
  } while (cursor !== null);
  return { ids, entries, complete: true, error: undefined };
}

/** True when the stored cards are exactly the expected fixture cards (FEN → answer), in any order. */
function practiceCardsMatch(actual, expected) {
  if (!Array.isArray(actual) || actual.length !== expected.length) return false;
  const expectedAnswers = new Map(expected.map(({ fen, answer }) => [fen, answer]));
  const seen = new Set();
  return actual.every(({ fen, answer }) => {
    if (seen.has(fen) || expectedAnswers.get(fen) !== answer) return false;
    seen.add(fen);
    return true;
  });
}

function practicePositionsFromSnapshot(snapshot) {
  try {
    const positions = JSON.parse(snapshot?.positionsDocument ?? "null").positions;
    return Array.isArray(positions) ? positions : undefined;
  } catch {
    return undefined;
  }
}

/** One real left click at viewport coordinates through W3C pointer actions. */
async function clickAt(session, x, y, id = "mouse") {
  await session.call("POST", "/actions", {
    actions: [
      {
        type: "pointer",
        id,
        parameters: { pointerType: "mouse" },
        actions: [
          { type: "pointerMove", duration: 0, x, y, origin: "viewport" },
          { type: "pointerDown", button: 0 },
          { type: "pointerUp", button: 0 },
        ],
      },
    ],
  });
}

/** One pointer sequence for a UCI move: two square clicks separated by PRACTICE_MOVE_CLICK_DELAY_MS. Does not wait for a tree ply. */
async function playPracticeBoardMove(session, uci, pointerId) {
  const pointer = await session.execute(
    `const board = document.querySelector('cg-board');
     if (!board) return false;
     const box = board.getBoundingClientRect();
     const square = (name) => ({
       x: Math.round(box.left + (name.charCodeAt(0) - 96.5) * box.width / 8),
       y: Math.round(box.top + (8.5 - Number(name[1])) * box.height / 8),
     });
     return { from: square(arguments[0].slice(0, 2)), to: square(arguments[0].slice(2, 4)) };`,
    [uci],
  );
  if (!pointer) throw new Error(`practice board was not available for ${uci}`);
  await session.call("POST", "/actions", {
    actions: [
      {
        type: "pointer",
        id: pointerId,
        parameters: { pointerType: "mouse" },
        actions: [
          {
            type: "pointerMove",
            duration: 0,
            x: pointer.from.x,
            y: pointer.from.y,
            origin: "viewport",
          },
          { type: "pointerDown", button: 0 },
          { type: "pointerUp", button: 0 },
          { type: "pause", duration: PRACTICE_MOVE_CLICK_DELAY_MS },
          {
            type: "pointerMove",
            duration: 0,
            x: pointer.to.x,
            y: pointer.to.y,
            origin: "viewport",
          },
          { type: "pointerDown", button: 0 },
          { type: "pointerUp", button: 0 },
        ],
      },
    ],
  });
}

/** One real double-click, with the two clicks inside the platform double-click interval. */
async function doubleClickAt(session, x, y) {
  await session.call("POST", "/actions", {
    actions: [
      {
        type: "pointer",
        id: "mouse",
        parameters: { pointerType: "mouse" },
        actions: [
          { type: "pointerMove", duration: 0, x, y, origin: "viewport" },
          { type: "pointerDown", button: 0 },
          { type: "pointerUp", button: 0 },
          { type: "pause", duration: DOUBLE_CLICK_GAP_MS },
          { type: "pointerDown", button: 0 },
          { type: "pointerUp", button: 0 },
        ],
      },
    ],
  });
}

async function reachableStableCoordinates(
  session,
  label,
  script,
  args = [],
  { timeoutMs = FILES_PROBE_TIMEOUT_MS, beforeProbe, leftInset } = {},
) {
  let previous;
  let stableSince;
  return waitFor(
    label,
    async () => {
      await beforeProbe?.();
      const point = await session.execute(
        `
    const element = (${script});
    if (!element) return false;
    element.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    const box = element.getBoundingClientRect();
    if (!box.width || !box.height) return false;
    let left = Math.max(0, box.left), right = Math.min(innerWidth, box.right);
    let top = Math.max(0, box.top), bottom = Math.min(innerHeight, box.bottom);
    let settleMs = 0;
    const appearance = [];
    const milliseconds = value => parseFloat(value) * (value.trim().endsWith('ms') ? 1 : 1000);
    for (let node = element; node; node = node.parentElement) {
      const style = getComputedStyle(node);
      if (style.visibility === 'hidden' || style.display === 'none' || Number(style.opacity) === 0) return false;
      if (node.getAnimations?.().some(animation => animation.pending || animation.playState === 'running')) return false;
      const durations = style.transitionDuration.split(',').map(milliseconds);
      const delays = style.transitionDelay.split(',').map(milliseconds);
      for (let i = 0; i < Math.max(durations.length, delays.length); i++) {
        settleMs = Math.max(settleMs, durations[i % durations.length] + delays[i % delays.length]);
      }
      appearance.push([style.transform, style.opacity]);
      if (node === element) continue;
      const bounds = node.getBoundingClientRect();
      // Rows may extend behind another pane. Use only their reachable scrolling viewport.
      if (style.overflowX !== 'visible') {
        left = Math.max(left, bounds.left + node.clientLeft);
        right = Math.min(right, bounds.left + node.clientLeft + node.clientWidth);
      }
      if (style.overflowY !== 'visible') {
        top = Math.max(top, bounds.top + node.clientTop);
        bottom = Math.min(bottom, bounds.top + node.clientTop + node.clientHeight);
      }
    }
    if (right <= left || bottom <= top) return false;
    const x = Math.round(left + Math.min(${leftInset ?? "Infinity"}, (right - left) / 2));
    const y = Math.round((top + bottom) / 2);
    const hit = document.elementFromPoint(x, y);
    if (!hit || (hit !== element && !element.contains(hit))) return false;
    return { x, y, disabled: element.disabled, selected: element.getAttribute('aria-selected'),
      element, settleMs, geometry: [box.x, box.y, box.width, box.height, left, right, top, bottom, appearance] };
  `,
        args,
      );
      const now = Date.now();
      const stable =
        point &&
        previous &&
        JSON.stringify(point.element) === JSON.stringify(previous.element) &&
        JSON.stringify(point.geometry) === JSON.stringify(previous.geometry);
      if (!stable) stableSince = now;
      previous = point;
      // Mantine schedules its enter transition over animation frames. Equal early rectangles
      // alone can be a pre-enter plateau. Require unchanged geometry/appearance for the actual
      // ancestor transition budget as well as no pending/running animation, within this deadline.
      return stable && now - stableSince >= point.settleMs ? point : false;
    },
    { timeoutMs },
  );
}

async function clickButton(session, name, icon = false) {
  const point = await reachableStableCoordinates(
    session,
    name,
    `[...document.querySelectorAll('button')].find(node => !node.disabled && (arguments[1] ? (node.getAttribute('aria-label') || '').startsWith(arguments[0]) : ${ACCESSIBLE_TEXT}(node) === arguments[0]))`,
    [name, icon],
  );
  await clickAt(session, point.x, point.y);
}

const applicationMenuSelector = `[...document.querySelectorAll('button')].find(node => {
  const label = node.getAttribute('aria-label') || '';
  return label === 'Application menu' || label === 'Anwendungsmenü';
})`;
export const BOARD_TAB_STOP_SELECTOR = 'header [role="tablist"] [role="tab"][tabindex="0"]';

async function rendererChromeState(session) {
  return session
    .execute(
      `
    const menu = ${applicationMenuSelector};
    const box = menu?.getBoundingClientRect();
    const x = box ? Math.round(box.left + box.width / 2) : null;
    const y = box ? Math.round(box.top + box.height / 2) : null;
    const hit = x === null ? null : document.elementFromPoint(x, y);
    return {
      path: location.pathname,
      dialogs: [...document.querySelectorAll('[role="dialog"]')].map((dialog) =>
        dialog.innerText.replace(/\\s+/g, " ").trim().slice(0, 240),
      ),
      overlays: document.querySelectorAll(".mantine-Overlay-root, .mantine-Modal-overlay").length,
      applicationMenu: menu
        ? {
            label: menu.getAttribute("aria-label"),
            width: box.width,
            height: box.height,
            hit: hit && (hit === menu || menu.contains(hit)),
            hitLabel: hit?.getAttribute?.("aria-label") ?? hit?.tagName ?? null,
          }
        : null,
    };
  `,
    )
    .catch((error) => ({ unavailable: error.message }));
}

async function openApplicationMenu(session) {
  let point;
  try {
    point = await reachableStableCoordinates(session, "Application menu", applicationMenuSelector);
  } catch (error) {
    throw new Error(
      `${error.message}; renderer state: ${JSON.stringify(await rendererChromeState(session))}`,
    );
  }
  await clickAt(session, point.x, point.y);
  await waitFor("the application menu", () =>
    session.execute(`return document.querySelector('[role="menu"]') !== null`).catch(() => false),
  );
}

async function chooseApplicationMenuItem(session, names) {
  await openApplicationMenu(session);
  const point = await reachableStableCoordinates(
    session,
    names[0],
    `[...document.querySelectorAll('[role="menuitem"]')].find(node => {
      const text = node.textContent.replace(/\\s+/g, ' ').trim();
      return arguments[0].some((name) => text === name || text.startsWith(name + ' ') || text.startsWith(name));
    })`,
    [names],
  );
  await clickAt(session, point.x, point.y);
}

async function goToSettings(session) {
  const here = await session.execute("return location.pathname");
  if (here === "/settings" || here.startsWith("/settings/")) return;
  await chooseApplicationMenuItem(session, ["Settings", "Einstellungen"]);
  await waitFor("Settings route", () =>
    session
      .execute(
        "return location.pathname === '/settings' || location.pathname.startsWith('/settings/')",
      )
      .catch(() => false),
  );
}

async function goToEngines(session) {
  const here = await session.execute("return location.pathname");
  if (here === "/engines" || here.startsWith("/engines/")) return;
  await chooseApplicationMenuItem(session, ["Engines"]);
  await waitFor("Engines route", () =>
    session
      .execute(
        "return location.pathname === '/engines' || location.pathname.startsWith('/engines/')",
      )
      .catch(() => false),
  );
}

export async function goToAccounts(session) {
  const here = await session.execute("return location.pathname");
  if (here === "/accounts" || here.startsWith("/accounts/")) return;
  await chooseApplicationMenuItem(session, ["Accounts", "Konten"]);
  await waitFor("Accounts route", () =>
    session
      .execute(
        "return location.pathname === '/accounts' || location.pathname.startsWith('/accounts/')",
      )
      .catch(() => false),
  );
}

async function goToBoards(session) {
  const here = await session.execute("return location.pathname");
  if (here === "/") return;
  // Off "/", the row's single tab stop is the active tab. Clicking the first tab would select a
  // different game and still navigate to "/".
  const point = await reachableStableCoordinates(
    session,
    "board tab",
    `document.querySelector(${JSON.stringify(BOARD_TAB_STOP_SELECTOR)})`,
  );
  await clickAt(session, point.x, point.y);
  await waitFor("boards route", () =>
    session.execute("return location.pathname === '/'").catch(() => false),
  );
}

async function closeSelectedWorkspaceTab(session) {
  const point = await reachableStableCoordinates(
    session,
    "Close selected tab",
    `document.querySelector('header [role="tablist"] [role="tab"][aria-selected="true"] + button')`,
  );
  await clickAt(session, point.x, point.y);
}

async function clickFeedback(session) {
  const point = await reachableStableCoordinates(
    session,
    "Feedback",
    `[...document.querySelectorAll('button')].find(node => {
      const label = node.getAttribute('aria-label') || '';
      return label === 'Feedback';
    })`,
  );
  await clickAt(session, point.x, point.y);
}

async function filesRowCoordinates(session, name, timeoutMs = FILES_PROBE_TIMEOUT_MS) {
  return reachableStableCoordinates(
    session,
    `${name} Files row`,
    `document.querySelector('[role="treeitem"][aria-label=' + JSON.stringify(arguments[0]) + ']')`,
    [name],
    {
      timeoutMs,
      leftInset: 60,
      beforeProbe: async () => {
        await showLibraryOverview(session);
        await session.execute("window.dispatchEvent(new Event('focus')); return true;");
      },
    },
  );
}

async function openFilesEntry(session, name, timeoutMs = FILES_PROBE_TIMEOUT_MS) {
  const row = await filesRowCoordinates(session, name, timeoutMs);
  await clickAt(session, row.x, row.y);
  try {
    await waitFor(
      `${name} game preview to load`,
      () =>
        session
          .execute(
            "return document.body.innerText.includes('verify:practice') && [...document.querySelectorAll('button')].some(button => button.textContent.trim() === 'Open game')",
          )
          .catch(() => false),
      { timeoutMs },
    );
  } catch (error) {
    const state = await session
      .execute(
        "return { path: location.pathname, text: document.body.innerText.slice(0, 1000), boards: document.querySelectorAll('cg-board').length }",
      )
      .catch(() => ({ path: "unavailable", text: "unavailable", boards: "unavailable" }));
    throw new Error(`${error.message}; renderer state: ${JSON.stringify(state)}`);
  }
  const openButton = await waitFor(
    `${name} FileCard open control`,
    () =>
      session
        .execute(
          `const button = [...document.querySelectorAll('button')].find(button => button.textContent.trim() === 'Open game');
           if (!button) return false;
           const box = button.getBoundingClientRect();
           return {
             x: Math.round(box.left + box.width / 2),
             y: Math.round(box.top + box.height / 2),
             disabled: button.disabled,
           };`,
        )
        .catch(() => false),
    { timeoutMs },
  );
  await clickAt(session, openButton.x, openButton.y);
  try {
    await waitFor(
      `${name} to open in the real renderer`,
      () =>
        session
          .execute(
            `return location.pathname === '/' && !!document.querySelector('cg-board') &&
              [...document.querySelectorAll('[role="tablist"] [role="tab"]')].some(tab => tab.textContent.trim() === 'Practice');`,
          )
          .catch(() => false),
      { timeoutMs },
    );
  } catch (error) {
    const state = await session
      .execute("return { path: location.pathname, text: document.body.innerText.slice(0, 1000) }")
      .catch(() => ({ path: "unavailable", text: "unavailable" }));
    throw new Error(`${error.message}; renderer state: ${JSON.stringify(state)}`);
  }
}

async function selectPracticeTab(session, timeoutMs = FILES_PROBE_TIMEOUT_MS) {
  const tab = await reachableStableCoordinates(
    session,
    "the Practice tab",
    `[...document.querySelectorAll('[role="tab"]')].find(tab => tab.textContent.trim() === 'Practice')`,
    [],
    { timeoutMs },
  );
  await clickAt(session, tab.x, tab.y);
  await waitFor(
    "the Practice tab to show Start Practice",
    () =>
      session
        .execute("return document.body.innerText.includes('Start Practice')")
        .catch(() => false),
    { timeoutMs },
  );
}

