export const linkedCollectionArtifactAssertions = [
  "LC1 accumulated source preserves custom headers, variations, NAGs and provider occurrences",
  "LC2 linked export is byte-identical to its authoritative PGN",
  "LC3 restoring the migration archive recovers the independent database version",
  "LC4 the current search cache indexes exactly the authoritative source generation",
  "LC5 Database-choice migration preserves the prior PGN bytes",
  "LC6 Database-choice migration exposes one active chosen version and an inactive preserved original",
  "LC7 Database-choice migration preserves the original metadata meaning",
  "LC8 Database-choice migration preserves the complete database version in source and archive",
  "LC9 Database-choice position search resolves the chosen source generation",
  "LC10 the preserved original index refuses the previous reference search",
];

// These inspect only small, harness-owned collection fixtures. The native large-file test owns
// bounded streaming proof. Each assertion is independently callable for real-input staging.
export async function assertLinkedCollectionArtifact(assertion, artifacts) {
  if (assertion === linkedCollectionArtifactAssertions[0]) {
    const source = await readFile(artifacts.source, "utf8");
    const original = source.split(/\n(?=\[Event ")/)[0];
    if (
      !original.includes('[Custom "keep this tag"]') ||
      !original.includes("(1. d4 d5)") ||
      !original.includes("$1") ||
      (source.match(/\[Event /g) ?? []).length !== 2 ||
      (source.match(/https:\/\/www.chess.com\/game\/live\/123"/g) ?? []).length !== 1 ||
      (source.match(/https:\/\/www.chess.com\/game\/live\/456"/g) ?? []).length !== 1
    )
      throw new Error(assertion);
  } else if (assertion === linkedCollectionArtifactAssertions[1]) {
    if (!(await readFile(artifacts.source)).equals(await readFile(artifacts.exported)))
      throw new Error(assertion);
  } else if (assertion === linkedCollectionArtifactAssertions[2]) {
    const archive = await readFile(artifacts.archived, "utf8");
    if (
      (archive.match(/\[Event /g) ?? []).length !== 1 ||
      !archive.includes("1. c4 c5") ||
      archive.includes("1. d4")
    )
      throw new Error(assertion);
  } else if (assertion === linkedCollectionArtifactAssertions[3]) {
    const source = await readFile(artifacts.source);
    const database = new DatabaseSync(artifacts.cache, { readOnly: true });
    try {
      const rows = database
        .prepare(
          "SELECT LinkedSource.Ordinal FROM Games JOIN LinkedSource ON Games.ID=LinkedSource.GameID ORDER BY LinkedSource.Ordinal",
        )
        .all();
      const metadata = Object.fromEntries(
        database
          .prepare(
            "SELECT Name,Value FROM Info WHERE Name IN ('LinkedDigest','LinkedGeneration','DataRevision')",
          )
          .all()
          .map((row) => [row.Name, row.Value]),
      );
      if (
        rows.length !== 2 ||
        rows[0].Ordinal !== 0 ||
        rows[1].Ordinal !== 1 ||
        !metadata.LinkedGeneration ||
        Number(metadata.DataRevision) < 1 ||
        metadata.LinkedDigest !== createHash("sha256").update(source).digest("hex")
      )
        throw new Error(
          "LC4-cache metadata and ordinals match the authoritative source generation",
        );
      const search = JSON.parse(await readFile(artifacts.search, "utf8"));
      if (
        search[0].length !== 1 ||
        search[0][0].move !== "d5" ||
        search[1].length !== 1 ||
        search[1][0].white !== "Edited Player" ||
        search[1][0].linked?.ordinal !== 1 ||
        search[1][0].linked?.generation !== metadata.LinkedGeneration
      )
        throw new Error("LC4-search position results match the authoritative source generation");
    } finally {
      database.close();
    }
  } else if (assertion === linkedCollectionArtifactAssertions[4]) {
    if (
      !(await readFile(artifacts.migrationOriginal)).equals(
        await readFile(artifacts.migrationOriginalBefore),
      )
    )
      throw new Error(assertion);
  } else if (assertion === linkedCollectionArtifactAssertions[5]) {
    const disposition = JSON.parse(await readFile(artifacts.migrationDisposition, "utf8"));
    const original = disposition.collections.find(
      (collection) => collection.id === disposition.originalId,
    );
    const chosen = disposition.collections.find(
      (collection) => collection.id === disposition.chosenId,
    );
    if (
      disposition.collections.filter((collection) => collection.status === "ready").length !== 1 ||
      chosen?.status !== "ready" ||
      !chosen.database ||
      original?.status !== "preservedOriginal" ||
      original.database !== null
    )
      throw new Error(assertion);
  } else if (assertion === linkedCollectionArtifactAssertions[6]) {
    const disposition = JSON.parse(await readFile(artifacts.migrationDisposition, "utf8"));
    if (
      !disposition.metadataBefore ||
      JSON.stringify(disposition.metadataBefore) !== JSON.stringify(disposition.metadataAfter)
    )
      throw new Error(assertion);
  } else if (assertion === linkedCollectionArtifactAssertions[7]) {
    const expected = await readFile(artifacts.migrationExpectedDatabase);
    if (!expected.equals(await readFile(artifacts.migrationChosen)))
      throw new Error("LC8-source the chosen PGN equals the complete exported database version");
    if (!expected.equals(await readFile(artifacts.migrationArchiveExport)))
      throw new Error(
        "LC8-archive restoring the archive equals the complete exported database version",
      );
  } else if (assertion === linkedCollectionArtifactAssertions[8]) {
    const disposition = JSON.parse(await readFile(artifacts.migrationDisposition, "utf8"));
    const chosen = disposition.collections.find(
      (collection) => collection.id === disposition.chosenId,
    );
    const searched = JSON.parse(await readFile(artifacts.migrationSearch, "utf8"));
    if (
      !chosen ||
      searched[0].length !== 1 ||
      searched[0][0].move !== "c5" ||
      searched[1].length !== 1 ||
      searched[1][0].linked?.collection !== chosen.id ||
      searched[1][0].linked?.generation !== chosen.generation
    )
      throw new Error(assertion);
  } else if (assertion === linkedCollectionArtifactAssertions[9]) {
    const disposition = JSON.parse(await readFile(artifacts.migrationDisposition, "utf8"));
    if (!["conflict", "stale-game"].includes(disposition.oldReferenceError?.category))
      throw new Error(assertion);
  } else throw new Error(`Unknown collection assertion: ${assertion}`);
}

async function verifyLinkedCollections(session, filesWorkspace, profileDirectory) {
  const invoke = (command, args) => invokeIpc(session, "__verifyLinkedIPC", command, args);
  const workspace = { id: { id: filesWorkspaceId }, kind: "fileWorkspace" };
  const prefix = `verify-linked-${randomUUID()}`;
  const game = (id, moves, note) =>
    `[Event "Collection fixture"]\n[Site "https://www.chess.com"]\n[Date "2026.10.01"]\n[UTCTime "12:00:00"]\n[White "Player"]\n[Black "Opponent"]\n[Result "1-0"]\n[Link "https://www.chess.com/game/live/${id}"]\n[Custom "keep this tag"]\n\n1. ${moves} {${note}} 1-0\n\n`;
  const source = await createWorkspacePgnFixture(
    invoke,
    workspace,
    `${prefix}-source`,
    game("123", "e4 (1. d4 d5) $1 e5", "original note"),
  );
  const original = await createWorkspacePgnFixture(
    invoke,
    workspace,
    `${prefix}-database-original`,
    game("789", "c4 c5", "database version"),
  );
  const root = (await invoke("get_database_workspace", {})).root;
  const database = await invoke("create_workspace_database", { root, filename: `${prefix}.db3` });
  await invoke("convert_pgn", {
    progressId: prefix,
    files: [original.handle],
    database,
    timestamp: null,
    title: prefix,
    description: "Linked migration fixture",
  });
  const collection = await invoke("migrate_linked_collection", {
    requestId: randomUUID(),
    workspace,
    database,
    source: source.handle,
    choice: "pgn",
    account: { provider: "chesscom", account: prefix },
    destinationName: prefix,
  });
  const batch = await createWorkspacePgnFixture(
    invoke,
    workspace,
    `${prefix}-incoming`,
    game("123", "e4 e5", "provider overlap") + game("456", "d4 d5", "new game"),
  );
  await invoke("append_collection_games", { collection: collection.id, source: batch.handle });
  await invoke("append_collection_games", { collection: collection.id, source: batch.handle });
  const row = await filesRowCoordinates(session, source.name);
  await clickAt(session, row.x, row.y);
  await waitFor(
    "linked Library player-edit controls",
    () =>
      session.execute(
        `
    const owner = document.querySelector('[data-linked-collection=' + JSON.stringify(arguments[0]) + ']');
    if (!owner) return false;
    const values = [['Existing player name', 'Player'], ['Replacement player name', 'Edited Player']];
    for (const [label, value] of values) {
      const caption = [...owner.querySelectorAll('label')].find(node => node.textContent === label);
      const input = caption && document.getElementById(caption.htmlFor);
      if (!input) return false;
      Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(input, value);
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.dispatchEvent(new Event('change', { bubbles: true }));
    }
    return true;
  `,
        [collection.id],
      ),
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  const save = await waitFor(
    "linked Library player-edit Save",
    () =>
      session.execute(
        `
    const owner = document.querySelector('[data-linked-collection=' + JSON.stringify(arguments[0]) + ']');
    const button = owner && [...owner.querySelectorAll('button')].find(node => node.textContent.trim() === 'Save');
    if (!button || button.disabled) return false;
    button.scrollIntoView({ block: 'center' });
    const box = button.getBoundingClientRect();
    return { x: Math.round(box.left + box.width / 2), y: Math.round(box.top + box.height / 2) };
  `,
        [collection.id],
      ),
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  await clickAt(session, save.x, save.y);
  await waitFor(
    "linked Library player edit reaches its authoritative PGN",
    async () =>
      (await readFile(join(filesWorkspace, `${prefix}-source.pgn`), "utf8")).includes(
        '[White "Edited Player"]',
      ),
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  const exported = await createWorkspacePgnFixture(invoke, workspace, `${prefix}-exported`, "");
  await invoke("export_to_pgn", { file: collection.database, destination: exported.handle });
  const restored = await invoke("create_workspace_database", {
    root,
    filename: `${prefix}-restored.db3`,
  });
  await invoke("restore_collection_archive", { collection: collection.id, destination: restored });
  const archiveExport = await createWorkspacePgnFixture(
    invoke,
    workspace,
    `${prefix}-restored-export`,
    "",
  );
  await invoke("export_to_pgn", { file: restored, destination: archiveExport.handle });
  const artifacts = {
    source: join(filesWorkspace, `${prefix}-source.pgn`),
    exported: join(filesWorkspace, `${prefix}-exported.pgn`),
    archived: join(filesWorkspace, `${prefix}-restored-export.pgn`),
    cache: join(
      profileDirectory,
      ".local/share/com.chessriddle.studio/collections",
      `${collection.id}.db3`,
    ),
    search: join(filesWorkspace, `${prefix}-search.json`),
  };
  const search = await invoke("search_position", {
    file: collection.database,
    query: {
      position: {
        fen: "rnbqkbnr/pppppppp/8/8/3P4/8/PPP1PPPP/RNBQKBNR b KQkq d3 0 1",
        type_: "exact",
      },
    },
    tabId: `${prefix}-search`,
    ticket: null,
  });
  await writeFile(artifacts.search, JSON.stringify(search));
  // Exercise Database choice with an already automatically indexed prior source. All files,
  // IPC replies and evidence below belong to this disposable actual-app fixture.
  const priorOriginal = await createWorkspacePgnFixture(
    invoke,
    workspace,
    `${prefix}-prior-original`,
    game("321", "e4 e5", "independent PGN version"),
    "game",
  );
  const originals = await invoke("list_linked_collections", { workspace, ticket: null });
  const priorCollection = originals.find(
    (entry) => entry.file.id.id === priorOriginal.handle.id.id,
  );
  if (!priorCollection?.database || priorCollection.status !== "ready")
    throw new Error("Database-choice fixture requires an automatically indexed prior PGN");
  const metadataFor = (listing, file) => {
    const visit = (entries) => entries.flatMap((entry) => [entry, ...visit(entry.children ?? [])]);
    return visit(listing.entries).find((entry) => entry.handle.id.id === file.id.id)?.metadata;
  };
  const metadataBefore = metadataFor(
    await invoke("list_file_workspace", { workspace, ticket: null }),
    priorOriginal.handle,
  );
  artifacts.migrationOriginal = join(filesWorkspace, `${prefix}-prior-original.pgn`);
  artifacts.migrationOriginalBefore = join(filesWorkspace, `${prefix}-prior-before.pgn`);
  await writeFile(artifacts.migrationOriginalBefore, await readFile(artifacts.migrationOriginal));
  const databaseInput = await createWorkspacePgnFixture(
    invoke,
    workspace,
    `${prefix}-database-choice-input`,
    game("789", "c4 c5", "database version") + game("790", "Nf3 Nf6", "second database game"),
  );
  const chosenDatabase = await invoke("create_workspace_database", {
    root,
    filename: `${prefix}-database-choice.db3`,
  });
  await invoke("convert_pgn", {
    progressId: `${prefix}-database-choice`,
    files: [databaseInput.handle],
    database: chosenDatabase,
    timestamp: null,
    title: `${prefix}-database-choice`,
    description: "Database-choice original retirement fixture",
  });
  const expectedDatabase = await createWorkspacePgnFixture(
    invoke,
    workspace,
    `${prefix}-database-choice-expected`,
    "",
  );
  await invoke("export_to_pgn", { file: chosenDatabase, destination: expectedDatabase.handle });
  const databaseChoice = await invoke("migrate_linked_collection", {
    requestId: randomUUID(),
    workspace,
    database: chosenDatabase,
    source: priorOriginal.handle,
    choice: "database",
    account: null,
    destinationName: `${prefix}-database-chosen`,
  });
  const allCollections = await invoke("list_linked_collections", { workspace, ticket: null });
  const relatedCollections = allCollections.filter(
    (entry) => entry.id === databaseChoice.id || entry.file.id.id === priorOriginal.handle.id.id,
  );
  const metadataAfter = metadataFor(
    await invoke("list_file_workspace", { workspace, ticket: null }),
    priorOriginal.handle,
  );
  const restoredDatabaseChoice = await invoke("create_workspace_database", {
    root,
    filename: `${prefix}-database-choice-restored.db3`,
  });
  await invoke("restore_collection_archive", {
    collection: databaseChoice.id,
    destination: restoredDatabaseChoice,
  });
  const databaseArchiveExport = await createWorkspacePgnFixture(
    invoke,
    workspace,
    `${prefix}-database-choice-archive`,
    "",
  );
  await invoke("export_to_pgn", {
    file: restoredDatabaseChoice,
    destination: databaseArchiveExport.handle,
  });
  artifacts.migrationChosen = join(filesWorkspace, `${prefix}-database-chosen.pgn`);
  artifacts.migrationExpectedDatabase = join(
    filesWorkspace,
    `${prefix}-database-choice-expected.pgn`,
  );
  artifacts.migrationArchiveExport = join(filesWorkspace, `${prefix}-database-choice-archive.pgn`);
  artifacts.migrationDisposition = join(
    filesWorkspace,
    `${prefix}-database-choice-disposition.json`,
  );
  const migrationQuery = {
    position: {
      fen: "rnbqkbnr/pppppppp/8/8/2P5/8/PP1PPPPP/RNBQKBNR b KQkq c3 0 1",
      type_: "exact",
    },
  };
  const migrationSearch = await invoke("search_position", {
    file: databaseChoice.database,
    query: migrationQuery,
    tabId: `${prefix}-chosen-search`,
    ticket: null,
  });
  const oldSearchArgs = {
    file: priorCollection.database,
    query: migrationQuery,
    tabId: `${prefix}-old-reference`,
    ticket: null,
  };
  const oldSearch = await invokeJsonAndWait(
    session,
    "preserved original reference refusal",
    "__verifyOriginalRefusal",
    `window.__TAURI_INTERNALS__.invoke("search_position", ${JSON.stringify(oldSearchArgs)})`,
  );
  const oldReferenceError = oldSearch.result.rejected
    ? JSON.parse(oldSearch.result.rejected)
    : null;
  artifacts.migrationSearch = join(filesWorkspace, `${prefix}-database-choice-search.json`);
  await writeFile(artifacts.migrationSearch, JSON.stringify(migrationSearch));
  await writeFile(
    artifacts.migrationDisposition,
    JSON.stringify({
      collections: relatedCollections,
      originalId: priorCollection.id,
      chosenId: databaseChoice.id,
      metadataBefore,
      metadataAfter,
      oldReferenceError,
    }),
  );
  await waitFor(
    "Database-choice preserved original appears in Library",
    () =>
      session.execute(
        `window.dispatchEvent(new Event('focus'));
         const row = document.querySelector('[role="treeitem"][aria-label=' + JSON.stringify(arguments[0]) + ']');
         if (!row) return false;
         return true;`,
        [priorOriginal.name],
      ),
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  const originalRow = await filesRowCoordinates(session, priorOriginal.name);
  await clickAt(session, originalRow.x, originalRow.y);
  await waitFor(
    "Database-choice original role retains its real preview without old index controls",
    () =>
      session.execute(
        `
    const role = document.querySelector('[data-preserved-original=' + JSON.stringify(arguments[0]) + ']');
    const detail = role?.closest('.mantine-Paper-root');
    const board = detail?.querySelector('.cg-wrap');
    if (!role || !board || detail.querySelector('[data-linked-collection]')) return false;
    const bounds = board.getBoundingClientRect();
    return role.textContent.includes('Preserved original') && bounds.width > 0 && bounds.height > 0;
  `,
        [priorCollection.id],
      ),
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  for (const assertion of linkedCollectionArtifactAssertions) {
    try {
      await assertLinkedCollectionArtifact(assertion, artifacts);
      check(true, assertion);
    } catch (error) {
      check(false, assertion, error.message);
    }
  }
  console.log(`  .. linked collection disposable artifacts: ${JSON.stringify(artifacts)}`);
  // Leave the existing Library, explorer, opening and file-freshness acceptance paths active.
  // The fixture uses the same native migration/append boundary as the account action.
  await showLibraryOverview(session);
}

async function verifyDatabaseOrientation(session) {
  const invoke = (command, args) => invokeIpc(session, "__verifyOrientationIPC", command, args);
  const wait = (label, probe) => waitFor(label, probe, { timeoutMs: FILES_PROBE_TIMEOUT_MS });
  const coordinates = (label, script, args = []) =>
    reachableStableCoordinates(session, label, script, args);
  const boardIs = (side) =>
    wait(`orientation board is ${side}`, () =>
      session.execute(
        `return location.pathname === '/' && !!document.querySelector('[role="grid"][aria-label=' + JSON.stringify('Chessboard, ' + arguments[0] + ' orientation') + ']')`,
        [side],
      ),
    );
  const activeTree = async () => (await readActiveTabTree(session)).tree;
  // The surrounding NAG scenario disables autosave. Change it through the real settings control
  // for this scenario and restore its prior value before returning to the surrounding checks.
  let previousAutoSave;
  const setAutoSave = async (enabled) => {
    await goToSettings(session);
    // Auto Save lives in Analysis & notation since fecfa6daa; inactive panels stay mounted hidden.
    const category = await coordinates(
      "the Settings Analysis & notation category",
      `document.querySelector('[role="tab"][data-settings-category="analysis"]')`,
    );
    await clickAt(session, category.x, category.y);
    await wait("the Settings Analysis & notation category to be selected", () =>
      session.execute(
        `return document.querySelector('[role="tab"][data-settings-category="analysis"]')?.getAttribute('aria-selected') === 'true'`,
      ),
    );
    const checked = await wait("orientation Auto Save control", () =>
      session.execute(`
      const input = document.querySelector('input[aria-label="Auto Save"]');
      if (!input) return false;
      const panel = input.closest('[role="tabpanel"]');
      if (panel && (panel.hidden || getComputedStyle(panel).display === 'none')) return false;
      return { checked: input.checked };
    `),
    );
    previousAutoSave ??= checked.checked;
    if (checked.checked !== enabled) {
      const control = await coordinates(
        "orientation Auto Save switch",
        `document.querySelector('input[aria-label="Auto Save"]')?.closest('.mantine-Switch-root')`,
      );
      await clickAt(session, control.x, control.y);
      await wait("orientation Auto Save setting applied", () =>
        session.execute(
          `return document.querySelector('input[aria-label="Auto Save"]')?.checked === arguments[0]`,
          [enabled],
        ),
      );
    }
  };
  let database;
  let blackGame;
  let whiteGame;
  const title = "verify orientation database";
  const open = async (game) => {
    await showLibraryOverview(session);
    await wait("orientation database in Library", () =>
      session.execute(
        `window.dispatchEvent(new Event('focus')); return [...document.querySelectorAll('[role="treeitem"]')].some(node => node.getAttribute('aria-label') === arguments[0])`,
        [title],
      ),
    );
    const opener = await coordinates(
      "orientation database opener",
      `[...[...document.querySelectorAll('[role="treeitem"]')].find(node => node.getAttribute('aria-label') === arguments[0]).querySelectorAll('button')].find(node => node.textContent.trim() === 'Open database')`,
      [title],
    );
    await clickAt(session, opener.x, opener.y);
    await wait("orientation database route", () =>
      session.execute("return location.pathname === arguments[0]", [
        `/databases/${database.id.id}`,
      ]),
    );
    const gameRow = await coordinates(
      "orientation game row",
      `[...document.querySelectorAll('tbody tr')].find(node => node.textContent.includes(arguments[0]) && node.textContent.includes(arguments[1]))`,
      [game.white, game.black],
    );
    await clickAt(session, gameRow.x, gameRow.y);
    await clickButton(session, "Open game");
    await wait("orientation analysis route", () =>
      session.execute("return location.pathname === '/' && !!document.querySelector('cg-board')"),
    );
  };
  const seeded = await assertion(
    "AO1 an owner's Black game opens Black without dirtying or writing the native row",
    async () => {
      await setAutoSave(true);
      const workspace = { id: { id: filesWorkspaceId }, kind: "fileWorkspace" };
      const pgn = Array.from({ length: 12 }, (_, index) => {
        const ownerIsWhite = index >= 10;
        const opponent = `Orientation Opponent ${index}`;
        return `[Event "Orientation ${index}"]\n[White "${ownerIsWhite ? "Orientation Owner" : opponent}"]\n[Black "${ownerIsWhite ? opponent : "Orientation Owner"}"]\n[Result "*"]\n\n1. e4 e5 *\n`;
      }).join("\n");
      const source = await createWorkspacePgnFixture(invoke, workspace, "verify-orientation", pgn);
      const root = (await invoke("get_database_workspace", {})).root;
      database = await invoke("create_workspace_database", {
        root,
        filename: "verify-orientation.db3",
      });
      await invoke("convert_pgn", {
        progressId: `verify-orientation:${randomUUID()}`,
        files: [source.handle],
        database,
        title,
        description: "Orientation proof",
        ticket: null,
      });
      const rows = await invoke("get_games", {
        file: database,
        query: {
          options: { page: 1, pageSize: 25, sort: "id", direction: "asc", skipCount: false },
        },
        ticket: null,
      });
      if (rows.count !== 12) throw new Error(`expected 12 imported games, received ${rows.count}`);
      blackGame = rows.data.find((game) => game.white === "Orientation Opponent 0");
      whiteGame = rows.data.find((game) => game.black === "Orientation Opponent 10");
      if (!blackGame || !whiteGame) throw new Error("orientation fixture games are missing");
      await open(blackGame);
      await boardIs("Black");
      await wait("inferred orientation stays clean", async () => {
        const tree = await activeTree();
        return tree?.headers.orientation === "black" && tree.dirty === false;
      });
      const current = await invoke("get_db_game", {
        file: database,
        gameId: blackGame.id,
        linked: null,
        ticket: null,
      });
      if (
        current.kind !== "found" ||
        current.game.orientation !== undefined ||
        current.game.stamp !== blackGame.stamp
      )
        throw new Error(`inference wrote the database row: ${JSON.stringify(current)}`);
      await closeSelectedWorkspaceTab(session);
    },
  );
  await assertion(
    "AO2 flipping the owner's White game autosaves Black and reopening retains Black",
    async () => {
      if (!seeded) throw new Error("not attempted: AO1 fixture setup failed");
      await open(whiteGame);
      await boardIs("White");
      await clickButton(session, "Flip Board", true);
      await boardIs("Black");
      const saved = await wait("native orientation autosave", async () => {
        const current = await invoke("get_db_game", {
          file: database,
          gameId: whiteGame.id,
          linked: null,
          ticket: null,
        });
        return (
          current.kind === "found" &&
          current.game.orientation === "black" &&
          current.game.stamp !== whiteGame.stamp &&
          current.game
        );
      });
      await wait("orientation autosave acknowledged by renderer", async () => {
        const tree = await activeTree();
        return tree?.dirty === false && tree.sourceStamp === saved.stamp;
      });
      await closeSelectedWorkspaceTab(session);
      await open(whiteGame);
      await boardIs("Black");
      const path = `${screenshotPath ?? join(tmpdir(), `chessfable-orientation-${process.pid}`)}.database-orientation.png`;
      await writeFile(path, Buffer.from(await session.screenshot(), "base64"));
      console.log(`  .. database-orientation screenshot: ${path}`);
      await closeSelectedWorkspaceTab(session);
    },
  );
  await assertion(
    "AO3 orientation verification restores the surrounding autosave preference",
    async () => {
      if (previousAutoSave === undefined) throw new Error("Auto Save control was unavailable");
      await setAutoSave(previousAutoSave);
      await showLibraryOverview(session);
    },
  );
}

// Staged 2026-11-08 by breaking the product one change at a time in a disposable release build;
// each run printed the named FAIL line and `pnpm verify:app` exited 1, the documented failure status.
// PO1: renaming the overview-headline test id -> "timed out waiting for player overview statistics loaded".
// PO2: the White row given Black's statistics -> PO2 FAIL. PO3: performance without dp -> PO3 FAIL.
// PO4: the last-games query without sides "Any" -> "unexpected last-games list" with the unrelated games.
// PO6: a row click whose tab creation throws -> PO6 FAIL, with PO1-PO5 still ok.
// PO5 is argued, not staged: it fails only if the screenshot write fails, and the shared --screenshot
// prefix is written by earlier journeys first, so an unwritable path stops the suite before PO5.
async function verifyPlayerOverview(session) {
  const invoke = (command, args) => invokeIpc(session, "__verifyPlayerOverviewIPC", command, args);
  const wait = (label, probe) => waitFor(label, probe, { timeoutMs: FILES_PROBE_TIMEOUT_MS });
  const pointer = (label, script, args = []) =>
    reachableStableCoordinates(session, label, script, args);
  const assertion = async (label, prerequisite, action) => {
    if (prerequisite.error) {
      check(false, label, prerequisite.error);
      return prerequisite;
    }
    try {
      const value = await action();
      check(true, label);
      return { value };
    } catch (error) {
      check(false, label, error.message);
      return { error: `not attempted: ${label}: ${error.message}` };
    }
  };
  const player = "Overview Player";
  const title = "verify player overview database";
  // Import out of date order so descending IDs cannot masquerade as newest first.
  const games = [
    {
      day: "03",
      white: player,
      black: "Overview Opponent C",
      whiteElo: 1800,
      blackElo: 1600,
      result: "1/2-1/2",
    },
    {
      day: "06",
      white: "Overview Opponent F",
      black: player,
      whiteElo: 1900,
      blackElo: 1800,
      result: "1-0",
    },
    {
      day: "01",
      white: player,
      black: "Overview Opponent A",
      whiteElo: 1800,
      blackElo: 1400,
      result: "1-0",
    },
    {
      day: "05",
      white: "Overview Opponent E",
      black: player,
      whiteElo: 1800,
      blackElo: 1800,
      result: "1/2-1/2",
    },
    {
      day: "02",
      white: player,
      black: "Overview Opponent B",
      whiteElo: 1800,
      blackElo: 1500,
      result: "1-0",
    },
    {
      day: "04",
      white: player,
      black: "Overview Opponent D",
      whiteElo: 1800,
      blackElo: 1700,
      result: "0-1",
    },
    ...["07", "08", "09"].map((day) => ({
      day,
      white: "Unrelated White",
      black: "Unrelated Black",
      whiteElo: 2100,
      blackElo: 2200,
      result: "1-0",
    })),
  ];
  let database;
  const opened = await assertion(
    "PO1 verifyPlayerOverview seeds nine native games and opens Players → Overview Player → Overview",
    {},
    async () => {
      const pgn = games
        .map(
          (game) =>
            `[Event "Overview ${game.day}"]\n[Site "Overview fixture"]\n[Date "2026.10.${game.day}"]\n[Round "${Number(game.day)}"]\n[White "${game.white}"]\n[Black "${game.black}"]\n[WhiteElo "${game.whiteElo}"]\n[BlackElo "${game.blackElo}"]\n[Result "${game.result}"]\n\n1. e4 e5 ${game.result}\n`,
        )
        .join("\n");
      const workspace = { id: { id: filesWorkspaceId }, kind: "fileWorkspace" };
      const source = await createWorkspacePgnFixture(
        invoke,
        workspace,
        "verify-player-overview",
        pgn,
      );
      const root = (await invoke("get_database_workspace", {})).root;
      database = await invoke("create_workspace_database", {
        root,
        filename: "verify-player-overview.db3",
      });
      await invoke("convert_pgn", {
        progressId: `verify-player-overview:${randomUUID()}`,
        files: [source.handle],
        database,
        title,
        description: "Player Overview proof",
        ticket: null,
      });
      const imported = await invoke("get_games", {
        file: database,
        query: {
          options: { page: 1, pageSize: 25, sort: "id", direction: "asc", skipCount: false },
        },
        ticket: null,
      });
      if (imported.count !== 9 || imported.data.length !== 9)
        throw new Error(`expected nine imported games: ${JSON.stringify(imported)}`);
      await showLibraryOverview(session);
      await wait("player overview database in Library", () =>
        session.execute(
          `window.dispatchEvent(new Event('focus')); return [...document.querySelectorAll('[role="treeitem"]')].some(node => node.getAttribute('aria-label') === arguments[0])`,
          [title],
        ),
      );
      const opener = await pointer(
        "player overview database opener",
        `[...[...document.querySelectorAll('[role="treeitem"]')].find(node => node.getAttribute('aria-label') === arguments[0]).querySelectorAll('button')].find(node => node.textContent.trim() === 'Open database')`,
        [title],
      );
      await clickAt(session, opener.x, opener.y);
      await wait("player overview database route", () =>
        session.execute("return location.pathname === arguments[0]", [
          `/databases/${database.id.id}`,
        ]),
      );
      const players = await pointer(
        "player overview Players tab",
        `[...document.querySelectorAll('[role="tab"]')].find(node => node.textContent.trim() === 'Players')`,
      );
      await clickAt(session, players.x, players.y);
      const row = await pointer(
        "player overview player row",
        `[...document.querySelectorAll('[data-database-pane="table"] tbody tr')].find(node => [...node.querySelectorAll('td')].some(cell => cell.textContent.trim() === arguments[0]))`,
        [player],
      );
      await clickAt(session, row.x, row.y);
      const overview = await pointer(
        "player overview Overview tab",
        `[...document.querySelectorAll('[data-database-pane="preview"] [role="tab"]')].find(node => node.textContent.trim() === 'Overview')`,
      );
      await clickAt(session, overview.x, overview.y);
      await wait("player overview statistics loaded", () =>
        session.execute(
          `return !!document.querySelector('[data-testid="overview-headline"]') && !!document.querySelector('[data-testid="overview-opponents"]')`,
        ),
      );
    },
  );
  await assertion(
    "PO2 verifyPlayerOverview shows White 4 Games 62.5% +2 =1 −1, Black 2 Games 25% +0 =1 −1 and total 6 Games 50%",
    opened,
    async () => {
      const text =
        await session.execute(`return Object.fromEntries(['headline', 'white', 'black'].map(key =>
        [key, document.querySelector('[data-testid="overview-' + key + '"]')?.innerText.replace(/\\s+/g, ' ').trim()]));`);
      if (
        !text.white?.includes("As White") ||
        !text.white.includes("4 Games 62.5% +2 =1 −1") ||
        !text.black?.includes("As Black") ||
        !text.black.includes("2 Games 25% +0 =1 −1") ||
        !text.headline?.includes("6 Games 50% +2 =2 −2")
      )
        throw new Error(`unexpected Overview results: ${JSON.stringify(text)}`);
    },
  );
  await assertion(
    "PO3 verifyPlayerOverview shows hand-computed average opponent and FIDE performance for total and both colours",
    opened,
    async () => {
      // Rp = Ra + dp(p), p rounded to 2 decimals, FIDE table 8.1(a).
      // White: Ra = (1400+1500+1600+1700)/4 = 1550, p = (2+0.5)/4 = 0.625 → 0.63,
      // dp(0.63) = +95, Rp = 1645. Black: Ra = (1800+1900)/2 = 1850,
      // p = (0+0.5)/2 = 0.25, dp(0.25) = −193, Rp = 1657.
      // Total: Ra = 9900/6 = 1650, p = (2+2*0.5)/6 = 0.50, dp(0.50) = 0, Rp = 1650.
      const lines =
        await session.execute(`return [...document.querySelectorAll('[data-testid="overview-opponents"] p')]
        .map(node => node.innerText.replace(/\\s+/g, ' ').trim());`);
      const expected = [
        "Avg. opponent 1650 · Performance 1650 · 6 rated",
        "As White: Avg. opponent 1550 · Performance 1645 · 4 rated",
        "As Black: Avg. opponent 1850 · Performance 1657 · 2 rated",
      ];
      if (JSON.stringify(lines) !== JSON.stringify(expected))
        throw new Error(
          `unexpected opponent lines: ${JSON.stringify(lines)}, expected ${JSON.stringify(expected)}`,
        );
    },
  );
  const listed = await assertion(
    "PO4 verifyPlayerOverview last games contains exactly six selected-player opponents newest first and no unrelated players",
    opened,
    async () => {
      await wait("player overview last-games rows loaded", () =>
        session.execute(`return document.querySelectorAll('[data-last-games] button').length > 0`),
      );
      const observed = await session.execute(`return {
        heading: document.querySelector('[data-last-games]')?.innerText,
        rows: [...document.querySelectorAll('[data-last-games] button')].map(node => node.innerText.replace(/\\s+/g, ' ').trim()),
      };`);
      const expected = games
        .filter((game) => game.white === player || game.black === player)
        .sort((a, b) => b.day.localeCompare(a.day))
        .map((game) => ({
          date: `2026.10.${game.day}`,
          opponent: game.white === player ? game.black : game.white,
          elo: game.white === player ? game.blackElo : game.whiteElo,
        }));
      if (
        !observed.heading?.includes("Last games") ||
        observed.rows.length !== 6 ||
        observed.rows.some(
          (row, index) =>
            !row.includes(expected[index].date) ||
            !row.includes(`${expected[index].opponent} (${expected[index].elo})`) ||
            row.includes("Unrelated"),
        )
      )
        throw new Error(
          `unexpected last-games list: ${JSON.stringify(observed)}, expected ${JSON.stringify(expected)}`,
        );
    },
  );
  await assertion("PO5 verifyPlayerOverview saves the Overview screenshot", opened, async () => {
    await session.execute(
      `document.querySelector('[data-testid="overview-headline"]').scrollIntoView({ block: 'start' }); return true;`,
    );
    const path = `${screenshotPath ?? join(tmpdir(), `chessfable-player-overview-${process.pid}`)}.player-overview.png`;
    await writeFile(path, Buffer.from(await session.screenshot(), "base64"));
    console.log(`  .. verifyPlayerOverview screenshot: ${path}`);
  });
  const analysis = await assertion(
    "PO6 verifyPlayerOverview clicking the newest last-game row opens that game's analysis tab",
    listed,
    async () => {
      const before = (await readActiveTabTree(session)).workspace;
      if (!before) throw new Error("player overview workspace snapshot is unreadable");
      const row = await pointer(
        "player overview newest game",
        `document.querySelector('[data-last-games] button')`,
      );
      await clickAt(session, row.x, row.y);
      await wait("player overview analysis route and players", () =>
        session.execute(
          `return location.pathname === '/' && !!document.querySelector('cg-board') && document.body.innerText.includes('Overview Opponent F') && document.body.innerText.includes(arguments[0])`,
          [player],
        ),
      );
      await wait("player overview analysis tab identity", async () => {
        const snapshot = await readActiveTabTree(session);
        return (
          snapshot.tab?.name === `Overview Opponent F - ${player}` &&
          !before.tabs.some((tab) => tab.value === snapshot.tab.value) &&
          snapshot.tree?.headers.white === "Overview Opponent F" &&
          snapshot.tree?.headers.black === player &&
          snapshot.tree?.headers.date === "2026.10.06"
        );
      });
    },
  );
  if (!analysis.error) await closeSelectedWorkspaceTab(session);
  await showLibraryOverview(session);
}

async function verifyNewGameToDatabase(session) {
  const invoke = (command, args) => invokeIpc(session, "__verifyNewGameIPC", command, args);
  const wait = (label, probe) => waitFor(label, probe, { timeoutMs: FILES_PROBE_TIMEOUT_MS });
  const pointer = (label, script, args = []) =>
    reachableStableCoordinates(session, label, script, args);
  const move = async (from, to) => {
    for (const square of [from, to]) {
      const point = await pointer(
        `new-game square ${square}`,
        `document.querySelector('cg-board')`,
      );
      const target = await session.execute(
        `
        const board = document.querySelector('cg-board');
        if (!board) return false;
        const box = board.getBoundingClientRect();
        return { x: Math.round(box.left + (arguments[0].charCodeAt(0) - 96.5) * box.width / 8), y: Math.round(box.top + (8.5 - Number(arguments[0][1])) * box.height / 8) };
      `,
        [square],
      );
      if (!point || !target) throw new Error("new-game board is unavailable");
      await clickAt(session, target.x, target.y);
    }
  };
  try {
    const source = (await listFixtureEntries(invoke)).find(
      (entry) => entry.name === openingRowName,
    )?.handle;
    if (!source) throw new Error("new-game seed fixture is unavailable");
    const root = (await invoke("get_database_workspace", {})).root;
    const database = await invoke("create_workspace_database", {
      root,
      filename: "verify-new-game.db3",
    });
    const title = "verify new game database";
    await invoke("convert_pgn", {
      progressId: `verify-new-game:${randomUUID()}`,
      files: [source],
      database,
      timestamp: null,
      title,
      description: "New game proof",
    });
    const read = () =>
      invoke("get_games", {
        file: database,
        query: {
          options: { page: 1, pageSize: 25, sort: "id", direction: "asc", skipCount: false },
        },
        ticket: null,
      });
    const before = await read();
    const priorIds = new Set(before.data.map((game) => game.id));
    await showLibraryOverview(session);
    await wait("new-game database in Library", () =>
      session.execute(
        `window.dispatchEvent(new Event('focus')); return [...document.querySelectorAll('[role="treeitem"]')].some(node => node.getAttribute('aria-label') === arguments[0]);`,
        [title],
      ),
    );
    const row = await pointer(
      "new-game database row",
      `[...document.querySelectorAll('[role="treeitem"]')].find(node => node.getAttribute('aria-label') === arguments[0])`,
      [title],
    );
    await clickAt(session, row.x, row.y);
    await clickButton(session, "New game");
    await wait("new-game analysis board", () =>
      session.execute("return location.pathname === '/' && !!document.querySelector('cg-board')"),
    );
    await move("e2", "e4");
    // A draft is named before its first save: Save PGN opens the naming dialog, and only its
    // confirmation writes the row (`requestUserSave` in BoardAnalysis.tsx).
    await clickButton(session, "Save PGN", true);
    // The dialog's first field is White; WebDriver returns it as an element reference.
    const whiteElement = await wait("new-game naming dialog", () =>
      session.execute(`
        const dialog = document.querySelector('[role="dialog"]');
        const input = dialog?.querySelector('form input');
        return dialog?.querySelector('form button[type="submit"]') && input ? input : null;
      `),
    );
    const whiteElementId = encodeURIComponent(whiteElement["element-6066-11e4-a52e-4f735466cecf"]);
    await session.call("POST", `/element/${whiteElementId}/clear`, {});
    await session.call("POST", `/element/${whiteElementId}/value`, { text: newGameWhite });
    const confirm = await pointer(
      "new-game naming confirmation",
      `document.querySelector('[role="dialog"] form button[type="submit"]')`,
    );
    await clickAt(session, confirm.x, confirm.y);
    const first = await wait("new-game insert through native read", async () => {
      const games = await read();
      const added = games.data.filter((game) => !priorIds.has(game.id));
      return (
        games.count === before.count + 1 &&
        added.length === 1 &&
        added[0].moves.includes("e4") &&
        added[0].white === newGameWhite &&
        added[0]
      );
    });
    await wait("new-game naming dialog closed", () =>
      session.execute(`return !document.querySelector('[role="dialog"]')`),
    );
    await move("e7", "e5");
    await clickButton(session, "Save PGN", true);
    const edited = await wait("new-game edit updates its original native row", async () => {
      const games = await read();
      const added = games.data.filter((game) => !priorIds.has(game.id));
      return (
        games.count === before.count + 1 &&
        added.length === 1 &&
        added[0].id === first.id &&
        added[0].moves.includes("e4 e5") &&
        added[0]
      );
    });
    check(
      !!edited,
      "NG1 New game inserts once and the next explicit save updates the same native database row",
    );
  } catch (error) {
    check(
      false,
      "NG1 New game inserts once and the next explicit save updates the same native database row",
      `${error.message}; renderer state: ${JSON.stringify(await rendererChromeState(session))}`,
    );
    // A dialog NG1 leaves open covers the navigation row the later scenarios drive.
    await session
      .call("POST", "/actions", {
        actions: [
          {
            type: "key",
            id: "new-game-dismiss",
            actions: [
              { type: "keyDown", value: "\uE00C" },
              { type: "keyUp", value: "\uE00C" },
            ],
          },
        ],
      })
      .catch(() => {});
  }
}

async function verifyGameOpening(session, ownedRoot, filesWorkspace) {
  const assertion = async (message, action) => {
    try {
      await action();
      check(true, message);
      return true;
    } catch (error) {
      const state = await session
        .execute(`return {
        path: location.pathname,
        selected: [...document.querySelectorAll('tbody tr[aria-selected="true"]')].map(row => row.textContent),
        controls: [...document.querySelectorAll('button')].filter(button => button.textContent.trim() === 'Open game').map(button => ({ disabled: button.disabled, text: button.textContent })),
      }`)
        .catch(() => ({ unavailable: true }));
      check(false, message, `${error.message}, renderer state: ${JSON.stringify(state)}`);
      return false;
    }
  };
  const wait = (label, script, args = []) =>
    waitFor(label, () => session.execute(script, args), { timeoutMs: FILES_PROBE_TIMEOUT_MS });
  const invoke = (command, args) => invokeIpc(session, "__verifyOpeningIPC", command, args);
  const coordinates = (script, args = []) =>
    reachableStableCoordinates(session, "game-opening pointer target", script, args);
  const button = (text) =>
    coordinates(
      `[...document.querySelectorAll('button')].find(node => node.textContent.trim() === arguments[0])`,
      [text],
    );
  const snapshot = async () => {
    const raw = await session.execute("return sessionStorage.getItem('workspace')");
    const workspace = raw && deserializeStorageValue(raw);
    if (!workspace) throw new Error("game-opening workspace snapshot is unreadable");
    return workspace;
  };
  const assertOpened = async (game, origin, before) => {
    await wait(
      "game-opening content and destination",
      `return location.pathname === '/' && document.body.innerText.replace(/\\s+/g, '').includes(arguments[0])`,
      [game.notation],
    );
    const workspace = await snapshot();
    const previousIds = new Set(before.tabs.map((entry) => entry.value));
    const admitted = workspace.tabs.filter((entry) => !previousIds.has(entry.value));
    // Admission can replace a lone new placeholder without increasing the total tab count.
    if (admitted.length !== 1 || admitted[0].value !== workspace.activeTab)
      throw new Error(
        `expected one newly admitted active tab: ${JSON.stringify({ admitted, activeTab: workspace.activeTab })}`,
      );
    const tab = workspace.tabs.find((entry) => entry.value === workspace.activeTab);
    if (
      !tab ||
      tab.name !== `${game.white} - ${game.black}` ||
      JSON.stringify(tab.gameOrigin) !== JSON.stringify(origin)
    ) {
      // File metadata contains extra fields. Identity is the handle and explicit index below.
      const actual = tab?.gameOrigin;
      const matches =
        origin.kind === "file" &&
        actual?.kind === "file" &&
        actual.gameNumber === origin.gameNumber &&
        actual.file.handle.id.id === origin.file.handle.id.id;
      if (!matches || tab.name !== `${game.white} - ${game.black}`)
        throw new Error(`wrong opened target: ${JSON.stringify(tab)}`);
    }
  };
  const saveSource = async (name) => {
    const path = `${screenshotPath ?? join(tmpdir(), `chessfable-game-opening-${process.pid}.png`)}.${name}.png`;
    await writeFile(path, Buffer.from(await session.screenshot(), "base64"));
    console.log(`  .. game-opening source screenshot: ${path}`);
  };
  let database;
  let file;
  let records;
  const seeded = await assertion(
    "GO1 game-opening fixtures contain two distinct native database and PGN games",
    async () => {
      const entries = await listFixtureEntries(invoke);
      file = entries.find((entry) => entry.name === openingRowName)?.handle;
      if (!file) throw new Error("dedicated PGN fixture was not listed");
      const count = await invoke("count_pgn_games", { file, ticket: null });
      if (count !== 2) throw new Error(`dedicated PGN fixture has ${count} games`);
      const root = (await invoke("get_database_workspace", {})).root;
      database = await invoke("create_workspace_database", {
        root,
        filename: "verify-game-opening.db3",
      });
      await invoke("convert_pgn", {
        progressId: `verify-opening:${randomUUID()}`,
        files: [file],
        database,
        timestamp: null,
        title: openingDatabaseTitle,
        description: "Dedicated game-opening proof",
      });
      const response = await invoke("get_games", {
        file: database,
        query: {
          sides: "WhiteBlack",
          options: { page: 1, pageSize: 25, sort: "id", direction: "asc", skipCount: false },
        },
        ticket: null,
      });
      records = openingGames.map((game) =>
        response.data.find((record) => record.white === game.white && record.black === game.black),
      );
      if (response.count !== 2 || records.some((record) => !record))
        throw new Error(`database fixture mismatch: ${JSON.stringify(response)}`);
    },
  );
  const requireSeed = () => {
    if (!seeded) throw new Error("not attempted: GO1 fixture setup failed");
  };
  await assertion(
    "DS1 native database storage_size is the exact decimal string of its file length",
    async () => {
      requireSeed();
      const metadata = await invoke("get_db_info", { file: database, ticket: null });
      if (metadata.status !== "ready")
        throw new Error(`expected ready database metadata, received ${JSON.stringify(metadata)}`);
      const expected = (
        await stat(join(ownedRoot, "verify-game-opening.db3"), { bigint: true })
      ).size.toString();
      if (metadata.storage_size !== expected)
        throw new Error(
          `expected storage_size ${JSON.stringify(expected)}, received ${JSON.stringify(metadata.storage_size)}`,
        );
    },
  );
  const overview = async () => {
    requireSeed();
    await showLibraryOverview(session);
    // The fixture uses native IPC directly, so it does not publish the renderer's usual cache
    // refresh after conversion. Wake the existing focus revalidation until both seeded sources
    // have appeared, keeping the document and its read reservations alive.
    await wait(
      "seeded Library collections",
      `window.dispatchEvent(new Event('focus')); return document.querySelector('[role="treeitem"][aria-label="verify-game-opening"]') && document.querySelector('[role="treeitem"][aria-label="verify opening database"]')`,
    );
  };
  await assertion(
    "LU1 Library has one sidebar destination and one tree containing both native source kinds",
    async () => {
      await overview();
      await wait(
        "mixed Library entries",
        `return document.querySelector('[role="treeitem"][aria-label="verify-game-opening"]') && document.querySelector('[role="treeitem"][aria-label="verify opening database"]')`,
      );
      const structure = await session.execute(`return {
      links: document.querySelectorAll('nav a[aria-label="Library"]').length,
      oldLinks: document.querySelectorAll('nav a[aria-label="Files"], nav a[aria-label="Databases"]').length,
      trees: document.querySelectorAll('[role="tree"]').length,
    }`);
      if (structure.links !== 1 || structure.oldLinks !== 0 || structure.trees !== 1)
        throw new Error(`mixed Library structure mismatch: ${JSON.stringify(structure)}`);
    },
  );
  await assertion(
    "LU2 Library selection switches from file preview to database Explore and actions",
    async () => {
      await overview();
      const fileRow = await filesRowCoordinates(session, openingRowName);
      await clickAt(session, fileRow.x, fileRow.y);
      await button("Open game");
      const row = await coordinates(
        `document.querySelector('[role="treeitem"][aria-label="verify opening database"]')`,
      );
      await clickAt(session, row.x, row.y);
      await wait(
        "database detail after file selection",
        `return [...document.querySelectorAll('a')].some(node => node.textContent.trim() === "Explore") && [...document.querySelectorAll('button')].some(node => node.textContent.trim() === "Add Games") && ![...document.querySelectorAll('button')].some(node => node.textContent.trim() === "Open game")`,
      );
    },
  );
  const databaseSurface = async () => {
    await overview();
    const open = await button("Open database");
    await clickAt(session, open.x, open.y);
    await wait("opened database route", "return location.pathname === arguments[0]", [
      `/databases/${database.id.id}`,
    ]);
  };
  const databaseRow = (game) =>
    coordinates(
      `[...document.querySelectorAll('tbody tr')].find(node => node.textContent.includes(arguments[0]))`,
      [game.white],
    );
  const filesSurface = async (name = openingRowName) => {
    requireSeed();
    const row = await filesRowCoordinates(session, name);
    await clickAt(session, row.x, row.y);
    await button("Open game");
  };
  const fileRow = (game) =>
    coordinates(
      `[...document.querySelectorAll('[role="option"]')].find(node => node.textContent.includes(arguments[0]))`,
      [game.white],
    );
  const enter = async (script, args) => {
    await wait(
      "game-opening row focus",
      `const row = (${script}); if (!row) return false; row.focus(); return document.activeElement === row;`,
      args,
    );
    const before = await snapshot();
    await session.call("POST", "/actions", {
      actions: [
        {
          type: "key",
          id: "opening-keyboard",
          actions: [
            { type: "keyDown", value: "\uE007" },
            { type: "keyUp", value: "\uE007" },
          ],
        },
      ],
    });
    return before;
  };
  await assertion(
    "GO2 the database card has a visible sibling Open database control before selection",
    async () => {
      await overview();
      await wait(
        "associated database opener",
        `const button = [...document.querySelectorAll('button')].find(node => node.textContent.trim() === 'Open database'); return button && !button.disabled && button.closest('[role="treeitem"]')?.textContent.includes(arguments[0]) && !button.parentElement.closest('button') && button.getBoundingClientRect().height > 0;`,
        [openingDatabaseTitle],
      );
      await saveSource("database-card");
    },
  );
  await assertion(
    "GO3 the labelled database control opens its handle route and synchronizes the database",
    async () => {
      await databaseSurface();
      await wait(
        "synchronized database heading",
        "return [...document.querySelectorAll('h1,h2,h3')].some(node => node.textContent === arguments[0])",
        [openingDatabaseTitle],
      );
    },
  );
  await assertion(
    "DS2 database explorer persists the successful selection with its exact decimal storage_size",
    async () => {
      requireSeed();
      const raw = await session.execute("return sessionStorage.getItem('database-view')");
      const selected = raw && deserializeStorageValue(raw)?.state?.database;
      const expected = (
        await stat(join(ownedRoot, "verify-game-opening.db3"), { bigint: true })
      ).size.toString();
      if (
        selected?.type !== "success" ||
        selected.file?.kind !== database.kind ||
        selected.file?.id?.id !== database.id.id ||
        selected.storage_size !== expected
      )
        throw new Error(
          `expected successful selection ${database.id.id} with storage_size ${JSON.stringify(expected)}, received ${JSON.stringify(selected)}`,
        );
    },
  );
  await assertion(
    "GO4 database single-click selects a preview without admitting a tab",
    async () => {
      await databaseSurface();
      const before = await snapshot();
      const row = await databaseRow(openingGames[1]);
      await clickAt(session, row.x, row.y);
      await wait(
        "database preview selection",
        "return [...document.querySelectorAll('tbody tr[aria-selected=\"true\"]')].some(node => node.textContent.includes(arguments[0]))",
        [openingGames[1].white],
      );
      if (
        JSON.stringify(await snapshot()) !== JSON.stringify(before) ||
        !(await session.execute("return location.pathname.startsWith('/databases/')"))
      )
        throw new Error("single click opened a tab");
    },
  );
  await assertion(
    "GO5 the labelled database game button opens the selected content and origin",
    async () => {
      await databaseSurface();
      const row = await databaseRow(openingGames[1]);
      await clickAt(session, row.x, row.y);
      await wait(
        "selected database game opening control",
        `return [...document.querySelectorAll('button')].some(node => node.textContent.trim() === "Open game" && !node.disabled)`,
      );
      const open = await button("Open game");
      if (open.disabled) throw new Error("database game button is disabled");
      await saveSource("database-game");
      const before = await snapshot();
      await clickAt(session, open.x, open.y);
      await assertOpened(
        openingGames[1],
        { kind: "database", database, gameId: records[1].id },
        before,
      );
    },
  );
  await assertion(
    "GO6 a fixed-coordinate double-click opens an initially unselected database game",
    async () => {
      await databaseSurface();
      const row = await databaseRow(openingGames[1]);
      if (row.selected !== "false")
        throw new Error("database double-click target was already selected");
      const before = await snapshot();
      await doubleClickAt(session, row.x, row.y);
      await assertOpened(
        openingGames[1],
        { kind: "database", database, gameId: records[1].id },
        before,
      );
    },
  );
  await assertion(
    "GO7 row-focused Enter opens the requested database game content and origin",
    async () => {
      await databaseSurface();
      const before = await enter(
        `[...document.querySelectorAll('tbody tr')].find(node => node.textContent.includes(arguments[0]))`,
        [openingGames[0].white],
      );
      await assertOpened(
        openingGames[0],
        { kind: "database", database, gameId: records[0].id },
        before,
      );
    },
  );
  await assertion("GO8 the Files preview has a visible enabled Open game control", async () => {
    await filesSurface();
    const open = await button("Open game");
    if (open.disabled) throw new Error("Files game button is disabled");
    await fileRow(openingGames[1]);
    await saveSource("file-game");
  });
  await assertion(
    "GO9 PGN single-click selects without opening and keeps row coordinates stationary",
    async () => {
      // FileCard needs enough width to render the preview notation.
      const previewWindowWidth = 1300;
      const previewWindowHeight = 850;
      const originalRect = await session.call("GET", "/window/rect");
      let failure;
      try {
        await session.call("POST", "/window/rect", {
          width: previewWindowWidth,
          height: previewWindowHeight,
        });
        const resizedRect = await session.call("GET", "/window/rect");
        console.log(`  .. GO9 native geometry: ${JSON.stringify({ originalRect, resizedRect })}`);
        if (resizedRect.width !== previewWindowWidth || resizedRect.height !== previewWindowHeight)
          throw new Error(
            `native resize did not reach ${previewWindowWidth}x${previewWindowHeight}: ${JSON.stringify(resizedRect)}`,
          );
        await filesSurface();
        await wait(
          "first PGN preview at the resized native geometry",
          "return document.body.innerText.replace(/\\s+/g, '').includes(arguments[0])",
          [openingGames[0].notation],
        );
        const before = await snapshot();
        const row = await fileRow(openingGames[1]);
        await clickAt(session, row.x, row.y);
        await wait(
          "PGN preview selection",
          'return [...document.querySelectorAll(\'[role="option"][aria-selected="true"]\')].some(node => node.textContent.includes(arguments[0]))',
          [openingGames[1].white],
        );
        // Wait for the new preview's actual notation, so this covers completion as well as selection.
        await wait(
          "second PGN preview",
          "return document.body.innerText.replace(/\\s+/g, '').includes(arguments[0])",
          [openingGames[1].notation],
        );
        const after = await fileRow(openingGames[1]);
        if (
          JSON.stringify(await snapshot()) !== JSON.stringify(before) ||
          !(await session.execute("return location.pathname === '/library'")) ||
          row.x !== after.x ||
          row.y !== after.y
        )
          throw new Error(`selection moved or opened the list: ${JSON.stringify({ row, after })}`);
      } catch (error) {
        failure = error;
      } finally {
        let restorationError;
        try {
          await session.call("POST", "/window/rect", originalRect);
          const restoredRect = await session.call("GET", "/window/rect");
          console.log(`  .. GO9 restored native geometry: ${JSON.stringify(restoredRect)}`);
          if (["x", "y", "width", "height"].some((key) => restoredRect[key] !== originalRect[key]))
            restorationError = new Error(
              `restored geometry differs from ${JSON.stringify(originalRect)}`,
            );
        } catch (error) {
          restorationError = error;
        }
        if (restorationError)
          failure = new Error(
            `GO9 native geometry restoration failed: ${restorationError.message}${failure ? `, original failure: ${failure.message}` : ""}`,
            { cause: restorationError },
          );
      }
      if (failure) throw failure;
    },
  );
  await assertion(
    "GO10 the labelled Files game button opens the selected fresh game and explicit index",
    async () => {
      await filesSurface();
      const row = await fileRow(openingGames[1]);
      await clickAt(session, row.x, row.y);
      const open = await button("Open game");
      const before = await snapshot();
      await clickAt(session, open.x, open.y);
      await assertOpened(
        openingGames[1],
        { kind: "file", file: { handle: file }, gameNumber: 1 },
        before,
      );
    },
  );
  await assertion(
    "GO11 a fixed-coordinate double-click opens an initially unselected non-first PGN game",
    async () => {
      await filesSurface();
      // The Library remembers the last game position per file (b16db962), so GO10 leaves openingGames[1] selected.
      const first = await fileRow(openingGames[0]);
      await clickAt(session, first.x, first.y);
      await wait(
        "first PGN game selected before GO11",
        'return [...document.querySelectorAll(\'[role="option"][aria-selected="true"]\')].some(node => node.textContent.includes(arguments[0])) && ![...document.querySelectorAll(\'[role="option"][aria-selected="true"]\')].some(node => node.textContent.includes(arguments[1]))',
        [openingGames[0].white, openingGames[1].white],
      );
      const row = await fileRow(openingGames[1]);
      if (row.selected !== "false") throw new Error("PGN double-click target was already selected");
      const before = await snapshot();
      await doubleClickAt(session, row.x, row.y);
      await assertOpened(
        openingGames[1],
        { kind: "file", file: { handle: file }, gameNumber: 1 },
        before,
      );
    },
  );
  await assertion(
    "GO12 row-focused Enter opens the requested PGN game content and explicit index",
    async () => {
      await filesSurface();
      const before = await enter(
        `[...document.querySelectorAll('[role="option"]')].find(node => node.textContent.includes(arguments[0]))`,
        [openingGames[1].white],
      );
      await assertOpened(
        openingGames[1],
        { kind: "file", file: { handle: file }, gameNumber: 1 },
        before,
      );
    },
  );
  await assertion("GO13 an empty PGN exposes no working Open game action", async () => {
    await filesSurface(emptyOpeningRowName);
    const open = await button("Open game");
    if (!open.disabled) throw new Error("empty-file game opener is enabled");
  });
  await assertion(
    "GO14 confirmed discard replaces the owning current game without admitting a tab",
    async () => {
      requireSeed();
      const before = await snapshot();
      const owner = before.tabs.find((tab) => tab.value === before.activeTab);
      if (
        owner?.gameOrigin.kind !== "file" ||
        owner.gameOrigin.gameNumber !== 1 ||
        owner.gameOrigin.file.numGames !== 2 ||
        owner.gameOrigin.file.handle.id.id !== file.id.id
      )
        throw new Error(`GO12 did not leave the second file game active: ${JSON.stringify(owner)}`);
      const admittedIds = before.tabs.map((tab) => tab.value);
      const readTree = () =>
        waitFor(
          "discard owner's coherent persisted tree",
          async () => {
            const rawWorkspace = await session.execute(
              "return sessionStorage.getItem('workspace')",
            );
            const workspace = rawWorkspace && deserializeStorageValue(rawWorkspace);
            const currentOwner = Array.isArray(workspace?.tabs)
              ? workspace.tabs.find((tab) => tab?.value === owner.value)
              : undefined;
            const treeKey = currentOwner?.treeKey ?? currentOwner?.value ?? null;
            // Publication can retire the captured key between requests. Read the workspace
            // and that exact key together, then retry only when the workspace changed.
            const observed = await session.execute(
              `return {
                rawWorkspace: sessionStorage.getItem('workspace'),
                rawTree: arguments[0] === null ? null : sessionStorage.getItem(arguments[0]),
              };`,
              [typeof treeKey === "string" ? treeKey : null],
            );
            if (observed.rawWorkspace !== rawWorkspace) return false;
            if (!workspace || !Array.isArray(workspace.tabs))
              throw new Error("discard owner's persisted workspace is unreadable");
            if (!currentOwner)
              throw new Error("discard owner's logical tab is absent from the workspace");
            if (typeof treeKey !== "string" || !treeKey)
              throw new Error("discard owner's physical tree key is invalid");
            const tree = observed.rawTree && deserializeStorageValue(observed.rawTree)?.state;
            if (!tree) throw new Error("discard owner's persisted tree is unreadable");
            return tree;
          },
          { timeoutMs: FILES_PROBE_TIMEOUT_MS },
        );
      await goToBoards(session);
      await wait(
        "discard owner's second game on the analysis surface",
        "return location.pathname === '/' && document.body.innerText.replace(/\\s+/g, '').includes(arguments[0])",
        [openingGames[1].notation],
      );
      const dirtyEvent = "verify:GO14-unsaved-owner-discard";
      let initialTree;
      const dirtyTree = await dirtyActiveTreeEventHeader(session, dirtyEvent, {
        locate: (_label, script, args) => coordinates(script, args),
        wait,
        keyboardId: "opening-keyboard",
        missingHeaderError: "second game has no Event header",
        diagnoseEditorValue: true,
        beforeRead: async () => {
          initialTree = await waitFor(
            "discard owner's clean second game publication",
            async () => {
              const tree = await readTree();
              return (
                tree.dirty === false &&
                tree.headers.event === "verify:opening-1" &&
                tree.headers.white === openingGames[1].white &&
                tree.headers.black === openingGames[1].black &&
                tree
              );
            },
            { timeoutMs: FILES_PROBE_TIMEOUT_MS },
          );
        },
        waitForDirty: () =>
          waitFor(
            "real PGN Update publishes the owner's unsaved Event edit",
            async () => {
              const tree = await readTree();
              return tree.dirty === true && tree.headers.event === dirtyEvent && tree;
            },
            { timeoutMs: FILES_PROBE_TIMEOUT_MS },
          ),
      });
      const accordionControl = `(() => {
        const info = [...document.querySelectorAll('[role="tab"]')].find(node => node.textContent.trim() === 'Info' && node.getAttribute('aria-selected') === 'true');
        const panel = info && document.getElementById(info.getAttribute('aria-controls'));
        return panel && [...panel.querySelectorAll('button.mantine-Accordion-control[aria-controls][aria-expanded]')].find(node => /^2\\./.test(node.textContent.trim()));
      })()`;
      const accordion = await coordinates(accordionControl);
      if (
        !(await session.execute(
          `return (${accordionControl}).getAttribute('aria-expanded') === 'true'`,
        ))
      )
        await clickAt(session, accordion.x, accordion.y);
      const activation = await enter(
        `(() => {
          const control = (${accordionControl});
          const list = control && document.getElementById(control.getAttribute('aria-controls'));
          return list && [...list.querySelectorAll('[role="option"]')].find(node => node.textContent.includes(arguments[0]));
        })()`,
        [openingGames[0].white],
      );
      if (JSON.stringify(activation) !== JSON.stringify(before))
        throw new Error("editing or selecting the discard target changed the owning workspace");
      await wait(
        "actual unsaved-changes confirmation for the dirty owner",
        `return [...document.querySelectorAll('[role="dialog"]')].some(dialog => dialog.innerText.includes('Unsaved changes') && [...dialog.querySelectorAll('button')].some(node => node.textContent.trim() === 'Close without saving'));`,
      );
      await saveSource("info-panel-discard");
      const discard = await coordinates(
        `(() => {
          const dialog = [...document.querySelectorAll('[role="dialog"]')].find(node => node.innerText.includes('Unsaved changes'));
          return dialog && [...dialog.querySelectorAll('button')].find(node => node.textContent.trim() === 'Close without saving');
        })()`,
      );
      await clickAt(session, discard.x, discard.y);
      const replacement = await waitFor(
        "confirmed discard replaces the dirty owner with the clean first file game",
        async () => {
          const workspace = await snapshot();
          const tab = workspace.tabs.find((entry) => entry.value === owner.value);
          const tree = await readTree();
          const visible = await session.execute(
            `return location.pathname === '/' && document.body.innerText.replace(/\\s+/g, '').includes(arguments[0]) && !document.querySelector('[role="dialog"]');`,
            [openingGames[0].notation],
          );
          return (
            visible &&
            workspace.activeTab === owner.value &&
            JSON.stringify(workspace.tabs.map((entry) => entry.value)) ===
              JSON.stringify(admittedIds) &&
            tab?.gameOrigin.kind === "file" &&
            tab.gameOrigin.gameNumber === 0 &&
            tab.gameOrigin.file.handle.id.id === file.id.id &&
            tree.dirty === false &&
            tree.headers.event === "verify:opening-0" &&
            tree.headers.white === openingGames[0].white &&
            tree.headers.black === openingGames[0].black &&
            tree.root.children[0]?.san === "e4" &&
            tree.root.children[0]?.children[0]?.san === "e5" && { workspace, tree }
          );
        },
        { timeoutMs: FILES_PROBE_TIMEOUT_MS },
      ).catch(async (error) => {
        throw new Error(
          `${error.message}, workspace: ${JSON.stringify(await snapshot())}, tree: ${JSON.stringify(await readTree())}`,
        );
      });
      console.log(
        `  .. GO14 owner ${owner.value}, admitted IDs ${JSON.stringify(admittedIds)}, Event ${initialTree.headers.event} -> ${dirtyTree.headers.event} -> ${replacement.tree.headers.event}, dirty ${initialTree.dirty} -> ${dirtyTree.dirty} -> ${replacement.tree.dirty}, file gameNumber 1 -> 0, confirmation gone`,
      );
    },
  );

  // Native lookup and full-game admission cannot be proved by mocked browser IPC.
  // Removal path: remove this block and CR1–CR4's header when citation lookup is retired.
  const citationLabels = [
    "0-1 Beerdsen,T (2520)-Bluebaum,M (2651) Elllobregat op 3rd Sant Boi de Llobregat 2022 (3)",
    "0-1 Srinath,R (2255)-Deac,B (2690) Titled Tuesday intern op 19th Dec Late Chess.com INT blitz 2023 (6)",
    "0-1 Unlisted,Z-Unknown,Q 2021 (99)",
  ];
  const citationWorkspace = { id: { id: filesWorkspaceId }, kind: "fileWorkspace" };
  const citationPrefix = `verify-citations-${randomUUID()}`;
  let citationPreparation;
  let citationDatabase;
  let linkedCitationSource;
  const setupCitations = async () => {
    citationPreparation = await createWorkspacePgnFixture(
      invoke,
      citationWorkspace,
      `${citationPrefix}-preparation`,
      `[Event "Citation preparation"]\n[White "Preparation"]\n[Black "Citations"]\n[Result "*"]\n\n{Before **${citationLabels[0]}** ordinary prose. ${citationLabels[1]} Missing: ${citationLabels[2]}} 1. e4 *\n`,
    );
    const citationDatabaseInput = await createWorkspacePgnFixture(
      invoke,
      citationWorkspace,
      `${citationPrefix}-database-input`,
      '[Event "Elllobregat op 3rd"]\n[Site "Sant Boi de Llobregat"]\n[Date "2022.12.01"]\n[Round "3"]\n[White "Beerdsen, Thomas"]\n[Black "Bluebaum, Matthias"]\n[WhiteElo "2520"]\n[BlackElo "2651"]\n[Result "0-1"]\n[FEN "8/8/8/8/8/8/6k1/K7 b - - 12 23"]\n[SetUp "1"]\n\n23... Kf3 0-1\n',
    );
    const citationRoot = (await invoke("get_database_workspace", {})).root;
    citationDatabase = await invoke("create_workspace_database", {
      root: citationRoot,
      filename: `${citationPrefix}.db3`,
    });
    await invoke("convert_pgn", {
      progressId: `${citationPrefix}:import`,
      files: [citationDatabaseInput.handle],
      database: citationDatabase,
      timestamp: null,
      title: citationPrefix,
      description: "Native citation acceptance",
    });
    linkedCitationSource = await createWorkspacePgnFixture(
      invoke,
      citationWorkspace,
      `${citationPrefix}-linked`,
      '[Event "Titled Tuesday intern op 19th Dec Late"]\n[Site "Chess.com INT blitz"]\n[Date "2023.12.19"]\n[Round "6"]\n[White "Srinath, Rao"]\n[Black "Deac, Bogdan"]\n[WhiteElo "2255"]\n[BlackElo "2690"]\n[Result "0-1"]\n[Custom "citation original"]\n\n1. d4 $1 {citation source annotation} (1. e4 e5) d5 0-1\n',
      "game",
    );
    console.log(
      `  .. citation disposable inputs: ${JSON.stringify({ preparation: join(filesWorkspace, `${citationPreparation.name}.pgn`), database: join(ownedRoot, `${citationPrefix}.db3`), linked: join(filesWorkspace, `${linkedCitationSource.name}.pgn`) })}`,
    );
  };
  const citationSurface = async () => {
    if (!citationPreparation || !citationDatabase || !linkedCitationSource)
      throw new Error("citation fixture setup did not finish");
    await showLibraryOverview(session);
    await wait(
      "citation preparation listed",
      `window.dispatchEvent(new Event('focus')); return document.querySelector('[role="treeitem"][aria-label="' + arguments[0] + '"]');`,
      [citationPreparation.name],
    );
    const row = await filesRowCoordinates(session, citationPreparation.name);
    await clickAt(session, row.x, row.y);
    await wait(
      "citation preparation Open game action enabled",
      "return [...document.querySelectorAll('button')].some(node => node.textContent.trim() === 'Open game' && !node.disabled)",
    );
    const open = await button("Open game");
    if (open.disabled) throw new Error("citation preparation Open game action is disabled");
    await clickAt(session, open.x, open.y);
    await wait(
      "citation preparation full notation",
      "return location.pathname === '/' && document.querySelector('[data-game-reference]')",
    );
  };
  const activateCitation = async (label) => {
    const target = await coordinates(
      `[...document.querySelectorAll('[data-game-reference]')].find(node => node.textContent === arguments[0])`,
      [label],
    );
    const before = await snapshot();
    await clickAt(session, target.x, target.y);
    await waitFor(
      "citation lookup terminal",
      async () => {
        const workspace = await snapshot();
        const terminalDialog = await session.execute(
          `const dialog = document.querySelector('[role="dialog"]'); return Boolean(dialog && !dialog.querySelector('[role="status"]'));`,
        );
        return (
          terminalDialog ||
          (workspace.activeTab !== before.activeTab &&
            workspace.tabs.some((entry) => entry.value === workspace.activeTab))
        );
      },
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
  };
  const completeCitationAdmission = async (white) => {
    const outcome = await waitFor(
      "citation automatic admission or enabled choice",
      async () => {
        const current = await readActiveTabTree(session);
        if (current.tree?.headers.white === white) return "opened";
        const choice = await session.execute(
          `return [...document.querySelectorAll('[role="dialog"] button')].some(node => !node.disabled && node.textContent.trim() === 'Open game' && node.closest('.mantine-Paper-root')?.textContent.includes(arguments[0]))`,
          [white],
        );
        return choice ? "choice" : false;
      },
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
    if (outcome === "choice") {
      const target = await coordinates(
        `[...document.querySelectorAll('[role="dialog"] button')].find(node => !node.disabled && node.textContent.trim() === 'Open game' && node.closest('.mantine-Paper-root')?.textContent.includes(arguments[0]))`,
        [white],
      );
      await clickAt(session, target.x, target.y);
    }
  };
  const readCitationTree = async () => {
    const current = await snapshot();
    const tab = current.tabs.find((entry) => entry.value === current.activeTab);
    const raw = await session.execute("return sessionStorage.getItem(arguments[0])", [
      tab.treeKey ?? tab.value,
    ]);
    return { tab, tree: raw && deserializeStorageValue(raw)?.state };
  };
  await assertion(
    "CR1 imported formatted citations preserve prose and expose accessible notation actions",
    async () => {
      await setupCitations();
      await citationSurface();
      const visible = await session.execute(
        `const buttons = [...document.querySelectorAll('[data-game-reference]')]; return { labels: buttons.map(node => node.textContent), bold: buttons[0]?.querySelector('strong')?.textContent, prose: document.body.innerText.includes('ordinary prose.') };`,
      );
      if (
        JSON.stringify(visible.labels) !== JSON.stringify(citationLabels) ||
        visible.bold !== citationLabels[0] ||
        !visible.prose
      )
        throw new Error(`citation notation mismatch: ${JSON.stringify(visible)}`);
    },
  );
  await assertion(
    "CR2 citation native database lookup admits the exact full game and starting FEN",
    async () => {
      await citationSurface();
      const before = await snapshot();
      await activateCitation(citationLabels[0]);
      await completeCitationAdmission("Beerdsen, Thomas");
      await waitFor(
        "citation database active tab after selection",
        async () => {
          const workspace = await snapshot();
          return (
            workspace.activeTab !== before.activeTab &&
            workspace.tabs.some((entry) => entry.value === workspace.activeTab)
          );
        },
        { timeoutMs: FILES_PROBE_TIMEOUT_MS },
      );
      await wait(
        "citation database tab",
        "return location.pathname === '/' && document.body.innerText.includes('Beerdsen')",
      );
      const { tab, tree } = await readCitationTree();
      if (
        before.tabs.some((entry) => entry.value === tab.value) ||
        tab.gameOrigin.kind !== "database" ||
        tab.gameOrigin.database.id.id !== citationDatabase.id.id ||
        tree?.headers.white !== "Beerdsen, Thomas" ||
        tree.headers.black !== "Bluebaum, Matthias" ||
        tree.headers.round !== "3" ||
        tree.root.fen !== "8/8/8/8/8/8/6k1/K7 b - - 12 23" ||
        tree.root.children[0]?.san !== "Kf3"
      )
        throw new Error(`citation database admission mismatch: ${JSON.stringify({ tab, tree })}`);
    },
  );
  await assertion(
    "CR3 citation native linked lookup admits original annotations, variations and file occurrence",
    async () => {
      await citationSurface();
      const priorActiveTab = (await snapshot()).activeTab;
      await activateCitation(citationLabels[1]);
      await completeCitationAdmission("Srinath, Rao");
      await waitFor(
        "citation linked active tab after selection",
        async () => {
          const workspace = await snapshot();
          return (
            workspace.activeTab !== priorActiveTab &&
            workspace.tabs.some((entry) => entry.value === workspace.activeTab)
          );
        },
        { timeoutMs: FILES_PROBE_TIMEOUT_MS },
      );
      await wait(
        "citation linked tab",
        "return location.pathname === '/' && document.body.innerText.includes('Srinath')",
      );
      const { tab, tree } = await readCitationTree();
      if (
        tab.gameOrigin.kind !== "file" ||
        tab.gameOrigin.file.handle.id.id !== linkedCitationSource.handle.id.id ||
        tab.gameOrigin.gameNumber !== 0 ||
        tree?.headers.other.Custom !== "citation original" ||
        !tree.linkedSource ||
        tree.root.children[0]?.comment !== "citation source annotation" ||
        !tree.root.children[0]?.nags.includes(1) ||
        tree.root.children[1]?.children[0]?.san !== "e5"
      )
        throw new Error(`citation linked admission mismatch: ${JSON.stringify({ tab, tree })}`);
    },
  );
  await assertion(
    "CR4 absent citation explains the ChessBase PGN Library prerequisite without admitting a tab",
    async () => {
      await citationSurface();
      const before = await snapshot();
      await activateCitation(citationLabels[2]);
      const missing = await session.execute(
        `const dialog = document.querySelector('[role="dialog"]'); return dialog?.textContent.includes('ChessBase as PGN') && dialog.textContent.includes('Library') && ![...dialog.querySelectorAll('button')].some(node => node.textContent.trim() === 'Open game');`,
      );
      const after = await snapshot();
      if (
        !missing ||
        JSON.stringify(before.tabs) !== JSON.stringify(after.tabs) ||
        before.activeTab !== after.activeTab
      )
        throw new Error("missing citation guidance or source-tab preservation mismatch");
      const close = await coordinates(
        `document.querySelector('[role="dialog"] .mantine-Modal-close')`,
      );
      await clickAt(session, close.x, close.y);
    },
  );
}

let cleanupSettled = false;
let signalShutdown;
const handleSignal = () => {
  if (signalShutdown) return;
  restoreRootPermissionsForCleanup("signal");
  signalShutdown = shutdown()
    .catch((error) => console.error(`cleanup failed: ${error.message}`))
    .finally(() => {
      cleanupSettled = true;
      process.exit(1);
    });
};

async function verifyFullApplication(profileDirectory, appEnvironment) {
  const practiceGame = 0;
  const largePracticeId = "verify-practice-large-00000000-0000-4000-8000-000000000001";
  const legacyPracticeId = "verify-practice-legacy-00000000-0000-4000-8000-000000000002";
  const legacyPracticeKey = `deck-${legacyPracticeId}-${practiceGame}`;
  const largePracticeName = "verify-practice-large";
  const extendedPracticeTree = buildPracticeFixtureTree();
  const oraclePracticePositions = collectPracticePositions(extendedPracticeTree);
  const initialPracticeTree = clonePracticeFixtureTree(extendedPracticeTree);
  const initialPracticePositions = prunePracticeFixtureTree(initialPracticeTree, 12_000);
  const extendedPracticePositions = prunePracticeFixtureTree(extendedPracticeTree, 12_500);
  if (
    initialPracticePositions.length !== 12_000 ||
    extendedPracticePositions.length !== 12_500 ||
    JSON.stringify(initialPracticePositions) !==
      JSON.stringify(oraclePracticePositions.slice(0, 12_000)) ||
    JSON.stringify(extendedPracticePositions) !==
      JSON.stringify(oraclePracticePositions.slice(0, 12_500))
  ) {
    throw new Error(
      `practice fixture disagreed with its independent card oracle (${initialPracticePositions.length}/${extendedPracticePositions.length}; expected ${oraclePracticePositions.length})`,
    );
  }
  const legacyPracticePositions = practicePositionsDocument(initialPracticePositions.slice(0, 3));
  const legacyPracticeLogs = legacyPracticePositions.slice(0, 2).map((position, index) => ({
    ...position.card,
    fen: position.fen,
    rating: index + 3,
  }));
  const legacyPracticeDocument = JSON.stringify({
    positions: legacyPracticePositions,
    logs: legacyPracticeLogs,
  });
  // WebKit local storage belongs to the isolated profile, but it can only be initialized through
  // the real application origin. Seed valid durable image owners, close cleanly, and only then
  // install the registry fixture that the asserted startup must reconcile.
  const retainedImageId = "11111111-1111-4111-8111-111111111111";
  const retainedImageBase64 =
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
  const retiredImageId = "22222222-2222-4222-8222-222222222222";
  const orphanImageId = "33333333-3333-4333-8333-333333333333";
  const ownerEngine = (id, imageId) => ({
    type: "local",
    id,
    name: `Fixture ${id}`,
    version: "1",
    handle: { id: { id: `fixture-executable-${id}` }, kind: "engine" },
    filename: "fixture-engine",
    imageHandle: { id: { id: imageId }, kind: "engineImage" },
  });
  console.log("  .. opening seed WebDriver session");
  const seedSession = await Session.open(APP_BINARY);
  await waitFor("the seed renderer to expose Tauri", () =>
    seedSession.execute("return typeof window.__TAURI_INTERNALS__ === 'object'").catch(() => false),
  );
  // `file-workspace` owns the Files workspace entry through startup reconciliation.
  // Disable auto-save in this throwaway profile so the NAG edit proves SAVE_FILE wrote it.
  await seedRendererLocalStorage(seedSession, {
    engines: JSON.stringify([
      ownerEngine("retained", retainedImageId),
      ownerEngine("retire-on-shutdown", retiredImageId),
    ]),
    "file-workspace": JSON.stringify({ id: { id: filesWorkspaceId }, kind: "fileWorkspace" }),
    "file-workspace-display-name": JSON.stringify("Files fixture"),
    "download-destination-capability": JSON.stringify({ id: "verify-download-destination" }),
    "auto-save": "false",
    [legacyPracticeKey]: legacyPracticeDocument,
  });
  const seedClose = await closeApplicationThroughTitlebar(seedSession, "seed");
  if (!seedClose.gone || seedClose.survivors.length > 0) {
    throw new Error(`seed processes survived close: ${seedClose.survivors.join(", ")}`);
  }
  const seedQuit = await seedSession.quit();
  if (!seedQuit.released) {
    console.log(`  .. seed WebDriver session release returned: ${seedQuit.error}`);
  }
  console.log("  .. seed app and WebKit processes are gone; reusing WebDriver after session quit");

  await verifyWorkspaceRestore(profileDirectory);

  const fixtureDirectory = join(profileDirectory, "path-owner-fixture");
  const ownedRoot = join(fixtureDirectory, "owned-database-root");
  const downloadDestination = join(fixtureDirectory, "download-destination");
  const permissionPuzzleRoot = join(fixtureDirectory, "permission-puzzles");
  const permissionEngineRoot = join(fixtureDirectory, "permission-engines");
  const orphanFile = join(fixtureDirectory, "orphan-opening-book.bin");
  const imageDirectory = join(
    profileDirectory,
    ".local/share/com.chessriddle.studio/engine-images",
  );
  const retainedImage = join(imageDirectory, retainedImageId);
  const retiredImage = join(imageDirectory, retiredImageId);
  const orphanImage = join(imageDirectory, orphanImageId);
  const filesWorkspace = join(fixtureDirectory, "files-workspace");
  const practiceDirectory = join(profileDirectory, ".local/share/com.chessriddle.studio/practice");
  const largePracticePath = join(filesWorkspace, `${largePracticeName}.pgn`);
  const largePracticeMetadataPath = join(filesWorkspace, `${largePracticeName}.info`);
  const legacyPracticePath = join(fixtureDirectory, "legacy-practice-repertoire.pgn");
  await mkdir(ownedRoot, { recursive: true });
  await mkdir(permissionPuzzleRoot, { recursive: true, mode: 0o700 });
  await mkdir(join(permissionEngineRoot, "blocked-child"), { recursive: true, mode: 0o700 });
  await writeFile(join(permissionEngineRoot, "blocked-child/engine"), "not an executable\n");
  await mkdir(downloadDestination, { recursive: true });
  await mkdir(filesWorkspace, { recursive: true });
  await writeFile(join(filesWorkspace, `${filesRowName}.pgn`), filesGamePgn);
  await writeFile(join(filesWorkspace, `${openingRowName}.pgn`), openingPgn);
  await writeFile(join(filesWorkspace, `${conversionSeedName}.pgn`), conversionSeedPgn);
  const cancellationSource = join(filesWorkspace, `${conversionSourceName}.pgn`);
  await writeFile(cancellationSource, "");
  // Stream about 128 MiB of valid PGN so native progress can deliver a real running cancellation.
  // Deterministic transaction-boundary races belong to the portable Rust tests.
  const cancellationChunk = conversionSeedPgn
    .replace("1. d4", `{${"x".repeat(4096)}}\n1. d4`)
    .repeat(1024);
  for (let chunk = 0; chunk < 32; chunk++) await appendFile(cancellationSource, cancellationChunk);
  console.log(
    `  .. conversion disposable inputs: ${cancellationSource}, ${join(filesWorkspace, `${conversionSeedName}.pgn`)}`,
  );
  console.log(
    `  .. game-opening disposable PGN input: ${join(filesWorkspace, `${openingRowName}.pgn`)}`,
  );
  await writeFile(join(filesWorkspace, `${emptyOpeningRowName}.pgn`), "");
  // Dedicated sidecar-less file: changing its type cannot alter another check's fixture.
  const filesMetadataPgnPath = join(filesWorkspace, `${filesMetadataRowName}.pgn`);
  const filesMetadataInfoPath = join(filesWorkspace, `${filesMetadataRowName}.info`);
  await writeFile(filesMetadataPgnPath, filesGamePgn);
  const nagsGamePath = join(filesWorkspace, `${nagsRowName}.pgn`);
  await writeFile(nagsGamePath, nagsGamePgn);
  const initialLargePracticePgn = practicePgn(initialPracticeTree);
  await writeFile(largePracticePath, initialLargePracticePgn);
  await writeFile(largePracticeMetadataPath, JSON.stringify({ type: "repertoire", tags: [] }));
  await writeFile(
    legacyPracticePath,
    `[Event "legacy practice fixture"]\n[Result "*"]\n\n1. e4 *\n`,
  );
  const seededLargePractice = await seedNativePracticeDeck(
    practiceDirectory,
    largePracticeId,
    practiceGame,
    initialPracticePositions,
    100_001,
  );
  const extendedLargePracticePgn = practicePgn(extendedPracticeTree);
  const rewrittenOnlyMoveSan = extendedPracticePositions
    .slice(initialPracticePositions.length)
    .map(({ answer }) => answer)
    .find(
      (san) => extendedLargePracticePgn.includes(san) && !initialLargePracticePgn.includes(san),
    );
  if (!rewrittenOnlyMoveSan) {
    throw new Error("the rewritten practice PGN has no move absent from its initial PGN");
  }
  const rewrittenOnlyMoveFigurine = rewrittenOnlyMoveSan.replace(
    /^[KQRBN]/,
    (piece) => ({ K: "♔", Q: "♕", R: "♖", B: "♗", N: "♘" })[piece],
  );
  const rewrittenOnlyMoveForms = [...new Set([rewrittenOnlyMoveSan, rewrittenOnlyMoveFigurine])];
  await mkdir(imageDirectory, { recursive: true });
  await writeFile(orphanFile, "do not delete registry fixture bytes");
  const retainedImageBytes = Buffer.from(retainedImageBase64, "base64");
  await writeFile(retainedImage, retainedImageBytes);
  await writeFile(retiredImage, "retired managed image bytes");
  await writeFile(orphanImage, "orphan managed image bytes");
  const registryFile = join(profileDirectory, ".config/com.chessriddle.studio/path-authority.json");
  await mkdir(join(profileDirectory, ".config/com.chessriddle.studio"), { recursive: true });
  await writeFile(
    registryFile,
    JSON.stringify({
      schema_version: 1,
      entries: [
        await pathAuthorityEntry(
          "verify-permission-puzzles",
          "Permission puzzles",
          permissionPuzzleRoot,
          "puzzleRoot",
          ["puzzleRead", "puzzleDelete", "downloadFile"],
          true,
        ),
        await pathAuthorityEntry(
          "verify-permission-engines",
          "Permission engines",
          permissionEngineRoot,
          "engineRoot",
          ["downloadArchive", "engineInstall", "engineExecute", "engineConfigure"],
          true,
        ),
        await pathAuthorityEntry(
          "verify-owned-root",
          "Owned fixture root",
          ownedRoot,
          "databaseRoot",
          ["databaseRead", "databaseMutate", "databaseCreate", "databaseExport", "downloadFile"],
          true,
        ),
        await pathAuthorityEntry(
          "verify-download-destination",
          "Download destination fixture",
          downloadDestination,
          "downloadDestination",
          ["downloadFile"],
          true,
        ),
        await pathAuthorityEntry(
          "verify-unowned-book",
          "Unowned fixture book",
          orphanFile,
          "openingBook",
          ["openingBookRead"],
          false,
        ),
        await pathAuthorityEntry(
          retainedImageId,
          "Retained engine image",
          retainedImage,
          "engineImage",
          ["imageRead"],
          false,
        ),
        await pathAuthorityEntry(
          retiredImageId,
          "Shutdown engine image",
          retiredImage,
          "engineImage",
          ["imageRead"],
          false,
        ),
        await pathAuthorityEntry(
          orphanImageId,
          "Orphan engine image",
          orphanImage,
          "engineImage",
          ["imageRead"],
          false,
        ),
        await pathAuthorityEntry(
          filesWorkspaceId,
          "Files fixture",
          filesWorkspace,
          "pgnWorkspace",
          ["readPgn", "writePgn"],
          true,
        ),
        await pathAuthorityEntry(
          largePracticeId,
          "Large practice fixture",
          largePracticePath,
          "pgnFile",
          ["readPgn", "writePgn"],
          false,
        ),
        await pathAuthorityEntry(
          legacyPracticeId,
          "Legacy practice fixture",
          legacyPracticePath,
          "pgnReadOnlyFile",
          ["readPgn"],
          false,
        ),
      ],
      active_database_root: { id: "verify-owned-root" },
      active_puzzle_root: { id: "verify-permission-puzzles" },
      active_engine_root: { id: "verify-permission-engines" },
      pending_artifacts: [],
      provisional_attachments: [],
      image_cleanup: [],
    }),
  );
  await rm(downloadDestination, { recursive: true, force: true });
  const logFile = join(
    profileDirectory,
    ".local/share/com.chessriddle.studio/logs/chessriddle-studio.log",
  );
  const readLogSinceFirstOpen = await createSinceOpenLogReader(logFile);
  const readLog = () => readLogSinceFirstOpen().catch(() => "");

  const createLogReader = () => createSinceOpenLogReader(logFile);
  const openCurrentAssertionSession = (label) => openAssertionSession({ label, createLogReader });
  let session;
  let readLogSinceOpen;
  ({ session, readLogSinceOpen } = await openCurrentAssertionSession("preserved profile"));
  const readPathRegistry = async () => JSON.parse(await readFile(registryFile, "utf8"));
  const reconciledRegistry = await waitForStartupReconciliation({
    label: "production startup to reconcile the seeded path registry",
    readRegistry: readPathRegistry,
    isReconciled: (registry) =>
      !(
        registry.entries.some(
          ({ id }) => id.id === "verify-unowned-book" || id.id === orphanImageId,
        ) || registry.image_cleanup?.some(({ id }) => id.id === orphanImageId)
      ),
    probeId: "verify-unowned-book",
    orphanImageId,
    session,
    readLogSinceOpen,
  });
  check(
    reconciledRegistry.entries.some(({ id }) => id.id === "verify-owned-root") &&
      !reconciledRegistry.entries.some(({ id }) => id.id === "verify-unowned-book"),
    "production startup reclaims unowned authority and preserves native-owned authority",
  );
  check(
    existsSync(ownedRoot) && existsSync(orphanFile),
    "startup authority reconciliation deletes no user files",
  );
  check(
    reconciledRegistry.entries.some(({ id }) => id.id === retainedImageId) &&
      reconciledRegistry.entries.some(({ id }) => id.id === retiredImageId) &&
      !reconciledRegistry.entries.some(({ id }) => id.id === orphanImageId) &&
      existsSync(retainedImage) &&
      existsSync(retiredImage) &&
      !existsSync(orphanImage),
    "trusted production startup preserves owned images and cleans only the orphan",
  );
  const closeControl = await waitFor("the renderer to mount its window controls", async () =>
    session.execute(closeControlProbe).catch(() => false),
  ).catch((error) => {
    throw new Error(
      "could not find the close control: expected the translated label or the last button " +
        `in the window-controls group (${error.message})`,
    );
  });

  check(
    (await session.execute("return typeof window.__TAURI_INTERNALS__")) === "object",
    "the real Tauri IPC bridge is present (not a test mock)",
  );
  check(
    (await session.execute("return document.title")) === "ChessRiddle Studio",
    "the real renderer exposes the ChessRiddle Studio document title",
  );
  await verifyProgressContract(session);
  await verifyFeedbackScreenshot(session);

  const waitForPracticeOwners = async (label) =>
    waitFor(
      label,
      async () => {
        const registry = await readPathRegistry();
        return registry.entries.some(({ id }) => id.id === largePracticeId) &&
          registry.entries.some(({ id }) => id.id === legacyPracticeId)
          ? registry
          : false;
      },
      { timeoutMs: IPC_PROBE_TIMEOUT_MS },
    );
  const armStartupReconciliationProbe = async () => {
    const registry = await readPathRegistry();
    const probeId = "verify-unowned-book";
    registry.entries = registry.entries.filter(({ id }) => id.id !== probeId);
    registry.entries.push(
      await pathAuthorityEntry(
        probeId,
        "Startup reconciliation probe",
        orphanFile,
        "openingBook",
        ["openingBookRead"],
        false,
      ),
    );
    await writeFile(registryFile, JSON.stringify(registry));
  };
  const waitForCurrentStartupReconciliation = (label) =>
    waitForStartupReconciliation({
      label,
      readRegistry: readPathRegistry,
      isReconciled: (registry) =>
        !registry.entries.some(({ id }) => id.id === "verify-unowned-book"),
      probeId: "verify-unowned-book",
      session,
      readLogSinceOpen,
    });
  const reopenAssertionSession = async (label) => {
    const closed = await closeApplicationThroughTitlebar(session, label);
    if (!closed.gone || closed.survivors.length > 0) {
      throw new Error(`${label} processes survived close: ${closed.survivors.join(", ")}`);
    }
    await session.quit().catch(() => undefined);
    await armStartupReconciliationProbe();
    ({ session, readLogSinceOpen } = await openCurrentAssertionSession(label));
    const reconciledRegistry = await waitForCurrentStartupReconciliation(
      `${label} startup reconciliation to remove the freshly seeded probe`,
    );
    await waitFor(`${label} renderer to expose Tauri`, () =>
      session.execute("return typeof window.__TAURI_INTERNALS__ === 'object'").catch(() => false),
    );
    // The renderer's workspace initialization and practice migration must settle before a step
    // closes or opens tabs; the probe above proves only that native reconciliation ran.
    await waitForPracticeOwners(`${label} startup to retain practice capabilities`);
    return reconciledRegistry;
  };

  const trashWorkspace = { id: { id: filesWorkspaceId }, kind: "fileWorkspace" };
  const trashFolder = join(filesWorkspace, "Trash restart fixture");
  const trashFilename = "restart-trash.pgn";
  const restoredTrashFile = join(trashFolder, trashFilename);
  const rootTrashConflict = join(filesWorkspace, trashFilename);
  const rootTrashConflictBytes = '[Event "Root conflict"]\n\n1. d4 *\n';
  await mkdir(trashFolder);
  await writeFile(restoredTrashFile, filesGamePgn);
  await writeFile(rootTrashConflict, rootTrashConflictBytes);
  const trashBefore = await invokeJsonAndWait(
    session,
    "trash restart fixture listing",
    "__trashRestartBefore",
    `window.__TAURI_INTERNALS__.invoke("list_file_workspace", { workspace: ${JSON.stringify(trashWorkspace)}, ticket: null })`,
  );
  const trashSource = trashBefore.value?.entries
    ?.find((entry) => entry.name === "Trash restart fixture")
    ?.children?.find((entry) => entry.name === "restart-trash");
  if (!trashSource?.handle)
    throw new Error(`trash restart source missing: ${JSON.stringify(trashBefore)}`);
  const trashMoved = await invokeAndWait(
    session,
    "trash restart move",
    "__trashRestartMoved",
    `window.__TAURI_INTERNALS__.invoke("trash_workspace_entry", { workspace: ${JSON.stringify(trashWorkspace)}, entry: ${JSON.stringify(trashSource.handle)} })`,
  );
  if (typeof trashMoved.value !== "string" || !/^[0-9a-f-]{36}$/.test(trashMoved.value))
    throw new Error(`trash restart move failed: ${JSON.stringify(trashMoved)}`);
  check(
    !existsSync(restoredTrashFile),
    "TR0 native trash removes the subfolder source before restart",
  );
  await reopenAssertionSession("workspace-trash-restart");
  const trashAfter = await invokeJsonAndWait(
    session,
    "trash listing after restart",
    "__trashRestartAfter",
    `window.__TAURI_INTERNALS__.invoke("list_workspace_trash", { workspace: ${JSON.stringify(trashWorkspace)}, cursor: null, ticket: null })`,
  );
  check(
    trashAfter.value?.items?.some(
      (entry) =>
        entry.item === trashMoved.value && entry.originalFolder === "Trash restart fixture",
    ),
    "TR1 native trash listing recovers the item and original subfolder after restart",
    JSON.stringify(trashAfter),
  );
  const trashRestored = await invokeAndWait(
    session,
    "trash restore after restart",
    "__trashRestartRestored",
    `window.__TAURI_INTERNALS__.invoke("restore_workspace_trash_item", { workspace: ${JSON.stringify(trashWorkspace)}, item: ${JSON.stringify(trashMoved.value)} })`,
  );
  check(
    !trashRestored.rejected &&
      (await readFile(restoredTrashFile, "utf8").catch(() => null)) === filesGamePgn,
    "TR2 item-id restore after restart returns exact bytes to the original subfolder",
    JSON.stringify(trashRestored),
  );
  check(
    (await readFile(rootTrashConflict, "utf8")) === rootTrashConflictBytes,
    "TR3 subfolder restore preserves the root filename conflict",
  );
  check(
    !existsSync(join(filesWorkspace, ".en-croissant-trash", trashMoved.value)) &&
      !existsSync(join(filesWorkspace, ".en-croissant-trash", `${trashMoved.value}.origin`)),
    "TR4 restore after restart removes its bucket and origin record",
  );
  await rm(trashFolder, { recursive: true });
  await rm(rootTrashConflict);

  const largeDeckSnapshot = await loadPracticeDeckThroughIpc(
    session,
    largePracticeId,
    practiceGame,
    "__verifyAppLargeDeckSnapshot",
  );
  const largePositions = practicePositionsFromSnapshot(largeDeckSnapshot.value?.deck);
  check(
    largeDeckSnapshot.result.rejected === undefined &&
      Array.isArray(largePositions) &&
      largePositions.length === initialPracticePositions.length,
    "the native practice read returns all 12,000 seeded positions",
    largeDeckSnapshot.result.rejected ?? largeDeckSnapshot.error,
  );
  const largeReviewPage = await loadAllPracticeReviews(
    session,
    largePracticeId,
    practiceGame,
    "__verifyAppLargeReviews",
    largeDeckSnapshot.value?.epoch,
  );
  const oldestFirstReviewIds = [...largeReviewPage.ids].reverse();
  check(
    largeReviewPage.complete &&
      oldestFirstReviewIds.length === seededLargePractice.reviewIds.length &&
      oldestFirstReviewIds.every((id, index) => id === seededLargePractice.reviewIds[index]) &&
      largeReviewPage.ids.at(-1) === seededLargePractice.reviewIds[0],
    "native practice review paging returns every seeded entry and reaches the oldest review",
    largeReviewPage.error,
  );

  const migratedDeckSnapshot = await loadPracticeDeckThroughIpc(
    session,
    legacyPracticeId,
    practiceGame,
    "__verifyAppMigratedDeckSnapshot",
  );
  const migratedPositions = practicePositionsFromSnapshot(migratedDeckSnapshot.value?.deck);
  const migratedReviews = await loadAllPracticeReviews(
    session,
    legacyPracticeId,
    practiceGame,
    "__verifyAppMigratedReviews",
    migratedDeckSnapshot.value?.epoch,
  );
  check(
    migratedDeckSnapshot.result.rejected === undefined &&
      migratedDeckSnapshot.value?.deck?.migrated === true &&
      migratedPositions?.length === legacyPracticePositions.length &&
      migratedReviews.complete &&
      migratedReviews.ids.length === legacyPracticeLogs.length,
    "the legacy practice deck is migrated into the native store through real IPC",
    migratedDeckSnapshot.result.rejected ?? migratedDeckSnapshot.error ?? migratedReviews.error,
  );
  const migratedRegistry = await waitForPracticeOwners("migrated practice capabilities");
  check(
    migratedRegistry.entries.some(({ id }) => id.id === legacyPracticeId),
    "migration retains the legacy deck capability in path-authority.json",
  );
  const legacyValueBeforeWriter = await session.execute(
    "return localStorage.getItem(arguments[0])",
    [legacyPracticeKey],
  );
  check(
    legacyValueBeforeWriter === null,
    "successful startup migration retires the legacy practice localStorage key",
  );

  const practiceScreenshot = async (name) => {
    const path = `${screenshotPath}.${name}.png`;
    await writeFile(path, Buffer.from(await session.screenshot(), "base64"));
    console.log(`  .. practice screenshot: ${path}`);
  };
  let ratingIndex = -1;
  let practiceStage = "open the large practice file";
  try {
    await openFilesEntry(session, largePracticeName, PRACTICE_RENDERER_TIMEOUT_MS);
    await selectPracticeTab(session, PRACTICE_RENDERER_TIMEOUT_MS);
    const firstFiftyPracticePositions = initialPracticePositions.slice(0, 50);
    await waitFor(
      "the large practice deck to hydrate before UI writing",
      () =>
        session
          .execute(
            "return document.body.innerText.includes('Start Practice') && !document.body.innerText.includes('Loading')",
          )
          .catch(() => false),
      { timeoutMs: PRACTICE_RENDERER_TIMEOUT_MS },
    );
    if (screenshotPath) await practiceScreenshot("practice-idle");
    const startPracticeButton = await reachableStableCoordinates(
      session,
      "the rendered normal practice button",
      `[...document.querySelectorAll('button')].find((candidate) =>
             candidate.textContent?.includes('Start Practice')
           )`,
      [],
      { timeoutMs: PRACTICE_RENDERER_TIMEOUT_MS },
    );
    if (startPracticeButton.disabled) {
      const state = await session
        .execute("return { path: location.pathname, text: document.body.innerText.slice(0, 2000) }")
        .catch(() => ({ path: "unavailable", text: "unavailable" }));
      throw new Error(`normal practice remains disabled: ${JSON.stringify(state)}`);
    }
    practiceStage = "start practice";
    await clickAt(session, startPracticeButton.x, startPracticeButton.y, "practice-start");
    try {
      await waitFor(
        "the practice panel to enter its first move",
        () =>
          session
            .execute("return document.body.innerText.includes('Make your move')")
            .catch(() => false),
        { timeoutMs: PRACTICE_RENDERER_TIMEOUT_MS },
      );
    } catch (error) {
      const state = await session
        .execute(
          "return { path: location.pathname, text: document.body.innerText.slice(0, 2000), buttons: [...document.querySelectorAll('button')].map((button) => ({ text: button.textContent, disabled: button.disabled })).slice(-8) }",
        )
        .catch(() => ({ path: "unavailable", text: "unavailable", buttons: [] }));
      throw new Error(`${error.message}; practice state: ${JSON.stringify(state)}`);
    }
    if (screenshotPath) await practiceScreenshot("practice-session");
    for (const [index, position] of firstFiftyPracticePositions.entries()) {
      await waitFor(
        `practice card ${index + 1} to finish replay`,
        () =>
          session
            .execute("return document.body.innerText.includes('Make your move')")
            .catch(() => false),
        { timeoutMs: PRACTICE_RENDERER_TIMEOUT_MS },
      );
      ratingIndex = index;
      practiceStage = "rate practice cards";
      const move = position.uci;
      await playPracticeBoardMove(session, move, `practice-rating-${index}`);
      const moveResult = await waitFor(`practice move ${index + 1} to resolve`, () =>
        session
          .execute(
            `const text = document.body.innerText;
           if (text.includes(arguments[0] + " correct")) return "correct";
           if (text.includes("Not this move — try again") || text.includes("on the board, or press Space")) return "incorrect";
           return false;`,
            [index + 1],
          )
          .catch(() => false),
      ).catch(async (error) => {
        const state = await session
          .execute(
            "return { path: location.pathname, text: document.body.innerText.slice(0, 1800), board: (() => { const e = document.querySelector('cg-board'); if (!e) return null; const r = e.getBoundingClientRect(); return { left: r.left, top: r.top, width: r.width, height: r.height }; })() }",
          )
          .catch(() => ({ path: "unavailable", text: "unavailable", board: null }));
        throw new Error(`${error.message}; move ${move}; practice state: ${JSON.stringify(state)}`);
      });
      if (moveResult !== "correct")
        throw new Error(`practice move ${index + 1} was rejected: ${move}`);
    }
  } catch (error) {
    // A WebDriver request aborts when the renderer does not answer within the driver's fetch
    // timeout; wait for it to answer again so the failure carries what the page was doing.
    const recovered = await waitFor(
      "the renderer to answer again after the practice-step failure",
      () => session.execute("return true").catch(() => false),
      { timeoutMs: RENDERER_RECOVERY_TIMEOUT_MS },
    ).catch(() => false);
    const state = recovered
      ? await session
          .execute(
            `return {
               path: location.pathname,
               gates: [...document.querySelectorAll("[data-file-freshness]")].map((gate) =>
                 gate.getAttribute("data-file-freshness"),
               ),
               text: document.body.innerText.slice(0, 1500),
             };`,
          )
          .catch(() => "unavailable")
      : `renderer did not answer within ${RENDERER_RECOVERY_TIMEOUT_MS / 1000} s`;
    throw new Error(
      `${error.message}; stage: ${practiceStage}${ratingIndex >= 0 ? ` (rating ${ratingIndex + 1})` : ""}; renderer state: ${JSON.stringify(state)}`,
    );
  }
  const writerSnapshot = await loadPracticeDeckThroughIpc(
    session,
    largePracticeId,
    practiceGame,
    "__verifyAppWriterSnapshot",
  );
  const writerPositions = practicePositionsFromSnapshot(writerSnapshot.value?.deck);
  const writerReviews = await loadAllPracticeReviews(
    session,
    largePracticeId,
    practiceGame,
    "__verifyAppWriterReviews",
    writerSnapshot.value?.epoch,
  );
  const deckKeysAfterWriter = await session.execute(
    "return Object.keys(localStorage).filter((key) => key.startsWith('deck-')).sort()",
  );
  const legacyValueAfterWriter = await session.execute(
    "return localStorage.getItem(arguments[0])",
    [legacyPracticeKey],
  );
  const seededReviewIds = new Set(seededLargePractice.reviewIds);
  const writerNewReviews = writerReviews.entries.filter(({ id }) => !seededReviewIds.has(id));
  const writerNewRatings = writerNewReviews.map(({ entry }) => {
    try {
      return JSON.parse(entry).rating;
    } catch {
      return undefined;
    }
  });
  check(
    writerReviews.complete &&
      writerReviews.ids.length === seededLargePractice.reviewIds.length + 50,
    "fifty renderer ratings land in the native practice review store",
    writerReviews.error,
  );
  check(
    writerSnapshot.result.rejected === undefined && writerPositions?.length === 12_000,
    "renderer ratings do not alter the large deck's 12,000 native positions",
    writerSnapshot.result.rejected ?? writerSnapshot.error,
  );
  check(
    writerNewRatings.length === 50 && writerNewRatings.every((rating) => rating === 3),
    "the 50 new native reviews record the panel's Good rating",
    `ratings: ${JSON.stringify(writerNewRatings)}`,
  );
  check(
    deckKeysAfterWriter.length === 0 && legacyValueAfterWriter === null,
    "renderer ratings create no legacy keys and do not recreate the retired key",
    deckKeysAfterWriter.join(", "),
  );

  const retentionStartupRegistry = await reopenAssertionSession("legacy-key retirement");
  check(
    (await session.execute("return localStorage.getItem(arguments[0])", [legacyPracticeKey])) ===
      null && retentionStartupRegistry.entries.some(({ id }) => id.id === legacyPracticeId),
    "list_practice_decks retains the migrated capability after legacy-key retirement and fresh startup reconciliation",
  );

  await reopenAssertionSession("large-deck extension");
  await openFilesEntry(session, largePracticeName, PRACTICE_RENDERER_TIMEOUT_MS);
  await selectPracticeTab(session, PRACTICE_RENDERER_TIMEOUT_MS);
  const readOpenPracticeFreshness = () =>
    session
      .execute(
        `// An earlier verify:practice tab survives restarts through workspace restore; pick the active tab.
         const tab = [...document.querySelectorAll('[role="tab"]')].find((candidate) =>
           candidate.getAttribute("aria-selected") === "true" &&
           candidate.textContent?.includes("verify:practice")
         );
         const panelId = tab?.getAttribute("aria-controls");
         const panel = panelId ? document.getElementById(panelId) : null;
         const gate = panel?.querySelector("[data-file-freshness]");
         if (!gate) return false;
         const [state, countText] = (gate.getAttribute("data-file-freshness") || "").split(":");
         const reloadCount = Number(countText);
         return Number.isInteger(reloadCount) ? { state, reloadCount } : false;`,
      )
      .catch(() => false);
  let openFreshnessBeforeWrite;
  try {
    openFreshnessBeforeWrite = await waitFor(
      "the open file-backed tab to verify before the external PGN write",
      async () => {
        const freshness = await readOpenPracticeFreshness();
        return freshness && freshness.state === "verified" ? freshness : false;
      },
      { timeoutMs: PRACTICE_RENDERER_TIMEOUT_MS },
    );
  } catch (error) {
    const state = await session
      .execute(
        `return {
           path: location.pathname,
           tabs: [...document.querySelectorAll('[role="tab"]')].map((tab) => ({
             text: tab.textContent,
             selected: tab.getAttribute("aria-selected"),
             controls: tab.getAttribute("aria-controls"),
           })),
           gates: [...document.querySelectorAll("[data-file-freshness]")].map((gate) =>
             gate.getAttribute("data-file-freshness"),
           ),
           text: document.body.innerText.slice(0, 1200),
         };`,
      )
      .catch(() => "unavailable");
    throw new Error(`${error.message}; renderer state: ${JSON.stringify(state)}`);
  }
  const measurementReady = await session.execute(
    `const baselineReloadCount = arguments[0];
     // An earlier verify:practice tab survives restarts through workspace restore; pick the active tab.
     const tab = [...document.querySelectorAll('[role="tab"]')].find((candidate) =>
       candidate.getAttribute("aria-selected") === "true" &&
       candidate.textContent?.includes("verify:practice")
     );
     const panelId = tab?.getAttribute("aria-controls");
     const panel = panelId ? document.getElementById(panelId) : null;
     const gate = panel?.querySelector("[data-file-freshness]");
     if (!gate) return false;
     const state = {
       startedAt: performance.now(),
       baselineReloadCount,
       armed: true,
       readDurations: [],
       lastReadFinishedAt: null,
       lexAwaitMs: 0,
       appliedAt: null,
       fileId: null,
       terminal: null,
     };
     // The sealed IPC invoke cannot be wrapped, so the platform records this read.
     window.__verifyAppRecordReadGame = (durationMs, fileId) => {
       if (!state.armed || state.terminal) return;
       if (state.fileId == null) state.fileId = fileId ?? null;
       if (fileId !== state.fileId) return;
       state.readDurations.push(durationMs);
       state.lastReadFinishedAt = performance.now();
       state.lexAwaitMs = 0;
       state.appliedAt = null;
     };
     window.__verifyAppRecordLexPgn = (durationMs) => {
       if (!state.armed || state.terminal || state.lastReadFinishedAt == null) return;
       state.lexAwaitMs += durationMs;
     };
     window.__verifyAppRecordTreeApplied = () => {
       if (!state.armed || state.terminal) return;
       state.appliedAt = performance.now();
     };
     const observeFreshness = () => {
       const [freshnessState, countText] = (gate.getAttribute("data-file-freshness") || "").split(":");
       const reloadCount = Number(countText);
       if (
         !state.terminal &&
         (freshnessState === "conflict" ||
           freshnessState === "unavailable" ||
           (freshnessState === "verified" && reloadCount > baselineReloadCount))
       ) {
         state.terminal = {
           state: freshnessState,
           reloadCount,
           observedAt: performance.now(),
           readFinishedAt: state.lastReadFinishedAt,
           lexAwaitMs: state.lexAwaitMs,
           appliedAt: state.appliedAt,
         };
       }
     };
     state.observer = new MutationObserver(observeFreshness);
     state.observer.observe(gate, { attributes: true, attributeFilter: ["data-file-freshness"] });
     window.__verifyAppFileFreshnessMeasurement = state;
     return { startedAt: state.startedAt };`,
    [openFreshnessBeforeWrite.reloadCount],
  );
  if (!measurementReady) throw new Error("could not arm the open tab freshness measurement");
  const inodeBeforeRewrite = (await stat(largePracticePath)).ino;
  const writeStartedAt = performance.now();
  await writeFile(largePracticePath, extendedLargePracticePgn);
  const rewriteDurationMs = performance.now() - writeStartedAt;
  const inodeAfterRewrite = (await stat(largePracticePath)).ino;
  check(
    inodeAfterRewrite === inodeBeforeRewrite,
    "the stale-file scenario rewrites the PGN in place",
    `inode changed from ${inodeBeforeRewrite} to ${inodeAfterRewrite}`,
  );
  const freshnessTransition = await waitFor(
    "the open tab to reload the external PGN or show its conflict panel",
    () =>
      session
        .execute("return window.__verifyAppFileFreshnessMeasurement?.terminal || false")
        .catch(() => false),
    { timeoutMs: 10_000, everyMs: 50 },
  );
  const freshnessMeasurement = await session.execute(
    `const measurement = window.__verifyAppFileFreshnessMeasurement;
     return {
       readTimeMs: measurement.readDurations.at(-1) ?? null,
       state: measurement.terminal?.state ?? null,
       reloadCount: measurement.terminal?.reloadCount ?? null,
       observedAt: measurement.terminal?.observedAt ?? null,
       readFinishedAt: measurement.terminal?.readFinishedAt ?? null,
       lexAwaitMs: measurement.terminal?.lexAwaitMs ?? null,
       appliedAt: measurement.terminal?.appliedAt ?? null,
     };`,
  );
  await session.execute(
    "const measurement = window.__verifyAppFileFreshnessMeasurement; measurement.armed = false; measurement.observer?.disconnect(); delete window.__verifyAppRecordReadGame; delete window.__verifyAppRecordLexPgn; delete window.__verifyAppRecordTreeApplied; measurement.observer = null; return true;",
  );
  const freshnessElapsedMs =
    freshnessMeasurement.observedAt - measurementReady.startedAt - rewriteDurationMs;
  const measuredReadTimeMs = freshnessMeasurement.readTimeMs;
  const freshnessTiming = fileFreshnessTiming(
    freshnessMeasurement,
    FILE_FRESHNESS_POLL_INTERVAL_MS,
  );
  const {
    applicationMs,
    observationGapMs,
    mainThreadMs,
    deadlineMs: freshnessDeadlineMs,
  } = freshnessTiming;
  const formatDuration = (value) => (Number.isFinite(value) ? value.toFixed(1) : "unmeasured");
  const openTabReloaded =
    freshnessTransition.state === "conflict" ||
    (freshnessTransition.state === "verified" &&
      freshnessTransition.reloadCount > openFreshnessBeforeWrite.reloadCount);
  check(
    openTabReloaded,
    "the open file-backed tab reloads or withholds the changed PGN",
    `freshness state: ${freshnessTransition.state}`,
  );
  check(
    Number.isFinite(measuredReadTimeMs) && measuredReadTimeMs >= 0,
    "the file freshness transition includes a measured native read_game call",
    `read_game duration: ${measuredReadTimeMs}`,
  );
  check(
    fileFreshnessMainThreadWithinBudget(freshnessTiming, FILE_FRESHNESS_APPLY_BUDGET_MS),
    `the freshness main-thread publication takes at most ${FILE_FRESHNESS_APPLY_BUDGET_MS} ms excluding lex await`,
    `mainThreadMs: ${formatDuration(mainThreadMs)} ms; ` +
      `readGame: ${formatDuration(measuredReadTimeMs)} ms; lexAwaitMs: ${formatDuration(freshnessMeasurement.lexAwaitMs)} ms`,
  );
  console.log(
    `  info  open file freshness: ${freshnessElapsedMs.toFixed(1)} ms after rewrite ` +
      `(limit ${FILE_FRESHNESS_POLL_INTERVAL_MS} ms + readGame ${formatDuration(measuredReadTimeMs)} ms + ` +
      `lexAwaitMs ${formatDuration(freshnessMeasurement.lexAwaitMs)} ms + mainThreadMs ${formatDuration(mainThreadMs)} ms; ` +
      `applicationMs ${formatDuration(applicationMs)} ms; observationGapMs ${formatDuration(observationGapMs)} ms; ${freshnessTransition.state})`,
  );
  check(
    Number.isFinite(freshnessElapsedMs) && freshnessElapsedMs <= freshnessDeadlineMs,
    "the open file-backed tab refreshes within one poll interval plus measured read, lex await and main-thread time",
    `${freshnessElapsedMs.toFixed(1)} ms > ${Number.isFinite(freshnessDeadlineMs) ? `${freshnessDeadlineMs.toFixed(1)} ms` : "unmeasured deadline"}`,
  );
  if (freshnessTransition.state === "conflict") {
    const reloadButton = await waitFor("the open file freshness conflict panel reload button", () =>
      session
        .execute(
          `const button = [...document.querySelectorAll("button")].find((candidate) =>
               candidate.textContent?.trim() === "Reload from disk"
             );
             if (!button) return false;
             const box = button.getBoundingClientRect();
             return { x: Math.round(box.left + box.width / 2), y: Math.round(box.top + box.height / 2) };`,
        )
        .catch(() => false),
    );
    await clickAt(session, reloadButton.x, reloadButton.y, "reload-open-file-tab");
    let reloadWaitError;
    await waitFor(
      "the open file-backed tab to verify after Reload from disk",
      async () => {
        const freshness = await readOpenPracticeFreshness();
        return freshness &&
          freshness.state === "verified" &&
          freshness.reloadCount > freshnessTransition.reloadCount
          ? freshness
          : false;
      },
      { timeoutMs: PRACTICE_RENDERER_TIMEOUT_MS },
    ).catch((error) => {
      reloadWaitError = error.message;
    });
    const reloadedFreshness = await readOpenPracticeFreshness();
    const rewrittenOnlyMoveVisible = await session
      .execute(
        `const pageText = document.body.innerText.replace(/\\s+/g, "");
         return arguments[0].some((move) => pageText.includes(move));`,
        [rewrittenOnlyMoveForms],
      )
      .catch(() => false);
    const reloadCheckPassed =
      reloadedFreshness?.state === "verified" &&
      reloadedFreshness.reloadCount > freshnessTransition.reloadCount &&
      rewrittenOnlyMoveVisible;
    check(
      reloadCheckPassed,
      "Reload from disk verifies the tab and shows a move unique to the rewritten PGN",
      `wait: ${reloadWaitError ?? "verified"}; freshness: ${reloadedFreshness?.state ?? "unavailable"}:${reloadedFreshness?.reloadCount ?? "unavailable"} (expected count > ${freshnessTransition.reloadCount}); ${rewrittenOnlyMoveSan}/${rewrittenOnlyMoveFigurine} visible: ${rewrittenOnlyMoveVisible}`,
    );
  }
  let syncWaitError;
  try {
    await waitFor(
      "the real sync path to add 500 large-deck positions",
      async () => {
        const loaded = await loadPracticeDeckThroughIpc(
          session,
          largePracticeId,
          practiceGame,
          "__verifyAppExtendedDeckSnapshot",
        );
        return practicePositionsFromSnapshot(loaded.value?.deck)?.length === 12_500;
      },
      { timeoutMs: PRACTICE_RENDERER_TIMEOUT_MS },
    );
  } catch (error) {
    const state = await session
      .execute(
        "return { path: location.pathname, text: document.body.innerText.slice(0, 2200), sync: [...document.querySelectorAll('[title]')].map((element) => ({ title: element.getAttribute('title'), text: element.textContent })).filter(({ title }) => title?.toLowerCase().includes('sync')) }",
      )
      .catch(() => ({ path: "unavailable", text: "unavailable", sync: [] }));
    syncWaitError = `${error.message}; extended sync state: ${JSON.stringify(state)}`;
  }
  const extendedSnapshot = await loadPracticeDeckThroughIpc(
    session,
    largePracticeId,
    practiceGame,
    "__verifyAppExtendedDeckSnapshotFinal",
  );
  const extendedPositions = practicePositionsFromSnapshot(extendedSnapshot.value?.deck);
  check(
    syncWaitError === undefined &&
      extendedSnapshot.result.rejected === undefined &&
      practiceCardsMatch(extendedPositions, extendedPracticePositions),
    "the real sync path stores 500 further repertoire positions",
    syncWaitError ?? extendedSnapshot.result.rejected ?? extendedSnapshot.error,
  );

  await reopenAssertionSession("final practice retention");
  const finalLargeSnapshot = await loadPracticeDeckThroughIpc(
    session,
    largePracticeId,
    practiceGame,
    "__verifyAppFinalLargeSnapshot",
  );
  const finalLegacySnapshot = await loadPracticeDeckThroughIpc(
    session,
    legacyPracticeId,
    practiceGame,
    "__verifyAppFinalLegacySnapshot",
  );
  const finalLargeReviews = await loadAllPracticeReviews(
    session,
    largePracticeId,
    practiceGame,
    "__verifyAppFinalLargeReviews",
    finalLargeSnapshot.value?.epoch,
  );
  const finalLegacyReviews = await loadAllPracticeReviews(
    session,
    legacyPracticeId,
    practiceGame,
    "__verifyAppFinalLegacyReviews",
    finalLegacySnapshot.value?.epoch,
  );
  const finalInventory = await invokeJsonAndWait(
    session,
    "list_practice_decks final inventory to settle",
    "__verifyAppFinalPracticeInventory",
    `window.__TAURI_INTERNALS__.invoke("list_practice_decks")`,
  );
  const finalLargePositions = practicePositionsFromSnapshot(finalLargeSnapshot.value?.deck);
  const finalLegacyPositionCount = practicePositionsFromSnapshot(
    finalLegacySnapshot.value?.deck,
  )?.length;
  check(
    practiceCardsMatch(finalLargePositions, extendedPracticePositions) &&
      finalLargeReviews.ids.length === seededLargePractice.reviewIds.length + 50 &&
      finalLargeReviews.complete &&
      finalLegacyPositionCount === legacyPracticePositions.length &&
      finalLegacyReviews.complete &&
      finalLegacyReviews.ids.length === legacyPracticeLogs.length,
    "final restart preserves exact native position and review counts for both decks",
    finalLargeSnapshot.result.rejected ?? finalLegacySnapshot.result.rejected,
  );
  check(
    finalInventory.value?.anomalies?.length === 0 &&
      finalInventory.value?.decks?.length === 2 &&
      finalInventory.value.decks.some(
        ({ fileId, game }) => fileId === largePracticeId && game === practiceGame,
      ) &&
      finalInventory.value.decks.some(
        ({ fileId, game }) => fileId === legacyPracticeId && game === practiceGame,
      ),
    "final practice inventory contains no additional native deck",
    finalInventory.result.rejected ?? finalInventory.error,
  );
  check(
    finalLegacyPositionCount === legacyPracticePositions.length &&
      finalLegacyReviews.ids.length === legacyPracticeLogs.length,
    "final migrated-deck counts still equal the legacy value's counts",
  );

  const persistedDownloadDestination = await session.execute(`
    const serialized = localStorage.getItem("download-destination-capability");
    return serialized === null ? null : JSON.parse(serialized);
  `);
  const knownDownloadDestinationResult = await invokeAndWait(
    session,
    "download_destination_is_known for the persisted destination to settle",
    "__verifyAppKnownDownloadDestination",
    `window.__TAURI_INTERNALS__.invoke("download_destination_is_known", {
      destination: ${JSON.stringify(persistedDownloadDestination)},
    })`,
  );
  check(
    knownDownloadDestinationResult.value === "true",
    "real IPC preserves the persisted offline download destination",
    knownDownloadDestinationResult.rejected ??
      knownDownloadDestinationResult.error ??
      knownDownloadDestinationResult.value,
  );

  const freshDownloadDestination = { id: randomUUID() };
  const freshDownloadDestinationResult = await invokeAndWait(
    session,
    "download_destination_is_known for a fresh destination to settle",
    "__verifyAppFreshDownloadDestination",
    `window.__TAURI_INTERNALS__.invoke("download_destination_is_known", {
      destination: ${JSON.stringify(freshDownloadDestination)},
    })`,
  );
  check(
    freshDownloadDestinationResult.value === "false",
    "real IPC rejects a fresh download destination id",
    freshDownloadDestinationResult.rejected ??
      freshDownloadDestinationResult.error ??
      freshDownloadDestinationResult.value,
  );

  const databaseRootDestination = { id: "verify-owned-root" };
  const databaseRootDestinationResult = await invokeAndWait(
    session,
    "download_destination_is_known for the database root to settle",
    "__verifyAppDatabaseRootDestination",
    `window.__TAURI_INTERNALS__.invoke("download_destination_is_known", {
      destination: ${JSON.stringify(databaseRootDestination)},
    })`,
  );
  check(
    databaseRootDestinationResult.value === "false",
    "real IPC rejects a database-root id",
    databaseRootDestinationResult.rejected ??
      databaseRootDestinationResult.error ??
      databaseRootDestinationResult.value,
  );

  const retainedEnginePortrait = await waitFor(
    "the retained engine portrait to render and decode",
    async () => {
      await goToEngines(session).catch(() => false);
      return session
        .execute(
          `const image = document.querySelector('img[alt="Fixture retained"]');
         if (!image || image.naturalWidth <= 0) return false;
         return { src: image.getAttribute("src"), naturalWidth: image.naturalWidth };`,
        )
        .catch(() => false);
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  ).catch((error) => ({ error: error.message }));
  check(
    !retainedEnginePortrait.error,
    "the retained engine LocalImage rendered on the Engines page",
    retainedEnginePortrait.error,
  );
  check(
    typeof retainedEnginePortrait.src === "string" &&
      retainedEnginePortrait.src.startsWith("data:image/png;base64,"),
    "the retained engine LocalImage uses an image/png data URL",
    retainedEnginePortrait.error ?? retainedEnginePortrait.src,
  );
  check(
    retainedEnginePortrait.naturalWidth > 0,
    "the retained engine LocalImage data URL decodes in WebKitGTK",
    retainedEnginePortrait.error ?? String(retainedEnginePortrait.naturalWidth),
  );

  // Exercise the actual inline editor through WebDriver with real native attachment IPC.
  // Only this disposable profile's engines-key renderer storage is refused in the second case.
  await session.execute(`
    const card = [...document.querySelectorAll('button[aria-pressed]')]
      .find(node => node.innerText.includes('Fixture retained'));
    if (!card) throw new Error('engine publication fixture card missing');
    card.click();
    return true;
  `);
  const nameInputId = await waitFor(
    "the real engine Name editor",
    () =>
      session.execute(`
      const label = [...document.querySelectorAll('label')].find(node => node.textContent === 'Name');
      const input = label && document.getElementById(label.htmlFor);
      return input && input.id;
    `),
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );
  const nameElement = await session.call("POST", "/element", {
    using: "css selector",
    value: `#${nameInputId}`,
  });
  const nameElementId = encodeURIComponent(nameElement["element-6066-11e4-a52e-4f735466cecf"]);
  async function editEngineName(value) {
    await session.call("POST", `/element/${nameElementId}/clear`, {});
    await session.call("POST", `/element/${nameElementId}/value`, { text: value });
  }
  async function enginePublicationSnapshot() {
    return session.execute(
      `
      const card = document.querySelector('button[aria-pressed="true"]');
      return {
        card: card?.querySelector('p')?.firstChild?.textContent.trim(),
        input: document.getElementById(arguments[0])?.value,
        raw: localStorage.getItem('engines'),
        error: document.body.innerText.includes('The engine list could not be saved.'),
        refusals: window.__verifyEngineStorageRefusals || 0,
      };
    `,
      [nameInputId],
    );
  }
  const publicationStoredName = (snapshot) => {
    const records =
      snapshot.raw && decodeEngineOwnerValue(deserializeStorageValue(snapshot.raw))?.value;
    return Array.isArray(records)
      ? records.find((record) => record.id === "retained")?.name
      : undefined;
  };
  const savedEngineName = "Fixture saved publication";
  await editEngineName(savedEngineName);
  const savedPublication = await waitFor(
    "the successful real engine editor write to settle",
    async () => {
      const snapshot = await enginePublicationSnapshot();
      return (
        publicationStoredName(snapshot) === savedEngineName &&
        snapshot.input === savedEngineName &&
        snapshot.card === savedEngineName &&
        snapshot
      );
    },
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  ).catch(async () => enginePublicationSnapshot());
  check(
    savedPublication.card === savedEngineName,
    "EP1-card successful Name edit publishes the saved engine card",
    JSON.stringify(savedPublication),
  );
  check(
    publicationStoredName(savedPublication) === savedEngineName,
    "EP1-storage successful Name edit persists the decoded engine name",
    JSON.stringify(savedPublication),
  );

  await session.execute(`
    const original = Storage.prototype.setItem;
    window.__verifyEngineStorageRefusals = 0;
    window.__verifyRestoreEngineStorage = () => { Storage.prototype.setItem = original; };
    Storage.prototype.setItem = function(key, value) {
      if (this === localStorage && key === 'engines') {
        window.__verifyEngineStorageRefusals++;
        throw new DOMException('Disposable engine publication refusal', 'QuotaExceededError');
      }
      return original.call(this, key, value);
    };
    return true;
  `);
  try {
    await editEngineName("Fixture refused publication");
    const refusedPublication = await waitFor(
      "the refused real engine Name draft to settle after its reported save failure",
      async () => {
        const snapshot = await enginePublicationSnapshot();
        return (
          snapshot.refusals > 0 && snapshot.error && snapshot.input === savedEngineName && snapshot
        );
      },
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    ).catch(async () => enginePublicationSnapshot());
    check(
      refusedPublication.refusals > 0 && refusedPublication.error,
      "EP2-error refused engines storage write reports the save error",
      JSON.stringify(refusedPublication),
    );
    check(
      refusedPublication.card === savedEngineName,
      "EP2-card refused Name edit retains the saved engine card",
      JSON.stringify(refusedPublication),
    );
    check(
      refusedPublication.input === savedEngineName,
      "EP2-input refused Name draft settles to the saved name",
      JSON.stringify(refusedPublication),
    );
    check(
      publicationStoredName(refusedPublication) === savedEngineName,
      "EP2-storage refused Name edit retains the decoded saved engine name",
      JSON.stringify(refusedPublication),
    );
  } finally {
    await session.execute(
      "window.__verifyRestoreEngineStorage(); delete window.__verifyRestoreEngineStorage; return true;",
    );
  }

  const blobCspResult = await invokeAndWait(
    session,
    "the detached blob image CSP violation to settle",
    "__verifyAppBlobImageCsp",
    `(() => {
      const bytes = new Uint8Array(${JSON.stringify([...retainedImageBytes])});
      const objectUrl = URL.createObjectURL(new Blob([bytes], { type: "image/png" }));
      return new Promise((resolve) => {
        let settled = false;
        let timeoutId;
        const image = document.createElement("img");
        const listener = (event) => {
          if (
            typeof event.violatedDirective !== "string" ||
            !event.violatedDirective.startsWith("img-src") ||
            event.blockedURI !== "blob"
          ) {
            return;
          }
          finish(
            JSON.stringify({
              violatedDirective: event.violatedDirective,
              blockedURI: event.blockedURI,
            }),
          );
        };
        const cleanup = () => {
          if (timeoutId !== undefined) clearTimeout(timeoutId);
          URL.revokeObjectURL(objectUrl);
          document.removeEventListener("securitypolicyviolation", listener);
        };
        const finish = (value) => {
          if (settled) return;
          settled = true;
          cleanup();
          resolve(value);
        };
        try {
          document.addEventListener("securitypolicyviolation", listener);
          timeoutId = setTimeout(
            () => finish(JSON.stringify({ timeout: true })),
            ${CSP_PROBE_TIMEOUT_MS},
          );
          image.src = objectUrl;
        } catch (error) {
          finish(JSON.stringify({ error: String(error) }));
        }
      });
    })()`,
  );
  let blobCspEvent;
  try {
    blobCspEvent = JSON.parse(blobCspResult.value ?? "null");
  } catch {
    blobCspEvent = undefined;
  }
  check(
    typeof blobCspResult.rejected === "undefined" &&
      typeof blobCspEvent?.violatedDirective === "string" &&
      blobCspEvent.violatedDirective.startsWith("img-src") &&
      blobCspEvent.blockedURI === "blob",
    "the production CSP rejects a detached blob image URL with an img-src violation",
    blobCspResult.rejected ?? blobCspResult.error ?? blobCspResult.value,
  );

  const resolveDirectoryResult = await invokeAndWait(
    session,
    "the core:path resolve-directory refusal",
    "__verifyAppResolveDirectory",
    `window.__TAURI_INTERNALS__.invoke("plugin:path|resolve_directory", {
      directory: ${BASE_DIRECTORY_APP_DATA},
      path: "x",
    })`,
    "resolved",
  );
  check(
    typeof resolveDirectoryResult.rejected === "string" &&
      /not allowed/i.test(resolveDirectoryResult.rejected),
    "the renderer cannot resolve a base directory (core:path grants are gone)",
    resolveDirectoryResult.resolved ?? resolveDirectoryResult.error,
  );

  // A bundled release must publish a live, non-zero sound-server port. `invokeAndWait` stores
  // success as a string under the success key and failure as `rejected`; a missing command, a
  // failed invoke and port 0 therefore all fail this check.
  const soundPortResult = await invokeAndWait(
    session,
    "get_sound_server_port to settle",
    "__verifyAppSoundPort",
    `window.__TAURI_INTERNALS__.invoke("get_sound_server_port")`,
    "port",
  );
  const soundServerPort = Number(soundPortResult.port);
  check(
    typeof soundPortResult.rejected === "undefined" && Number(soundPortResult.port) > 0,
    "the renderer reaches a live loopback sound-server port",
    soundPortResult.rejected ?? soundPortResult.error ?? soundPortResult.port,
  );

  // Node side, not `session.execute`: in-page `fetch` is connect-src, which does not list
  // 127.0.0.1, and the handler sends no CORS headers. Only media-src allows loopback, so this
  // proves the axum server serves the bundled file; the webview plays it through <audio>.
  try {
    const response = await fetch(`http://127.0.0.1:${soundServerPort}/standard/Move.mp3`);
    const body = Buffer.from(await response.arrayBuffer());
    check(
      response.status === 200 && body.length > 0,
      "the loopback sound server serves the bundled standard move sound",
      `status ${response.status}, ${body.length} bytes`,
    );
  } catch (error) {
    check(false, "the loopback sound server serves the bundled standard move sound", error.message);
  }

  const prepareRetireImageResult = await invokeAndWait(
    session,
    "engine attachment prepare to settle",
    "__verifyAppPrepareRetireImage",
    `window.__TAURI_INTERNALS__.invoke("reconcile_engine_attachments", {
      action: {
        action: "prepare",
        retained_ids: [{ id: ${JSON.stringify(retainedImageId)} }],
      },
    })`,
  );
  check(
    prepareRetireImageResult.value === "null",
    "real attachment IPC prepares the exact next durable owner set",
    prepareRetireImageResult.rejected ?? prepareRetireImageResult.error,
  );
  await session.execute(`localStorage.setItem("engines", arguments[0]); return true`, [
    serializeStorageValue([
      { ...ownerEngine("retained", retainedImageId), legacyAssessment: null },
    ]),
  ]);
  const retireImageResult = await invokeAndWait(
    session,
    "engine attachment reconciliation to settle",
    "__verifyAppRetireImage",
    `window.__TAURI_INTERNALS__.invoke("reconcile_engine_attachments", {
      action: {
        action: "reconcile",
        retained_ids: [{ id: ${JSON.stringify(retainedImageId)} }],
        abandoned_ids: [{ id: ${JSON.stringify(retiredImageId)} }],
        startup: false,
      },
    })`,
  );
  check(
    retireImageResult.value === "null",
    "real attachment IPC retires the selected managed image",
    retireImageResult.rejected ?? retireImageResult.error,
  );
  const registryWithCleanup = await waitFor("the managed-image cleanup intent", async () => {
    const registry = await readPathRegistry();
    return registry.image_cleanup?.some(({ id }) => id.id === retiredImageId) ? registry : false;
  });
  check(
    existsSync(retiredImage) &&
      existsSync(retainedImage) &&
      !registryWithCleanup.entries.some(({ id }) => id.id === retiredImageId),
    "retirement preserves image bytes for the live session and records cleanup intent",
  );

  check(
    closeControl === "label" || closeControl === "fallback",
    "the navigation row rendered its window controls",
    closeControl === "fallback"
      ? "the translated close label was absent; the last button in the window-controls group will be used"
      : undefined,
  );

  const preparedRead = await invokeAndWait(
    session,
    "native read reservation to settle",
    "__verifyAppPreparedRead",
    `window.__TAURI_INTERNALS__.invoke("prepare_native_read", {})`,
  );
  check(
    typeof preparedRead.value === "string",
    "the native backend mints an opaque read reservation",
    preparedRead.rejected ?? preparedRead.error,
  );
  const preparedTicket = preparedRead.value;
  const cancelRead = await invokeAndWait(
    session,
    "native read cancellation to settle",
    "__verifyAppCancelledRead",
    `window.__TAURI_INTERNALS__.invoke("cancel_native_read", { ticket: ${JSON.stringify(preparedTicket)} })`,
  );
  check(cancelRead.value === "null", "the native backend acknowledges reservation cancellation");
  const refusedStart = await invokeAndWait(
    session,
    "cancelled native read start to settle",
    "__verifyAppRefusedRead",
    `window.__TAURI_INTERNALS__.invoke("lex_pgn", { pgn: "1. e4 *", ticket: ${JSON.stringify(preparedTicket)} })`,
  );
  check(
    typeof refusedStart.rejected === "string" &&
      /native read reservation is unknown or expired/.test(refusedStart.rejected),
    "a cancelled reservation cannot be claimed by a later native read",
    refusedStart.value ?? refusedStart.error,
  );

  // Files double-click. Runs before the retained reservation is minted, so opening the file cannot
  // add a reservation to the destroyed-window log line checked below. Navigation stays in-app:
  // a URL load would replace the main webview document that line is about. Nothing after this
  // depends on the route the double-click leaves behind.
  await verifyWorkspaceDeletionOutcome(session, filesWorkspace);
  await verifyLosslessFileGameSave(session, filesWorkspace);
  const filesRowCheck = "the seeded workspace file row renders on the Files page";
  const filesRouteCheck = "a real double-click on the unselected Files row navigates to /";
  const filesNotationCheck = "a real double-click on the unselected Files row shows its game";
  const filesRow = await filesRowCoordinates(session, filesRowName).then(
    (coordinates) => ({ coordinates }),
    (error) => ({ error: error.message }),
  );
  check(!filesRow.error, filesRowCheck, filesRow.error);
  if (filesRow.error) {
    check(false, filesRouteCheck, "not attempted: the Files row never rendered");
    check(false, filesNotationCheck, "not attempted: the Files row never rendered");
  } else {
    const gesture = await doubleClickAt(
      session,
      filesRow.coordinates.x,
      filesRow.coordinates.y,
    ).then(
      () => null,
      (error) => `the pointer double-click gesture was rejected: ${error.message}`,
    );
    const route = gesture
      ? { error: gesture }
      : await waitFor(
          "the double-click to navigate to /",
          () => session.execute("return location.pathname === '/'").catch(() => false),
          { timeoutMs: FILES_PROBE_TIMEOUT_MS },
        ).catch(async (error) => ({
          error: `${error.message}; path is ${await session
            .execute("return location.pathname")
            .catch(() => "unknown")}`,
        }));
    check(route === true, filesRouteCheck, route.error);
    const notation = gesture
      ? { error: "not attempted: the gesture was rejected" }
      : await waitFor(
          "the opened game's notation",
          () =>
            session
              .execute(
                "return document.body.innerText.replace(/\\s+/g, '').includes(arguments[0])",
                [filesGameNotation],
              )
              .catch(() => false),
          { timeoutMs: FILES_PROBE_TIMEOUT_MS },
        ).catch((error) => ({ error: `${error.message}; expected ${filesGameNotation}` }));
    check(notation === true, filesNotationCheck, notation.error);
  }

  await verifyGameOpening(session, ownedRoot, filesWorkspace);
  await verifyNewGameToDatabase(session);
  await verifyDatabaseOrientation(session);
  await verifyPlayerOverview(session);
  await verifyLinkedCollections(session, filesWorkspace, profileDirectory);
  await verifyConversionCancellation(session, ownedRoot);

  // Lossless NAGs: setup failures are carried to every dependent assertion.
  const nagSetup = async (step, prerequisite, action) => {
    if (prerequisite.error) return prerequisite;
    try {
      const value = await action();
      if (!value) throw new Error("the setup returned no result");
      return { value };
    } catch (error) {
      return { error: `not attempted: ${step}: ${error.message}` };
    }
  };
  const nagAssertion = async (description, prerequisite, action) => {
    if (prerequisite.error) {
      check(false, description, prerequisite.error);
      return prerequisite;
    }
    try {
      const value = await action();
      check(true, description);
      return { value };
    } catch (error) {
      check(false, description, error.message);
      return { error: `not attempted: ${description}: ${error.message}` };
    }
  };
  const nagRow = await nagSetup("NAG Files row lookup", {}, () =>
    filesRowCoordinates(session, nagsRowName),
  );
  const nagOpened = await nagSetup("NAG game double-click open", nagRow, async () => {
    await doubleClickAt(session, nagRow.value.x, nagRow.value.y);
    return waitFor(
      "the NAG game's notation",
      () =>
        session.execute(`
      return location.pathname === '/' && [...document.querySelectorAll('button[class*="cell"]')]
        .some((button) => /^(?:Nc3|♘c3)$/.test(button.textContent.trim()));
    `),
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
  });
  const navigateNagMove = async (move) => {
    const coordinates = await session.execute(
      `
      const button = [...document.querySelectorAll('button[class*="cell"]')].find((button) =>
        button.textContent.trim().replace('♘', 'N').replace(/[!?□=⩲]+$/, '') === arguments[0]);
      if (!button) return false;
      const box = button.getBoundingClientRect();
      return { x: Math.round(box.left + box.width / 2), y: Math.round(box.top + box.height / 2) };
    `,
      [move],
    );
    if (!coordinates) throw new Error(`the ${move} notation control was not rendered`);
    await clickAt(session, coordinates.x, coordinates.y);
    return waitFor(
      `the selected ${move} notation control`,
      () =>
        session.execute(
          `
      return [...document.querySelectorAll('button[class*="cell"]')].some((button) =>
        button.textContent.trim().replace('♘', 'N').replace(/[!?□=⩲]+$/, '') === arguments[0] &&
        button.getAttribute('aria-current') === 'true');
    `,
          [move],
        ),
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
  };
  const hintProbe = () =>
    session.execute(`
    const board = document.querySelector('[role="grid"]');
    // The hint overlays BoardFrame inside the common board surface.
    const wrapper = board?.closest('[data-board-surface]');
    const hint = wrapper?.querySelector('[data-board-annotation-hint]');
    const svg = hint?.querySelector(':scope > svg');
    if (!hint) return { rendered: false, title: null, path: false, width: 0, height: 0, ancestors: [], visible: false };
    const box = hint.getBoundingClientRect();
    const ancestors = [];
    let reachedBoardWrapper = false;
    let element = hint;
    while (element) {
      const style = getComputedStyle(element);
      ancestors.push({ element: element.tagName, className: element.getAttribute("class"), display: style.display, visibility: style.visibility, opacity: style.opacity });
      if (element === wrapper) reachedBoardWrapper = true;
      element = element.parentElement;
    }
    return {
      rendered: true, title: svg?.querySelector('title')?.textContent ?? null,
      path: Boolean(svg?.querySelector('g path')),
      width: box.width, height: box.height, ancestors,
      visible: reachedBoardWrapper && box.width > 0 && box.height > 0 && ancestors.every((style) =>
        style.display !== 'none' && style.visibility !== 'hidden' && style.visibility !== 'collapse' &&
        Number(style.opacity) > 0),
    };
  `);
  const assertNagHint = async (predicate) => {
    const hint = await hintProbe();
    if (!predicate(hint)) throw new Error(`observed board hint: ${JSON.stringify(hint)}`);
    return hint;
  };
  const nagE4 = await nagSetup("navigation to 1.e4", nagOpened, () => navigateNagMove("e4"));
  await nagAssertion("the $8 board hint is rendered with a glyph path", nagE4, () =>
    assertNagHint((hint) => hint.rendered && hint.path),
  );
  await nagAssertion("the $8 board hint SVG title is □", nagE4, () =>
    assertNagHint((hint) => hint.title === "□"),
  );
  await nagAssertion(
    "the $8 board hint has a visible box and positive opacity through its board ancestors",
    nagE4,
    () => assertNagHint((hint) => hint.visible),
  );
  if (screenshotPath && !nagE4.error) {
    await writeFile(screenshotPath, Buffer.from(await session.screenshot(), "base64"));
    console.log(`  ..  NAG game at 1.e4 screenshot written to ${screenshotPath}`);
  }
  const nagD5 = await nagSetup("navigation to 2...d5", nagOpened, () => navigateNagMove("d5"));
  await nagAssertion("the unknown $220 renders no board annotation hint", nagD5, () =>
    assertNagHint((hint) => !hint.rendered),
  );
  const nagNc3 = await nagSetup("navigation to 3.Nc3", nagOpened, () => navigateNagMove("Nc3"));
  const nagAnnotated = await nagSetup("Annotate panel ?! click", nagNc3, async () => {
    const tab = await session.execute(`
      const tab = [...document.querySelectorAll('[role="tab"]')].find((tab) => tab.textContent.trim() === 'Annotate');
      if (!tab) return false;
      const box = tab.getBoundingClientRect();
      return { x: Math.round(box.left + box.width / 2), y: Math.round(box.top + box.height / 2) };
    `);
    if (!tab) throw new Error("the Annotate tab was not rendered");
    await clickAt(session, tab.x, tab.y);
    const button = await waitFor(
      "the Annotate ?! control",
      () =>
        session.execute(`
      const button = [...document.querySelectorAll('[role="tabpanel"] button')].find((button) => button.textContent.trim() === '?!');
      if (!button) return false;
      const box = button.getBoundingClientRect();
      return box.width > 0 && box.height > 0 && { x: Math.round(box.left + box.width / 2), y: Math.round(box.top + box.height / 2) };
    `),
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
    await clickAt(session, button.x, button.y);
    return waitFor(
      "Nc3?! in the real notation",
      () =>
        session.execute(`
      return [...document.querySelectorAll('button[class*="cell"]')]
        .some((button) => button.textContent.trim().replace('♘', 'N') === 'Nc3?!');
    `),
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
  });
  const nagMovetext = (pgn) =>
    pgn
      .split(/\r?\n/)
      .filter((line) => line.trim() && !line.startsWith("["))
      .join(" ");
  const nagSaved = await nagAssertion(
    "SAVE_FILE writes Nc3?! to the seeded NAG file",
    nagAnnotated,
    async () => {
      const before = await readFile(nagsGamePath, "utf8");
      let observed = before;
      let readError;
      try {
        // SAVE_FILE is ctrl+s on Linux (src/state/keybinds.ts).
        await session.call("POST", "/actions", {
          actions: [
            {
              type: "key",
              id: "nag-save",
              actions: [
                { type: "keyDown", value: "\uE009" },
                { type: "keyDown", value: "s" },
                { type: "keyUp", value: "s" },
                { type: "keyUp", value: "\uE009" },
              ],
            },
          ],
        });
        return await waitFor(
          "the NAG file's saved Nc3?! edit",
          async () => {
            try {
              observed = await readFile(nagsGamePath, "utf8");
              readError = undefined;
            } catch (error) {
              readError = error.message;
              return false;
            }
            return observed.includes("Nc3?!") && observed;
          },
          { timeoutMs: FILES_PROBE_TIMEOUT_MS },
        );
      } catch (error) {
        throw new Error(
          `${error.message}; file changed: ${observed !== before}; NAG movetext: ${nagMovetext(observed)}${readError ? `; read error: ${readError}` : ""}`,
        );
      }
    },
  );
  for (const text of ["$8", "$11", "d4! $2", "$220"]) {
    await nagAssertion(`the saved NAG game preserves ${text}`, nagSaved, () => {
      const saved = nagSaved.value;
      if (!saved.includes(text)) throw new Error(`observed saved movetext: ${nagMovetext(saved)}`);
      return true;
    });
  }

  // Metadata-only edit through the real card and modal. Disk assertions depend on submission,
  // not its success: a rejected write must still leave the filename assertion independently green.
  const filesMetadataDialogCheck = "the Files metadata edit submits without a dialog error";
  const filesMetadataFilterCheck = "the Repertoire filter lists the metadata-edited workspace file";
  const filesMetadataSidecarCheck =
    "the metadata-edited workspace sidecar records repertoire on disk";
  const filesMetadataFilenameCheck = "the Files metadata edit preserves the PGN filename";
  const metadataAttempt = async (action) => {
    try {
      return { value: await action() };
    } catch (error) {
      return { error: error.message };
    }
  };
  const clickMetadataControl = async (label, lookup, args = []) => {
    const coordinates = await reachableStableCoordinates(session, label, lookup, args);
    if (coordinates.disabled) throw new Error(`${label} is disabled`);
    await clickAt(session, coordinates.x, coordinates.y);
    return coordinates.element;
  };
  const chooseRepertoire = async (inDialog) => {
    const control = await clickMetadataControl(
      inDialog ? "the edit dialog's File type Select" : "the Files page's File type filter",
      `(() => {
        const label = [...document.querySelectorAll('label')].find(label =>
          Boolean(label.closest('[role="dialog"]')) === arguments[0] &&
          label.textContent.replace(/\\s*\\*$/, '').trim() === 'File type');
        return label && document.getElementById(label.htmlFor);
      })()`,
      [inDialog],
    );
    await clickMetadataControl(
      "the opened File type control's Repertoire option",
      `(() => {
        const control = arguments[0];
        if (!control.isConnected) return null;
        const listboxId = control.getAttribute('aria-controls');
        const listbox = listboxId && document.getElementById(listboxId);
        if (listbox?.getAttribute('role') !== 'listbox') return null;
        return [...listbox.querySelectorAll('[role="option"]')].find(option =>
          ${ACCESSIBLE_TEXT}(option) === 'Repertoire');
      })()`,
      [control],
    );
    await waitFor(
      "the intended File type control to accept Repertoire before continuing",
      () =>
        session.execute(
          `const control = arguments[0];
           if (!control.isConnected) throw new Error('the intended File type control disconnected');
           return control.value === 'Repertoire';`,
          [control],
        ),
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
  };
  let metadataSubmitted = false;
  let originalWorkspacePgnNames;
  const metadataEdit = await metadataAttempt(async () => {
    originalWorkspacePgnNames = (await readdir(filesWorkspace))
      .filter((name) => name.endsWith(".pgn"))
      .sort();
    if (existsSync(filesMetadataInfoPath))
      throw new Error("the metadata fixture already has a sidecar");
    const row = await filesRowCoordinates(session, filesMetadataRowName, FILES_PROBE_TIMEOUT_MS);
    await clickAt(session, row.x, row.y);
    await clickMetadataControl(
      "the FileCard Edit metadata control",
      `document.querySelector('button[aria-label="Edit metadata"]')`,
    );
    await waitFor(
      "the metadata edit dialog with the unchanged Name",
      () =>
        session.execute(
          `
        const dialog = document.querySelector('[role="dialog"]');
        const label = dialog && [...dialog.querySelectorAll('label')].find(label => label.textContent.trim() === 'Name');
        return label && document.getElementById(label.htmlFor)?.value === arguments[0];`,
          [filesMetadataRowName],
        ),
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
    await chooseRepertoire(true);
    await clickMetadataControl(
      "the metadata edit Confirm control",
      `[...document.querySelectorAll('[role="dialog"] button')].find(button => button.textContent.trim() === 'Confirm')`,
    );
    metadataSubmitted = true;
    return waitFor(
      "the metadata edit to close or report a dialog error",
      () =>
        session.execute(`
        const dialog = document.querySelector('[role="dialog"]');
        if (!dialog) return { closed: true };
        const invalid = dialog.querySelector('input[aria-invalid="true"]');
        const error = invalid && document.getElementById(invalid.getAttribute('aria-describedby'));
        return invalid && { error: error?.textContent ?? 'the Name input is invalid' };`),
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
  });
  const metadataSetupError = metadataSubmitted
    ? undefined
    : `not attempted: metadata edit setup: ${metadataEdit.error}`;
  const metadataDialogError = metadataSetupError ?? metadataEdit.error ?? metadataEdit.value?.error;
  check(metadataEdit.value?.closed === true, filesMetadataDialogCheck, metadataDialogError);

  const metadataFilter = metadataDialogError
    ? {
        error: `not attempted: the metadata edit did not close successfully: ${metadataDialogError}`,
      }
    : await metadataAttempt(async () => {
        await chooseRepertoire(false);
        await filesRowCoordinates(session, filesMetadataRowName);
        return session.execute(`
          const label = [...document.querySelectorAll('label')].find(label =>
            !label.closest('[role="dialog"]') && label.textContent.trim() === 'File type');
          return label && document.getElementById(label.htmlFor)?.value === 'Repertoire';`);
      });
  check(metadataFilter.value === true, filesMetadataFilterCheck, metadataFilter.error);

  const metadataSidecar = metadataSetupError
    ? { error: metadataSetupError }
    : await metadataAttempt(async () => {
        const metadata = JSON.parse(await readFile(filesMetadataInfoPath, "utf8"));
        if (metadata.type !== "repertoire")
          throw new Error(`observed sidecar: ${JSON.stringify(metadata)}`);
        return true;
      });
  check(metadataSidecar.value === true, filesMetadataSidecarCheck, metadataSidecar.error);
  const metadataFilename = metadataSetupError
    ? { error: metadataSetupError }
    : await metadataAttempt(async () => {
        const currentPgnNames = (await readdir(filesWorkspace))
          .filter((name) => name.endsWith(".pgn"))
          .sort();
        if (
          !existsSync(filesMetadataPgnPath) ||
          JSON.stringify(currentPgnNames) !== JSON.stringify(originalWorkspacePgnNames)
        ) {
          throw new Error(
            `original PGN exists: ${existsSync(filesMetadataPgnPath)}; PGN filenames: ${JSON.stringify(currentPgnNames)}`,
          );
        }
        return true;
      });
  check(metadataFilename.value === true, filesMetadataFilenameCheck, metadataFilename.error);
  // Close a failed dialog before the later document-reload and shutdown checks.
  await session.call("POST", "/actions", {
    actions: [
      {
        type: "key",
        id: "metadata-dismiss",
        actions: [
          { type: "keyDown", value: "\uE00C" },
          { type: "keyUp", value: "\uE00C" },
          { type: "keyDown", value: "\uE00C" },
          { type: "keyUp", value: "\uE00C" },
        ],
      },
    ],
  });
  await waitFor(
    "the metadata dialog to be dismissed",
    () => session.execute("return !document.querySelector('[role=\"dialog\"]')"),
    { timeoutMs: FILES_PROBE_TIMEOUT_MS },
  );

  // Direct launches inherit precisely the primary's profile and off-screen display environment.
  const launchInstanceProbe = (env, args = []) => {
    const child = launch(APP_BINARY, args, { env });
    const stdout = outputBuffer();
    const stderr = outputBuffer();
    let launchError;
    child.on("error", (error) => {
      launchError = error;
    });
    child.stdout.on("data", (chunk) => {
      stdout.push(chunk);
    });
    child.stderr.on("data", (chunk) => {
      stderr.push(chunk);
    });
    return {
      child,
      stdout: () => stdout.text(),
      waitForExit: () =>
        waitFor(
          "the instance probe to exit by itself",
          () => {
            if (launchError) throw launchError;
            return child.exitCode !== null || child.signalCode !== null;
          },
          { timeoutMs: INSTANCE_PROBE_TIMEOUT_MS },
        ),
      waitForLine: (line) =>
        waitFor(
          line,
          () => {
            if (launchError) throw launchError;
            if (stdout.text().includes(line)) return true;
            if (child.exitCode !== null || child.signalCode !== null) {
              throw new Error(
                `instance probe exited before ${line}: ${stdout.text()}\n${stderr.text()}`,
              );
            }
            return false;
          },
          { timeoutMs: INSTANCE_PROBE_TIMEOUT_MS },
        ),
    };
  };
  const refusalCheck =
    "a second process on the same app-data directory is refused before initialization";
  const unchangedCheck =
    "the refused launch leaves authority and credential registry bytes unchanged";
  const primaryCheck = "the primary still answers WebDriver after the refused launch";
  const reportedInstanceChecks = new Set();
  const instanceCheck = (condition, description, detail) => {
    check(condition, description, detail);
    reportedInstanceChecks.add(description);
  };
  const instanceSetupFailure = (descriptions, step, error) => {
    for (const description of descriptions) {
      if (!reportedInstanceChecks.has(description)) {
        instanceCheck(false, description, `not attempted: ${step}: ${error.message}`);
      }
    }
  };
  const assertInstanceRefusal = async (
    probe,
    { description, stopStep, survivorMessage, setStep },
  ) => {
    await probe.waitForLine(
      "another ChessRiddle Studio process holds the application data directory",
    );
    setStep(stopStep);
    await stopLaunchedChild(probe.child);
    if (processExists(probe.child.pid)) throw new Error(survivorMessage);
    instanceCheck(
      !probe.stdout().includes("Finished rust initialization"),
      description,
      probe.stdout(),
    );
  };
  let refused;
  let refusalStep = "read the primary registries";
  try {
    const credentialRegistry = join(
      profileDirectory,
      ".local/share/com.chessriddle.studio/credentials/lichess-accounts.json",
    );
    const before = await Promise.all([readFile(registryFile), readFile(credentialRegistry)]);
    refusalStep = "wait for same-directory refusal";
    refused = launchInstanceProbe(appEnvironment);
    await assertInstanceRefusal(refused, {
      description: refusalCheck,
      stopStep: "stop the refused process",
      survivorMessage: "the refused process survived cleanup",
      setStep: (step) => {
        refusalStep = step;
      },
    });
    refusalStep = "read the primary registries after refusal";
    const after = await Promise.all([readFile(registryFile), readFile(credentialRegistry)]);
    instanceCheck(
      before.every((bytes, index) => bytes.equals(after[index])),
      unchangedCheck,
    );
    refusalStep = "query the primary WebDriver session after refusal";
    instanceCheck(
      await session.execute("return typeof window.__TAURI_INTERNALS__ === 'object'"),
      primaryCheck,
    );
  } catch (error) {
    instanceSetupFailure([refusalCheck, unchangedCheck, primaryCheck], refusalStep, error);
  } finally {
    if (refused) await stopLaunchedChild(refused.child);
  }

  const sharedConfigCheck = "a second process sharing only the configuration directory is refused";
  let differentData;
  let sharedConfig;
  let sharedConfigStep = "create the different-data root";
  try {
    differentData = await mkdtemp(join(tmpdir(), "chessfable-config-sharing-probe-"));
    registerTemporaryProfile(differentData);
    sharedConfigStep = "wait for shared-configuration refusal";
    sharedConfig = launchInstanceProbe({ ...appEnvironment, XDG_DATA_HOME: differentData });
    await assertInstanceRefusal(sharedConfig, {
      description: sharedConfigCheck,
      stopStep: "stop the shared-configuration process",
      survivorMessage: "the shared-configuration process survived cleanup",
      setStep: (step) => {
        sharedConfigStep = step;
      },
    });
  } catch (error) {
    instanceSetupFailure([sharedConfigCheck], sharedConfigStep, error);
  } finally {
    if (sharedConfig) await stopLaunchedChild(sharedConfig.child);
    if (differentData) await rm(differentData, { recursive: true, force: true });
  }

  const coexistenceCheck =
    "a process on a different app-data directory initializes while the primary runs";
  let differentProfile;
  let independent;
  let coexistenceStep = "create the different-HOME profile";
  try {
    differentProfile = await mkdtemp(join(tmpdir(), "chessfable-instance-probe-"));
    registerTemporaryProfile(differentProfile);
    coexistenceStep = "wait for different-HOME initialization";
    independent = launchInstanceProbe({ ...appEnvironment, HOME: differentProfile });
    await independent.waitForLine("Finished rust initialization");
    coexistenceStep = "query the primary WebDriver session during coexistence";
    instanceCheck(
      await session.execute("return typeof window.__TAURI_INTERNALS__ === 'object'"),
      coexistenceCheck,
    );
  } catch (error) {
    instanceSetupFailure([coexistenceCheck], coexistenceStep, error);
  } finally {
    if (independent) await stopLaunchedChild(independent.child);
    if (differentProfile) await rm(differentProfile, { recursive: true, force: true });
  }

  // A game link from the browser extension. The id is syntactically valid and names no game,
  // so the renderer's fetch ends in its error notification with or without a network.
  const GAME_LINK = "chessriddle-studio://import?url=https%3A%2F%2Flichess.org%2F00000000";
  const handoffExitCheck =
    "a second process started with a game link hands it to the primary and exits by itself";
  const handoffArrivalCheck = "the primary opens the handed-over game link";
  let handed;
  let handoffStep = "launch the process with a game link";
  try {
    handed = launchInstanceProbe(appEnvironment, [GAME_LINK]);
    handoffStep = "wait for the link process to exit";
    await handed.waitForExit();
    instanceCheck(
      handed.child.exitCode === 0 && !handed.stdout().includes("Finished rust initialization"),
      handoffExitCheck,
      `exit code ${handed.child.exitCode}, signal ${handed.child.signalCode}: ${handed.stdout()}`,
    );
    handoffStep = "wait for the primary to show the link being opened";
    await waitFor(
      "the primary to show the handed-over link being opened",
      () =>
        session.execute(
          "const text = document.body.innerText;" +
            "return text.includes('Opening game') || " +
            "text.includes('Could not open the game from Lichess');",
        ),
      { timeoutMs: INSTANCE_PROBE_TIMEOUT_MS },
    );
    instanceCheck(true, handoffArrivalCheck);
  } catch (error) {
    instanceSetupFailure([handoffExitCheck, handoffArrivalCheck], handoffStep, error);
  } finally {
    if (handed) await stopLaunchedChild(handed.child);
  }

  const coldLinkCheck =
    "a process started with a game link queues it before it finishes initializing";
  let coldProfile;
  let cold;
  let coldStep = "create the cold-start profile";
  try {
    coldProfile = await mkdtemp(join(tmpdir(), "chessfable-link-probe-"));
    registerTemporaryProfile(coldProfile);
    coldStep = "wait for cold-start initialization";
    cold = launchInstanceProbe({ ...appEnvironment, HOME: coldProfile }, [GAME_LINK]);
    await cold.waitForLine("Finished rust initialization");
    const output = cold.stdout();
    const queued = output.indexOf("queued a game link from the command line");
    instanceCheck(
      queued !== -1 &&
        queued < output.indexOf("Finished rust initialization") &&
        !output.includes(GAME_LINK),
      coldLinkCheck,
      output,
    );
  } catch (error) {
    instanceSetupFailure([coldLinkCheck], coldStep, error);
  } finally {
    if (cold) await stopLaunchedChild(cold.child);
    if (coldProfile) await rm(coldProfile, { recursive: true, force: true });
  }

  const reloadCheck = "a real document reload cancels the previous document's retained reservation";
  const workspaceTabsCheck =
    "a real document reload preserves both exact seeded workspace tab identities";
  const workspaceSelectionCheck = "a real document reload selects the second seeded workspace tab";
  const seededWorkspaceTabs = ["verify:workspace:first", "verify:workspace:second"].map((name) => ({
    name,
    value: randomUUID(),
    type: "new",
    gameOrigin: { kind: "none" },
  }));
  const seededWorkspace = {
    version: 1,
    tabs: seededWorkspaceTabs,
    activeTab: seededWorkspaceTabs[1].value,
  };
  let workspaceReloadPrepared = false;
  try {
    const previousDocumentRead = await invokeAndWait(
      session,
      "previous-document native read reservation to settle",
      "__verifyAppPreviousDocumentRead",
      `window.__TAURI_INTERNALS__.invoke("prepare_native_read", {})`,
    );
    if (typeof previousDocumentRead.value !== "string") {
      throw new Error(
        previousDocumentRead.rejected ??
          previousDocumentRead.error ??
          "no reservation ticket returned",
      );
    }
    const previousDocumentTicket = previousDocumentRead.value;
    await waitFor(
      "the board route before seeding the reload workspace",
      () =>
        session
          .execute(
            `const tab = document.querySelector(${JSON.stringify(BOARD_TAB_STOP_SELECTOR)});
         if (tab && location.pathname !== "/") tab.click();
         return location.pathname === "/" && !!document.querySelector(${JSON.stringify(BOARD_TAB_STOP_SELECTOR)});`,
          )
          .catch(() => false),
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
    await session.execute('sessionStorage.setItem("workspace", arguments[0]); return true;', [
      serializeStorageValue(seededWorkspace),
    ]);
    workspaceReloadPrepared = true;
    await session.call("POST", "/refresh", {});
    await waitFor(
      "the reloaded renderer and its previous-document reservation sweep",
      async () => {
        const ready = await session
          .execute("return typeof window.__TAURI_INTERNALS__ === 'object'")
          .catch(() => false);
        if (!ready) return false;
        const prefix = "reloaded webview main cancelled native reservations:";
        return (await readLog()).split("\n").some((line) => {
          const start = line.indexOf(prefix);
          if (start === -1) return false;
          const ids = line
            .slice(start + prefix.length)
            .trim()
            .split(",");
          return ids.includes(previousDocumentTicket);
        });
      },
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
    check(true, reloadCheck);
  } catch (error) {
    check(false, reloadCheck, error.message);
  }

  try {
    if (!workspaceReloadPrepared) throw new Error("the workspace reload fixture was not prepared");
    // Native sweep logging precedes render. Wait for a rendered board tablist independently,
    // without waiting for the expected identities that the assertions themselves must verify.
    const renderedWorkspace = await waitFor(
      "the reloaded workspace DOM",
      () =>
        session
          .execute(
            `if (document.readyState !== "complete" || location.pathname !== "/") return false;
         const tablist = document.querySelector('header [role="tablist"]');
         const tabs = [...(tablist?.querySelectorAll('[role="tab"]') ?? [])];
         if (tabs.length === 0 || !tabs.some((tab) => tab.getAttribute("aria-selected") === "true")) return false;
         const tabId = (tab) => tab.id.replace(/^board-tab-/, "");
         return {
           ids: tabs.map(tabId),
           selectedIds: tabs.filter((tab) => tab.getAttribute("aria-selected") === "true").map(tabId),
         };`,
          )
          .catch(() => false),
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
    check(
      renderedWorkspace.ids.length === 2 &&
        renderedWorkspace.ids.every((id, index) => id === seededWorkspaceTabs[index].value),
      workspaceTabsCheck,
      `rendered tab ids: ${JSON.stringify(renderedWorkspace.ids)}`,
    );
    check(
      renderedWorkspace.selectedIds.length === 1 &&
        renderedWorkspace.selectedIds[0] === seededWorkspace.activeTab,
      workspaceSelectionCheck,
      `selected tab ids: ${JSON.stringify(renderedWorkspace.selectedIds)}`,
    );
    if (screenshotPath) {
      await writeFile(screenshotPath, Buffer.from(await session.screenshot(), "base64"));
      console.log(`  ..  Reloaded workspace screenshot written to ${screenshotPath}`);
    }
  } catch (error) {
    check(false, workspaceTabsCheck, error.message);
    check(false, workspaceSelectionCheck, error.message);
  }

  await verifySelectedRootPermissions(session, permissionPuzzleRoot, permissionEngineRoot);

  // The reload log wait above confirms the startup sweep ran before this new-document reservation.
  // Its presence in the destroyed-window log below proves it survived that sweep until close.
  const retainedRead = await invokeAndWait(
    session,
    "retained native read reservation to settle",
    "__verifyAppRetainedRead",
    `window.__TAURI_INTERNALS__.invoke("prepare_native_read", {})`,
  );
  check(
    typeof retainedRead.value === "string",
    "a native read reservation is retained until titlebar close",
    retainedRead.rejected ?? retainedRead.error,
  );
  const retainedTicket = retainedRead.value;

  const describeProcesses = (processes) =>
    processes.map(({ pid, ppid, cmd }) => `${pid} ${ppid} ${cmd}`).join("\n      ");
  // The app's own control exercises the real RunEvent::ExitRequested path rather than a kill.
  const assertedClose = await closeApplicationThroughTitlebar(session, "asserted");
  const { application, webkitServicePids, running, gone, survivors } = assertedClose;
  check(true, "the application process is running before the close", describeProcesses(running));
  const trackedDescription =
    `application pid ${application.pid} and recorded WebKit service pids ` +
    `[${webkitServicePids.join(", ") || "none"}]`;
  check(
    gone && survivors.length === 0,
    `${trackedDescription} do not exist after the close`,
    survivors.length > 0 ? `surviving pids: ${survivors.join(", ")}` : undefined,
  );

  const log = await readLog();
  // This retained ticket belongs to the reloaded document and survived its startup sweep.
  check(
    log.includes(`destroyed webview main cancelled native reads/downloads: ${retainedTicket}`),
    "the real destroyed-window event cancels the exact retained main-webview reservation",
  );
  check(
    log.includes("Shutdown requested: terminating engines and live games"),
    "the shutdown sequence started",
  );
  check(
    log.includes("Shutdown cleanup finished"),
    "the shutdown cleanup ran to completion inside its budget",
    log.includes("Shutdown budget")
      ? "the budget elapsed instead — children may still be running"
      : undefined,
  );
  check(log.includes("Sound server shutdown signalled"), "the sound server shutdown was signalled");

  const shutdownRegistry = await readPathRegistry();
  check(
    !existsSync(retiredImage) &&
      existsSync(retainedImage) &&
      !shutdownRegistry.image_cleanup?.some(({ id }) => id.id === retiredImageId) &&
      shutdownRegistry.entries.some(({ id }) => id.id === retainedImageId),
    "titlebar shutdown removes retired image bytes and intent while retaining the owner",
  );

  console.log("\nshutdown log:");
  for (const line of log.split("\n").filter((line) => /Shutdown|Sound server/.test(line))) {
    console.log(`  ${line}`);
  }

  // Reset the throwaway HOME only after all existing checks and their shutdown evidence. This
  // fresh profile has no active custom root or cached list, and the db file predates app startup.
  const databaseRootCheck =
    "default-root-unusable: the Databases alert offers a visible folder chooser";
  try {
    if (!gone || survivors.length > 0) throw new Error("the asserted application survived close");
    const released = await session.quit();
    if (!released.released)
      throw new Error(`could not release the asserted session: ${released.error}`);
    await rm(profileDirectory, { recursive: true, force: true });
    const appDataDirectory = join(profileDirectory, ".local/share/com.chessriddle.studio");
    await mkdir(appDataDirectory, { recursive: true });
    await mkdir(join(profileDirectory, ".config/com.chessriddle.studio"), { recursive: true });
    await mkdir(join(profileDirectory, "ChessRiddle Studio"), { recursive: true });
    await writeFile(
      join(profileDirectory, "ChessRiddle Studio/Databases"),
      "home default database root is a regular file\n",
    );
    await writeFile(join(appDataDirectory, "db"), "default database root is a regular file\n");
    session = await Session.open(APP_BINARY);
    const alert = await databaseAlert(session, "the unusable default database root alert");
    check(
      alert.message === "This database folder cannot be opened. Choose another." &&
        alert.buttonDisplayed === true,
      databaseRootCheck,
      `observed Databases alert: ${JSON.stringify(alert)}`,
    );
  } catch (error) {
    check(false, databaseRootCheck, error.message);
  }

  // Let the real page activate its default in a fresh profile, then remove that selected folder
  // while the app is stopped. Relaunching re-proves the persisted selection without a cached list.
  const selectedRootCheck =
    "selected-root-missing: the Databases alert offers a visible folder chooser without recreating db";
  const selectedDatabaseRoot = join(profileDirectory, "ChessRiddle Studio/Databases");
  const defaultLocationCheck =
    "fresh profile Databases default is HOME/ChessRiddle Studio/Databases";
  const pgnControlCheck = "PGN row folder control shows the leaf PGN";
  let defaultLocationSeen = false;
  let pgnControlSeen = false;
  try {
    const closed = await closeApplicationThroughTitlebar(session, "default-root-unusable");
    if (!closed.gone || closed.survivors.length > 0)
      throw new Error("the default-root-unusable application survived close");
    const released = await session.quit();
    if (!released.released)
      throw new Error(`could not release the default-root-unusable session: ${released.error}`);
    await rm(profileDirectory, { recursive: true, force: true });
    await mkdir(join(profileDirectory, ".config/com.chessriddle.studio"), { recursive: true });
    session = await Session.open(APP_BINARY);
    await waitFor(
      "the Databases page to activate the default database root",
      async () => {
        await showLibraryOverview(session);
        const onDatabases = await session.execute('return location.pathname === "/library"');
        if (!onDatabases || !existsSync(selectedDatabaseRoot)) return false;
        const registry = await readFile(registryFile, "utf8")
          .then(JSON.parse)
          .catch((error) => {
            if (error.code === "ENOENT") return null;
            throw error;
          });
        if (!registry) return false;
        const active = registry.entries.find(
          ({ id }) => id.id === registry.active_database_root?.id,
        );
        return (
          active?.purpose === "databaseRoot" &&
          active.target_is_dir &&
          active.path.platform === "unix" &&
          Buffer.from(active.path.bytes, "base64").toString() === selectedDatabaseRoot
        );
      },
      { timeoutMs: FILES_PROBE_TIMEOUT_MS },
    );
    check(existsSync(selectedDatabaseRoot), defaultLocationCheck);
    defaultLocationSeen = true;
    try {
      await goToSettings(session);
      const tab = await reachableStableCoordinates(
        session,
        "Directories settings tab",
        `document.querySelector('[role="tab"][data-settings-category="directories"]')`,
      );
      await clickAt(session, tab.x, tab.y);
      await waitFor(
        "PGN folder control leaf",
        async () => {
          const text = await session.execute(`
            const row = document.querySelector('[data-setting-id="files-directory"]');
            const button = row && row.querySelector('button[aria-label="Select directory"]');
            return button ? button.textContent.trim() : "";
          `);
          return text === "PGN";
        },
        { timeoutMs: FILES_PROBE_TIMEOUT_MS },
      );
      check(true, pgnControlCheck);
      pgnControlSeen = true;
    } catch (error) {
      check(false, pgnControlCheck, error.message);
      pgnControlSeen = true;
    }
    const activatedClose = await closeApplicationThroughTitlebar(
      session,
      "activated database root",
    );
    if (!activatedClose.gone || activatedClose.survivors.length > 0)
      throw new Error("the activated database root application survived close");
    const activatedRelease = await session.quit();
    if (!activatedRelease.released)
      throw new Error(`could not release the activated-root session: ${activatedRelease.error}`);
    await rename(selectedDatabaseRoot, join(selectedDatabaseRoot, "..", "db-moved"));
    session = await Session.open(APP_BINARY);
    const alert = await databaseAlert(session, "the missing selected database root alert");
    const dbExists = existsSync(selectedDatabaseRoot);
    check(
      alert.message === "This database folder is no longer available. Choose another." &&
        alert.buttonDisplayed === true &&
        !dbExists,
      selectedRootCheck,
      `observed Databases alert: ${JSON.stringify({ ...alert, dbExists })}`,
    );

    async function repointActiveDatabaseRoot(dirPath, displayName) {
      const dirStat = statSync(dirPath);
      const parentStat = statSync(join(dirPath, ".."));
      const registry = JSON.parse(await readFile(registryFile, "utf8"));
      const activeEntry = registry.entries.find(
        ({ id }) => id.id === registry.active_database_root?.id,
      );
      if (!activeEntry) {
        throw new Error(`no active database root entry in registry for ${displayName}`);
      }
      activeEntry.display_name = displayName;
      activeEntry.path = {
        platform: "unix",
        bytes: Buffer.from(dirPath).toString("base64").replace(/=+$/, ""),
      };
      activeEntry.identity = { a: Number(dirStat.dev), b: Number(dirStat.ino) };
      activeEntry.parent_identity = { a: Number(parentStat.dev), b: Number(parentStat.ino) };
      await writeFile(registryFile, JSON.stringify(registry, null, 2), "utf8");
    }

    // Phase 3 real-app check: create a database in a custom folder, switch to another folder
    // with Move (via Restore default -> FolderSwitchModal -> Move), assert the database opens
    // from the new folder and the old file is gone.
    const moveSwitchCheck =
      "folder switch with Move relocates a custom-folder database, opens it from the new folder, and deletes the old file";
    try {
      const missingClose = await closeApplicationThroughTitlebar(session, "selected-root-missing");
      if (!missingClose.gone || missingClose.survivors.length > 0)
        throw new Error("the selected-root-missing application survived close");
      const missingRelease = await session.quit();
      if (!missingRelease.released)
        throw new Error(
          `could not release the selected-root-missing session: ${missingRelease.error}`,
        );

      const customDbRoot = join(profileDirectory, "custom-move-dbs");
      await rm(join(selectedDatabaseRoot, "..", "db-moved"), { recursive: true, force: true });
      await rm(selectedDatabaseRoot, { recursive: true, force: true });
      await mkdir(customDbRoot, { recursive: true });
      await repointActiveDatabaseRoot(customDbRoot, "custom-move-dbs");

      session = await Session.open(APP_BINARY);
      await waitFor("renderer ready for folder move check", () =>
        session.execute("return Boolean(window.__TAURI_INTERNALS__?.invoke)"),
      );
      const fileWorkspace = await invokeIpc(
        session,
        "__folderMoveGetFileWorkspace",
        "get_default_file_workspace",
        {},
      );
      const seedPgn = await invokeIpc(
        session,
        "__folderMoveCreateSeedPgn",
        "create_workspace_file",
        {
          workspace: fileWorkspace.handle,
          parent: fileWorkspace.handle,
          name: "move-verify-seed",
          metadata: { type: "other", tags: [] },
          content: {
            kind: "text",
            pgn: '[Event "Move Verify"]\n[White "White"]\n[Black "Black"]\n[Result "1-0"]\n\n1. e4 e5 1-0\n',
          },
        },
      );
      const customWorkspace = await invokeIpc(
        session,
        "__folderMoveGetDbWorkspace",
        "get_database_workspace",
        {},
      );
      const createdHandle = await invokeIpc(
        session,
        "__folderMoveCreateDb",
        "create_workspace_database",
        {
          root: customWorkspace.root,
          filename: "move-verify.db3",
        },
      );
      await invokeIpc(session, "__folderMoveInitDb", "convert_pgn", {
        progressId: "move-verify",
        files: [seedPgn.handle],
        database: createdHandle,
        timestamp: null,
        title: "Move Verify",
        description: "Verify folder move",
      });
      if (!existsSync(join(customDbRoot, "move-verify.db3"))) {
        throw new Error("move-verify.db3 was not created in custom folder");
      }

      await goToSettings(session);
      const dirTab = await reachableStableCoordinates(
        session,
        "Directories settings tab for move check",
        `document.querySelector('[role="tab"][data-settings-category="directories"]')`,
      );
      await clickAt(session, dirTab.x, dirTab.y);
      await waitFor(
        "Databases row shows custom-move-dbs and Restore default",
        async () =>
          Boolean(
            await session.execute(`
              const row = document.querySelector('[data-setting-id="databases-directory"]');
              if (!row) return false;
              const picker = row.querySelector('button[aria-label="Select directory"]');
              const restore = Array.from(row.querySelectorAll('button')).find(
                (b) => b.textContent.trim() === 'Restore default'
              );
              return Boolean(picker && picker.textContent.trim() === 'custom-move-dbs' && restore);
            `),
          ),
        { timeoutMs: FILES_PROBE_TIMEOUT_MS },
      );
      const restoreCoords = await reachableStableCoordinates(
        session,
        "Databases Restore default button",
        `Array.from(document.querySelectorAll('[data-setting-id="databases-directory"] button')).find((b) => b.textContent.trim() === 'Restore default')`,
      );
      await clickAt(session, restoreCoords.x, restoreCoords.y);
      const moveCoords = await reachableStableCoordinates(
        session,
        "Move files to new folder button",
        `Array.from(document.querySelectorAll('[role="dialog"] button')).find((b) => b.textContent.trim() === 'Move files to new folder')`,
      );
      await clickAt(session, moveCoords.x, moveCoords.y);
      await waitFor(
        "Databases row switched to Databases after Move",
        async () =>
          Boolean(
            await session.execute(`
              const row = document.querySelector('[data-setting-id="databases-directory"]');
              const dialog = document.querySelector('[role="dialog"]');
              const picker = row && row.querySelector('button[aria-label="Select directory"]');
              return !dialog && Boolean(picker && picker.textContent.trim() === 'Databases');
            `),
          ),
        { timeoutMs: FILES_PROBE_TIMEOUT_MS },
      );

      const movedExists = existsSync(join(selectedDatabaseRoot, "move-verify.db3"));
      const oldGone = !existsSync(join(customDbRoot, "move-verify.db3"));
      const movedWorkspace = await invokeIpc(
        session,
        "__folderMoveAfterWorkspace",
        "get_database_workspace",
        {},
      );
      const listing = await invokeIpc(
        session,
        "__folderMoveAfterList",
        "list_workspace_databases",
        { root: movedWorkspace.root, ticket: null },
      );
      const entry = listing?.entries?.find((e) => e.filename === "move-verify.db3");
      const info = entry
        ? await invokeIpc(session, "__folderMoveAfterInfo", "get_db_info", {
            file: entry.handle,
            ticket: null,
          })
        : null;
      const listed = { found: Boolean(entry), opened: info?.title === "Move Verify" };
      check(
        movedExists && oldGone && Boolean(listed?.found) && Boolean(listed?.opened),
        moveSwitchCheck,
        `observed move result: ${JSON.stringify({ movedExists, oldGone, listed })}`,
      );
    } catch (error) {
      check(false, moveSwitchCheck, error.message);
    }

    // Phase 4 real-app check: a profile whose active database root is the legacy app-data `db`
    // directory with one database starts and lists that database from the release default
    // `<HOME>/ChessRiddle Studio/Databases`, and the legacy directory is gone.
    const legacyMigrationCheck =
      "legacy app-data db root migrates on startup to release default HOME/ChessRiddle Studio/Databases and removes legacy db dir";
    try {
      const moveClose = await closeApplicationThroughTitlebar(session, "folder-move-switch");
      if (!moveClose.gone || moveClose.survivors.length > 0)
        throw new Error("the folder-move-switch application survived close");
      const moveRelease = await session.quit();
      if (!moveRelease.released)
        throw new Error(`could not release the folder-move-switch session: ${moveRelease.error}`);

      const legacyDbDir = join(profileDirectory, ".local/share/com.chessriddle.studio/db");
      await rm(legacyDbDir, { recursive: true, force: true });
      await mkdir(legacyDbDir, { recursive: true });
      const seedDbSource = join(selectedDatabaseRoot, "move-verify.db3");
      const legacyDbFile = join(legacyDbDir, "legacy-migrate.db3");
      await writeFile(legacyDbFile, await readFile(seedDbSource));
      await rm(selectedDatabaseRoot, { recursive: true, force: true });
      await repointActiveDatabaseRoot(legacyDbDir, "db");

      session = await Session.open(APP_BINARY);
      await waitFor("renderer ready for legacy migration check", () =>
        session.execute("return Boolean(window.__TAURI_INTERNALS__?.invoke)"),
      );

      const migratedWorkspace = await invokeIpc(
        session,
        "__legacyMigrationGetDbWorkspace",
        "get_database_workspace",
        {},
      );
      const migratedStatus = await invokeIpc(
        session,
        "__legacyMigrationGetDbStatus",
        "get_database_folder_status",
        {},
      );
      const migratedListing = await invokeIpc(
        session,
        "__legacyMigrationListDbs",
        "list_workspace_databases",
        { root: migratedWorkspace.root, ticket: null },
      );
      const migratedEntry = migratedListing?.entries?.find(
        (e) => e.filename === "legacy-migrate.db3",
      );
      const migratedInfo = migratedEntry
        ? await invokeIpc(session, "__legacyMigrationDbInfo", "get_db_info", {
            file: migratedEntry.handle,
            ticket: null,
          })
        : null;
      const inReleaseDefault = existsSync(join(selectedDatabaseRoot, "legacy-migrate.db3"));
      const legacyGone = !existsSync(legacyDbDir);
      check(
        inReleaseDefault &&
          legacyGone &&
          migratedStatus?.isDefault === true &&
          migratedStatus?.displayName === "Databases" &&
          Boolean(migratedEntry) &&
          migratedInfo?.title === "Move Verify",
        legacyMigrationCheck,
        `observed legacy migration result: ${JSON.stringify({
          inReleaseDefault,
          legacyGone,
          migratedStatus,
          found: Boolean(migratedEntry),
          title: migratedInfo?.title ?? null,
        })}`,
      );
    } catch (error) {
      check(false, legacyMigrationCheck, error.message);
    }
  } catch (error) {
    if (!defaultLocationSeen) check(false, defaultLocationCheck, error.message);
    if (!pgnControlSeen) check(false, pgnControlCheck, error.message);
    check(
      false,
      selectedRootCheck,
      `${error.message}; db exists: ${existsSync(selectedDatabaseRoot)}`,
    );
  }
}

// Staged 2026-11-09 by running --fallback-engine-install against a release build from before
// this feature (no Install Stockfish button): exit status 1, "5 check(s) failed".
// FE4 failed with its own message. FE5 to FE8 each failed with their distinct dependency message:
// "FE4 empty Engines page was not reached", "FE5 bounded install observation did not complete",
// "FE6 automation marker exclusion failed", "FE7 fallback button was not clicked".
// FE1, FE2, FE3 and FE9 are argued, not staged: breaking them needs a build that does not start,
// a browser without navigator.webdriver, or a pre-seeded profile or failed screenshot write,
// which this mode cannot produce without changing the verifier.
async function verifyFallbackEngineInstall(session, { screenshot = true } = {}) {
  const startup = await assertion(
    "FE1 fallback install renderer starts on the unseeded profile",
    () => waitFor("fallback install renderer startup", () => session.execute(closeControlProbe)),
  );
  const webdriver = await assertion("FE2 navigator.webdriver is true in the real app", async () => {
    if (!startup) throw new Error("FE1 renderer startup failed");
    const value = await session.execute("return navigator.webdriver");
    if (value !== true) throw new Error(`navigator.webdriver was ${JSON.stringify(value)}`);
  });
  const unseeded = await assertion("FE3 fallback profile has no saved engines key", async () => {
    if (!webdriver) throw new Error("FE2 webdriver exclusion was not established");
    const value = await session.execute("return localStorage.getItem('engines')");
    if (value !== null) throw new Error(`engines key already exists: ${value}`);
  });
  const opened = await assertion(
    "FE4 the empty Engines page offers Install Stockfish",
    async () => {
      if (!unseeded) throw new Error("FE3 profile is not unseeded");
      await goToEngines(session);
      await waitFor("the empty Engines fallback button", () =>
        session.execute(`
      return location.pathname === '/engines' && [...document.querySelectorAll('button')]
        .some(button => !button.disabled && button.textContent.trim() === 'Install Stockfish');
    `),
      );
    },
  );
  let markerStayedAbsent = false;
  const quiet = await assertion(
    "FE5 no engine install starts during the bounded automation wait",
    async () => {
      if (!opened) throw new Error("FE4 empty Engines page was not reached");
      const deadline = Date.now() + 3000;
      markerStayedAbsent = true;
      do {
        const sample = await session.execute(`
        return {
          marker: localStorage.getItem('first-launch-stockfish'),
          engines: localStorage.getItem('engines'),
          downloading: [...document.querySelectorAll('button')].some(button =>
            /Downloading|Extracting/.test(button.textContent))
        };
      `);
        markerStayedAbsent &&= sample.marker === null;
        const pending = await invokeJsonAndWait(
          session,
          "fallback pending engine installs",
          "__verifyFallbackPending",
          'window.__TAURI_INTERNALS__.invoke("pending_engine_completions")',
        );
        if (pending.error || !Array.isArray(pending.value)) {
          throw new Error(`pending install observation failed: ${JSON.stringify(pending)}`);
        }
        if (sample.downloading || sample.engines !== null || pending.value.length !== 0) {
          throw new Error(`unexpected install activity: ${JSON.stringify({ sample, pending })}`);
        }
        await new Promise((resolve) => setTimeout(resolve, 100));
      } while (Date.now() < deadline);
    },
  );
  const marker = await assertion(
    "FE6 the first-launch marker stays absent under WebDriver",
    async () => {
      if (!quiet) throw new Error("FE5 bounded install observation did not complete");
      if (!markerStayedAbsent) throw new Error("first-launch-stockfish appeared during the wait");
      const value = await session.execute("return localStorage.getItem('first-launch-stockfish')");
      if (value !== null) throw new Error(`first-launch-stockfish exists: ${value}`);
    },
  );
  const clicked = await assertion(
    "FE7 Install Stockfish accepts a real fallback install",
    async () => {
      if (!marker) throw new Error("FE6 automation marker exclusion failed");
      await clickButton(session, "Install Stockfish");
    },
  );
  await assertion(
    "FE8 the real download registers Stockfish in the Engines list within ten minutes",
    async () => {
      if (!clicked) throw new Error("FE7 fallback button was not clicked");
      await waitFor(
        "Stockfish in the Engines list",
        () =>
          session.execute(`
      return location.pathname === '/engines' && [...document.querySelectorAll('button[aria-pressed] p')]
        .some(label => label.textContent.trim() === 'Stockfish');
    `),
        { timeoutMs: 600_000, everyMs: 500 },
      );
    },
  );
  if (screenshotPath && screenshot) {
    await assertion("FE9 fallback engine install screenshot is written", async () => {
      await writeFile(screenshotPath, Buffer.from(await session.screenshot(), "base64"));
    });
  }
}

/** 1.e4 e5 2.Qh5 Nc6 3.Bc4 Nf6?? 4.Qxf7#: a short game whose 3...Nf6 any engine marks `??`. */
const GAME_REPORT_MOVES = ["e2e4", "e7e5", "d1h5", "b8c6", "f1c4", "g8f6", "h5f7"];
const GAME_REPORT_TIMEOUT_MS = 180_000;

/** Plays one UCI move on the white-oriented board by clicking its two squares. */
async function clickBoardMove(session, uci, ply) {
  const rect = await session.execute(`
    const box = document.querySelector('cg-board').getBoundingClientRect();
    return { left: box.left, top: box.top, width: box.width, height: box.height };
  `);
  const centre = (square) => ({
    x: Math.round(rect.left + ((square.charCodeAt(0) - 97 + 0.5) * rect.width) / 8),
    y: Math.round(rect.top + ((8 - Number(square[1]) + 0.5) * rect.height) / 8),
  });
  for (const square of [uci.slice(0, 2), uci.slice(2, 4)]) {
    const { x, y } = centre(square);
    await clickAt(session, x, y);
  }
  await waitFor(`move ${ply} (${uci}) in the active tree`, async () => {
    const snapshot = await readActiveTabTree(session);
    let node = snapshot.tree?.root;
    let depth = 0;
    while (node?.children?.[0]) {
      node = node.children[0];
      depth += 1;
    }
    return depth === ply;
  });
}

// GR checks run after FE1-FE8 installed Stockfish through the real catalog download. Each check
// names the one it depends on, so a failure reports where the flow stopped.
async function verifyGameReport(session) {
  const inDialog = (text) =>
    `[...document.querySelectorAll('[role="dialog"] button')].find(node => !node.disabled && node.textContent.trim() === ${JSON.stringify(text)})`;
  const played = await assertion(
    "GR1 the short game is played on a real Analysis Board",
    async () => {
      // A fresh profile opens on a New Tab; its Analysis Board card opens an empty board.
      await goToBoards(session);
      await clickButton(session, "Analysis Board");
      await waitFor("the empty analysis board", () =>
        session.execute("return !!document.querySelector('cg-board')"),
      );
      for (const [index, uci] of GAME_REPORT_MOVES.entries())
        await clickBoardMove(session, uci, index + 1);
    },
  );
  const started = await assertion(
    "GR2 the Report tab runs a report with the installed engine",
    async () => {
      if (!played) throw new Error("GR1 game was not played");
      // The default 800x648 window clips the Report tab below its first card.
      await session.call("POST", "/window/rect", { width: 1400, height: 1000 });
      for (const name of ["Analysis", "Report"]) {
        const tab = await reachableStableCoordinates(
          session,
          `the ${name} tab`,
          `[...document.querySelectorAll('[role="tab"]')].find(tab => tab.textContent.trim() === ${JSON.stringify(name)})`,
        );
        await clickAt(session, tab.x, tab.y);
      }
      await clickButton(session, "Generate report");
      await waitFor("the dialog's engine selection", () =>
        session.execute(
          `return [...document.querySelectorAll('[role="dialog"] input')].some(input => input.value.startsWith('Stockfish'))`,
        ),
      );
      // Mantine fades the modal in; a screenshot taken before the fade ends shows no dialog.
      await waitForDialogShown(session);
      if (screenshotPath) {
        const dialogPath = screenshotPath.replace(/(\.png)?$/, "-dialog.png");
        await writeFile(dialogPath, Buffer.from(await session.screenshot(), "base64"));
        console.log(`  .. game report dialog screenshot: ${dialogPath}`);
      }
      const analyze = await reachableStableCoordinates(session, "Analyze", inDialog("Analyze"));
      await clickAt(session, analyze.x, analyze.y);
    },
  );
  const finished = await assertion("GR3 the finished report shows its provenance", async () => {
    if (!started) throw new Error("GR2 report did not start");
    const provenance = await waitFor(
      "the report provenance line",
      () =>
        session.execute(
          `return document.querySelector('[data-testid="report-provenance"]')?.textContent ?? false`,
        ),
      { timeoutMs: GAME_REPORT_TIMEOUT_MS, everyMs: 500 },
    );
    if (!/^Analyzed by Stockfish.*, 0\.5 s per position, on /.test(provenance))
      throw new Error(`unexpected provenance: ${provenance}`);
    console.log(`  .. provenance: ${provenance}`);
  });
  await assertion("GR4 both sides get an accuracy card", async () => {
    if (!finished) throw new Error("GR3 report did not finish");
    const cards = await session.execute(
      `return [...document.querySelectorAll('[data-testid="report-accuracy"]')].map(card => card.innerText.replace(/\\s+/g, ' '))`,
    );
    if (cards.length !== 2 || !cards.every((card) => /\d+\.\d%/.test(card)))
      throw new Error(`accuracy cards: ${JSON.stringify(cards)}`);
    console.log(`  .. accuracy: ${JSON.stringify(cards)}`);
  });
  await assertion("GR5 the report marks 3...Nf6 a blunder in the key moments", async () => {
    if (!finished) throw new Error("GR3 report did not finish");
    const moments = await session.execute(
      `return [...document.querySelectorAll('[data-testid="report-key-moment"]')].map(row => row.innerText.replace(/\\s+/g, ' '))`,
    );
    if (!moments.some((row) => row.includes("Nf6??")))
      throw new Error(`key moments: ${JSON.stringify(moments)}`);
    console.log(`  .. key moments: ${JSON.stringify(moments)}`);
  });
  if (screenshotPath) {
    await assertion("GR6 game report screenshot is written", async () => {
      if (!finished) throw new Error("GR3 report did not finish");
      // The pointer still rests where Analyze was, over the chart; its tooltip would cover the card.
      await session.call("POST", "/actions", {
        actions: [
          {
            type: "pointer",
            id: "mouse",
            parameters: { pointerType: "mouse" },
            actions: [{ type: "pointerMove", duration: 0, x: 1, y: 990, origin: "viewport" }],
          },
        ],
      });
      await writeFile(screenshotPath, Buffer.from(await session.screenshot(), "base64"));
      console.log(`  .. game report screenshot: ${screenshotPath}`);
      // The Report tab scrolls inside its own viewport, not the document.
      await session.execute(`
        const moment = document.querySelector('[data-testid="report-key-moment"]');
        let viewport = moment.parentElement;
        while (viewport && viewport.scrollHeight <= viewport.clientHeight) viewport = viewport.parentElement;
        if (viewport) viewport.scrollTop += moment.getBoundingClientRect().top - viewport.getBoundingClientRect().top - 40;
      `);
      await waitFor("the key moment scrolled into view", () =>
        session.execute(`
          const box = document.querySelector('[data-testid="report-key-moment"]').getBoundingClientRect();
          return box.top >= 0 && box.bottom <= innerHeight;
        `),
      );
      const momentsPath = screenshotPath.replace(/(\.png)?$/, "-key-moments.png");
      await writeFile(momentsPath, Buffer.from(await session.screenshot(), "base64"));
      console.log(`  .. game report key moments screenshot: ${momentsPath}`);
    });
  }
}

const TIMED_RUN_TIMEOUT_MS = 60_000;
const TIMED_RUN_REPERTOIRE_ID = "verify-timed-run-00000000-0000-4000-8000-000000000001";
const TIMED_RUN_REPERTOIRE_NAME = "verify-timed-run";
const TIMED_RUN_REFERENCE_NAME = "verify-timed-run-reference";
const TIMED_RUN_DATABASE_ROOT_ID = "verify-timed-run-db-root";
const TIMED_RUN_PGN_ITALIAN = "Italian Game";
const TIMED_RUN_PGN_QUEENS_GAMBIT = "Queen's Gambit";
const TIMED_RUN_SELECTED_MINUTES = 10;
const TIMED_RUN_COUNTDOWN_SECONDS = TIMED_RUN_SELECTED_MINUTES * 60;
const TIMED_RUN_COUNTDOWN_FLOOR_SECONDS = 8 * 60;
// Higher weights on the second PGN chapter so TR4 fails if the planner walks file order.
const TIMED_RUN_LEADING_CHAPTER_WEIGHTS = [0.9, 0.6];
const TIMED_RUN_TRAILING_CHAPTER_WEIGHTS = [0.3, 0.2];
const TIMED_RUN_FIRST_SEGMENT = TIMED_RUN_PGN_QUEENS_GAMBIT;
const TIMED_RUN_SECOND_SEGMENT = TIMED_RUN_PGN_ITALIAN;

function whiteLinePracticePositions(sans) {
  const position = Chess.default();
  const cards = [];
  for (const san of sans) {
    const move = parseSan(position, san);
    if (!move) throw new Error(`timed-run fixture move is illegal: ${san}`);
    if (position.turn === "white") {
      cards.push({
        fen: makeFen(position.toSetup()),
        answer: san,
        uci: practiceMoveUci(move),
      });
    }
    position.play(move);
  }
  if (cards.length === 0) throw new Error("timed-run fixture produced no white cards");
  return cards;
}

/** Empty Start excludes the game root, so the first white ply is not a practice card. */
function timedRunChapterCards(sans) {
  const cards = whiteLinePracticePositions(sans).slice(1);
  if (cards.length === 0) throw new Error("timed-run chapter produced no in-scope white cards");
  return cards;
}

function timedRunPgn(event, white, black, moves) {
  return `[Event "${event}"]
[Site "verify:app"]
[Date "2026.11.24"]
[Round "1"]
[White "${white}"]
[Black "${black}"]
[Result "*"]

${moves}
`;
}

async function writeTimedRunScreenshot(directory, name, session) {
  const path = join(directory, name);
  await writeFile(path, Buffer.from(await session.screenshot(), "base64"));
  console.log(`  .. timed-run screenshot: ${path}`);
}

function timedRunLogFile(profileDirectory) {
  return join(profileDirectory, ".local/share/com.chessriddle.studio/logs/chessriddle-studio.log");
}

async function printTimedRunAppLog(profileDirectory) {
  try {
    const text = await readFile(timedRunLogFile(profileDirectory), "utf8");
    const { lines } = formatSinceOpenLog(text);
    console.log("  .. timed-run application-log ERROR/WARN:");
    if (lines.length === 0) console.log("     (none)");
    else for (const line of lines) console.log(`     ${line}`);
  } catch (error) {
    console.log(`  .. timed-run application-log unavailable: ${error.message}`);
  }
}

async function captureTimedRunFailure(session, screenshotDirectory, label) {
  const slug = label
    .replace(/[^A-Za-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 48);
  try {
    const body = await session.execute(`
      return (document.body && document.body.innerText ? document.body.innerText : "")
        .replace(/\\s+/g, " ")
        .trim();
    `);
    console.log(`  .. ${label} visible text: ${body}`);
  } catch (error) {
    console.log(`  .. ${label} visible text unavailable: ${error.message}`);
  }
  try {
    await writeTimedRunScreenshot(screenshotDirectory, `${slug}-fail.png`, session);
  } catch (error) {
    console.log(`  .. ${label} failure screenshot unavailable: ${error.message}`);
  }
}

async function timedRunMinutesState(session) {
  return session.execute(`
    const root = document.querySelector('[data-train-openings] [role="radiogroup"]');
    if (!root) return { present: false };
    const boxOf = (node) => {
      const box = node.getBoundingClientRect();
      return { x: Math.round(box.x), y: Math.round(box.y), w: Math.round(box.width), h: Math.round(box.height) };
    };
    const inputs = [...root.querySelectorAll('input[type="radio"]')].map((input) => ({
      value: input.value,
      checked: input.checked,
    }));
    const labels = [...root.querySelectorAll('label')].map((label) => ({
      text: label.textContent.replace(/\\s+/g, " ").trim(),
      active: label.hasAttribute("data-active"),
      activeAttr: label.getAttribute("data-active"),
      box: boxOf(label),
    }));
    const indicator = root.querySelector('[class*="indicator"]');
    return {
      present: true,
      checked: inputs.find((input) => input.checked)?.value ?? null,
      inputs,
      labels,
      indicator: indicator ? boxOf(indicator) : null,
    };
  `);
}

function minuteIndicatorFollowsActive(state, tolerancePx = 2) {
  const active = state?.labels?.find((label) => label.active);
  if (!state?.present || !active?.box || !state.indicator) return false;
  return (
    Math.abs(state.indicator.x - active.box.x) <= tolerancePx &&
    Math.abs(state.indicator.w - active.box.w) <= tolerancePx
  );
}

function assertTimedRunMinutePaint(state, minutes) {
  if (state?.checked !== String(minutes)) {
    throw new Error(`minute control value was ${JSON.stringify(state)}`);
  }
  const active = state.labels?.find((label) => label.active);
  if (!active?.box) {
    throw new Error(`no data-active minute label: ${JSON.stringify(state)}`);
  }
  if (!state.indicator) {
    throw new Error(`minute indicator missing: ${JSON.stringify(state)}`);
  }
  if (!minuteIndicatorFollowsActive(state)) {
    throw new Error(
      `minute indicator ${JSON.stringify(state.indicator)} did not match data-active ${JSON.stringify(active.box)}: ${JSON.stringify(state)}`,
    );
  }
}

async function timedRunPageText(session) {
  return session.execute(`
    const tab = document.querySelector('header [role="tablist"] [role="tab"][aria-selected="true"]');
    const train = [...document.querySelectorAll('[role="tab"]')].find((node) => node.textContent.trim() === 'Train');
    const body = (document.body && document.body.innerText ? document.body.innerText : "").replace(/\\s+/g, " ").trim();
    const countdown = body.match(/(\\d+):(\\d{2}) remaining/);
    const summary = body.match(/(\\d+) positions · (\\d+) correct · (\\d+) wrong · (\\d+)% accuracy/);
    const start = [...document.querySelectorAll('[data-train-openings] button')]
      .find((button) => button.textContent.trim() === 'Start');
    return {
      path: location.pathname,
      tab: tab ? tab.textContent.replace(/\\s+/g, ' ').trim() : '',
      trainSelected: train?.getAttribute('aria-selected') === 'true',
      countdownSeconds: countdown ? Number(countdown[1]) * 60 + Number(countdown[2]) : null,
      makeYourMove: body.includes('Make your move'),
      summary: summary
        ? { positions: Number(summary[1]), correct: Number(summary[2]), incorrect: Number(summary[3]) }
        : null,
      popover: document.querySelector('[data-train-openings]')?.innerText.replace(/\\s+/g, ' ').trim() ?? null,
      startDisabled: start ? !!start.disabled : null,
      startBusy: start ? start.getAttribute('data-loading') === 'true' || start.getAttribute('aria-busy') === 'true' : null,
      notifications: [...document.querySelectorAll('[data-mantine-notification], .mantine-Notification-root')]
        .map((node) => node.innerText.replace(/\\s+/g, ' ').trim())
        .filter(Boolean),
      body: body.slice(0, 800),
    };
  `);
}

async function selectTimedRunMinutes(session, minutes) {
  const labelText = `${minutes} min`;
  const minuteLabel = await reachableStableCoordinates(
    session,
    labelText,
    `[...document.querySelectorAll('[data-train-openings] label, [data-train-openings] button')]
      .find((node) => node.textContent.trim() === ${JSON.stringify(labelText)})`,
  );
  await clickAt(session, minuteLabel.x, minuteLabel.y);
  const selected = await waitFor(
    `${labelText} checked after pointer click`,
    async () => {
      const state = await timedRunMinutesState(session);
      return state.present && state.checked === String(minutes) ? state : false;
    },
    { timeoutMs: 3_000, everyMs: 100 },
  );
  console.log(`  .. minute control after pointer click: ${JSON.stringify(selected)}`);
  return selected;
}

async function answerTimedRunChapter(session, cards, pointerPrefix, waitAfterLast) {
  for (const [index, position] of cards.entries()) {
    await waitFor(
      `${pointerPrefix} card ${index + 1} to finish replay`,
      async () => (await timedRunPageText(session)).makeYourMove,
      { timeoutMs: TIMED_RUN_TIMEOUT_MS },
    );
    await playPracticeBoardMove(session, position.uci, `${pointerPrefix}-${index}`);
    const last = index === cards.length - 1;
    if (last) {
      await waitAfterLast();
      return;
    }
    await waitFor(
      `${pointerPrefix} card ${index + 1} counted correct`,
      async () => {
        const text = await session.execute("return document.body.innerText");
        return text.includes(`${index + 1} correct`);
      },
      { timeoutMs: TIMED_RUN_TIMEOUT_MS },
    );
  }
}

async function verifyTimedRun(profileDirectory, screenshotDirectory) {
  const italianCards = timedRunChapterCards(["e4", "e5", "Nf3", "Nc6", "Bc4"]);
  italianCards[0].weight = TIMED_RUN_TRAILING_CHAPTER_WEIGHTS[0];
  italianCards[1].weight = TIMED_RUN_TRAILING_CHAPTER_WEIGHTS[1];
  const queensCards = timedRunChapterCards(["d4", "d5", "c4", "e6", "Nc3"]);
  queensCards[0].weight = TIMED_RUN_LEADING_CHAPTER_WEIGHTS[0];
  queensCards[1].weight = TIMED_RUN_LEADING_CHAPTER_WEIGHTS[1];
  const dueTotal = italianCards.length + queensCards.length;
  const repertoirePgn =
    timedRunPgn(
      TIMED_RUN_PGN_ITALIAN,
      TIMED_RUN_PGN_ITALIAN,
      "e5",
      "1. e4 e5 2. Nf3 Nc6 3. Bc4 *",
    ) +
    "\n" +
    timedRunPgn(
      TIMED_RUN_PGN_QUEENS_GAMBIT,
      TIMED_RUN_PGN_QUEENS_GAMBIT,
      "d5",
      "1. d4 d5 2. c4 e6 3. Nc3 *",
    );
  const referencePgn =
    timedRunPgn(
      "Reference Italian",
      "Ref White",
      "Ref Black",
      "1. e4 e5 2. Nf3 Nc6 3. Bc4 Bc5 1-0",
    ) +
    "\n" +
    timedRunPgn(
      "Reference Queen's Gambit",
      "Ref White",
      "Ref Black",
      "1. d4 d5 2. c4 e6 3. Nc3 Nf6 1-0",
    );

  const fixtureDirectory = join(profileDirectory, "path-owner-fixture");
  const ownedRoot = join(fixtureDirectory, "owned-database-root");
  const filesWorkspace = join(fixtureDirectory, "files-workspace");
  const practiceDirectory = join(profileDirectory, ".local/share/com.chessriddle.studio/practice");
  const repertoirePath = join(filesWorkspace, `${TIMED_RUN_REPERTOIRE_NAME}.pgn`);
  const referencePath = join(filesWorkspace, `${TIMED_RUN_REFERENCE_NAME}.pgn`);
  await mkdir(ownedRoot, { recursive: true });
  await mkdir(filesWorkspace, { recursive: true });
  await writeFile(repertoirePath, repertoirePgn);
  await writeFile(
    join(filesWorkspace, `${TIMED_RUN_REPERTOIRE_NAME}.info`),
    JSON.stringify({ type: "repertoire", tags: [] }),
  );
  await writeFile(referencePath, referencePgn);
  await seedNativePracticeDeck(practiceDirectory, TIMED_RUN_REPERTOIRE_ID, 0, italianCards, 1);
  await seedNativePracticeDeck(practiceDirectory, TIMED_RUN_REPERTOIRE_ID, 1, queensCards, 1);
  const registryFile = join(profileDirectory, ".config/com.chessriddle.studio/path-authority.json");
  await mkdir(join(profileDirectory, ".config/com.chessriddle.studio"), { recursive: true });
  await writeFile(
    registryFile,
    JSON.stringify({
      schema_version: 1,
      entries: [
        await pathAuthorityEntry(
          TIMED_RUN_DATABASE_ROOT_ID,
          "Timed-run database root",
          ownedRoot,
          "databaseRoot",
          ["databaseRead", "databaseMutate", "databaseCreate", "databaseExport", "downloadFile"],
          true,
        ),
        await pathAuthorityEntry(
          filesWorkspaceId,
          "Files fixture",
          filesWorkspace,
          "pgnWorkspace",
          ["readPgn", "writePgn"],
          true,
        ),
        await pathAuthorityEntry(
          TIMED_RUN_REPERTOIRE_ID,
          "Timed-run repertoire",
          repertoirePath,
          "pgnFile",
          ["readPgn", "writePgn"],
          false,
        ),
      ],
      active_database_root: { id: TIMED_RUN_DATABASE_ROOT_ID },
      pending_artifacts: [],
      provisional_attachments: [],
      image_cleanup: [],
    }),
  );

  console.log("  .. opening timed-run seed WebDriver session");
  const seedSession = await Session.open(APP_BINARY);
  let session;
  try {
    try {
      await waitFor("the timed-run seed renderer to expose Tauri", () =>
        seedSession
          .execute("return typeof window.__TAURI_INTERNALS__ === 'object'")
          .catch(() => false),
      );
      const invoke = (command, args) =>
        invokeIpc(seedSession, "__verifyTimedRunIPC", command, args);
      const referenceFile = await waitFor(
        "timed-run files workspace listing",
        async () => {
          try {
            const listing = await invoke("list_file_workspace", {
              workspace: { id: { id: filesWorkspaceId }, kind: "fileWorkspace" },
              ticket: null,
            });
            const found = listing.entries?.find(
              (entry) =>
                entry.name === TIMED_RUN_REFERENCE_NAME ||
                entry.name === `${TIMED_RUN_REFERENCE_NAME}.pgn`,
            );
            return found?.handle ?? false;
          } catch {
            return false;
          }
        },
        { timeoutMs: FILES_PROBE_TIMEOUT_MS },
      );
      const root = (await invoke("get_database_workspace", {})).root;
      const database = await invoke("create_workspace_database", {
        root,
        filename: "verify-timed-run-reference.db3",
      });
      await invoke("convert_pgn", {
        progressId: `verify-timed-run:${randomUUID()}`,
        files: [referenceFile],
        database,
        title: "verify timed-run reference",
        description: "Timed-run reference fixture",
        ticket: null,
      });
      console.log(`  .. reference database seeded: ${database.id.id}`);
      await seedRendererLocalStorage(seedSession, {
        "file-workspace": JSON.stringify({ id: { id: filesWorkspaceId }, kind: "fileWorkspace" }),
        "file-workspace-display-name": JSON.stringify("Files fixture"),
        "auto-save": "false",
        "reference-database": JSON.stringify(database),
      });
      const seedClose = await closeApplicationThroughTitlebar(seedSession, "timed-run-seed");
      if (!seedClose.gone || seedClose.survivors.length > 0) {
        throw new Error(
          `timed-run seed processes survived close: ${seedClose.survivors.join(", ")}`,
        );
      }
    } finally {
      const seedQuit = await seedSession.quit();
      if (!seedQuit.released) {
        console.log(`  .. timed-run seed WebDriver session release returned: ${seedQuit.error}`);
      }
    }

    session = await Session.open(APP_BINARY);
    const tr = async (label, action) => {
      const passed = await assertion(label, action);
      if (!passed) await captureTimedRunFailure(session, screenshotDirectory, label);
      return passed;
    };
    try {
      const startup = await tr("TR1 timed-run renderer starts on the seeded profile", () =>
        waitFor("timed-run renderer startup", () => session.execute(closeControlProbe)),
      );
      if (startup) {
        await session.call("POST", "/window/rect", { width: 1400, height: 900 });
        const rect = await session.call("GET", "/window/rect");
        if ((rect.width ?? 0) < 1400 || (rect.height ?? 0) < 900) {
          throw new Error(`timed-run window rect was ${JSON.stringify(rect)}`);
        }
      }
      const home = await tr("TR2 New Tab offers Train openings", async () => {
        if (!startup) throw new Error("TR1 renderer startup failed");
        await goToBoards(session);
        await waitFor("New Tab Train openings action", () =>
          session.execute(`
            return location.pathname === '/' && [...document.querySelectorAll('[data-home-action]')]
              .some((action) => ${ACCESSIBLE_TEXT}(action) === 'Train openings');
          `),
        );
      });
      const popover = await tr(
        `TR3 the Train openings popover shows ${TIMED_RUN_SELECTED_MINUTES} minutes and the due total`,
        async () => {
          if (!home) throw new Error("TR2 Train openings action was not reached");
          await clickButton(session, "Train openings");
          await waitFor("Train openings popover", () =>
            session.execute("return !!document.querySelector('[data-train-openings]')"),
          );
          await selectTimedRunMinutes(session, TIMED_RUN_SELECTED_MINUTES);
          const radioState = await waitFor(
            `${TIMED_RUN_SELECTED_MINUTES} min indicator to follow the data-active label`,
            async () => {
              const state = await timedRunMinutesState(session);
              return state.present &&
                state.checked === String(TIMED_RUN_SELECTED_MINUTES) &&
                minuteIndicatorFollowsActive(state)
                ? state
                : false;
            },
            { timeoutMs: 3_000, everyMs: 50 },
          ).catch(async () => timedRunMinutesState(session));
          assertTimedRunMinutePaint(radioState, TIMED_RUN_SELECTED_MINUTES);
          const text = await waitFor(
            "Train openings due total and enabled Start",
            async () => {
              const page = await timedRunPageText(session);
              if (!page.popover) return false;
              if (page.startDisabled !== false) return false;
              if (!page.popover.includes(`${dueTotal} positions due`)) return false;
              if (!page.popover.includes("1 repertoires") && !page.popover.includes("1 repertoire"))
                return false;
              return page.popover;
            },
            { timeoutMs: TIMED_RUN_TIMEOUT_MS },
          );
          if (text.includes("A reference database lets the most-played lines come first.")) {
            throw new Error(
              `reference was seeded but the popover still shows the no-reference hint: ${text}`,
            );
          }
          await writeTimedRunScreenshot(screenshotDirectory, "popover.png", session);
        },
      );
      const started = await tr(
        "TR4 Start opens the first segment on Practice/Train with a countdown",
        async () => {
          if (!popover) throw new Error("TR3 popover was not ready");
          const start = await reachableStableCoordinates(
            session,
            "Train openings Start",
            `[...document.querySelectorAll('[data-train-openings] button')]
            .find((button) => !button.disabled && button.textContent.trim() === 'Start')`,
          );
          await clickAt(session, start.x, start.y);
          let lastSnapshot;
          try {
            const page = await waitFor(
              "first timed-run segment with countdown",
              async () => {
                const snapshot = await timedRunPageText(session);
                lastSnapshot = snapshot;
                return snapshot.tab.includes(TIMED_RUN_FIRST_SEGMENT) &&
                  snapshot.trainSelected &&
                  snapshot.countdownSeconds !== null
                  ? snapshot
                  : false;
              },
              { timeoutMs: TIMED_RUN_TIMEOUT_MS },
            );
            if (
              page.countdownSeconds > TIMED_RUN_COUNTDOWN_SECONDS ||
              page.countdownSeconds <= TIMED_RUN_COUNTDOWN_FLOOR_SECONDS
            ) {
              throw new Error(
                `countdown was ${page.countdownSeconds}s, expected a ${TIMED_RUN_SELECTED_MINUTES}-minute run`,
              );
            }
            await writeTimedRunScreenshot(screenshotDirectory, "first-segment.png", session);
            console.log(
              `  .. first segment: ${page.tab}; countdown ${Math.floor(page.countdownSeconds / 60)}:${String(
                page.countdownSeconds % 60,
              ).padStart(2, "0")}`,
            );
          } catch (error) {
            throw new Error(
              `${error.message}; last snapshot: ${JSON.stringify(lastSnapshot ?? (await timedRunPageText(session).catch((dump) => dump.message)))}`,
            );
          }
        },
      );
      const decreasing = await tr("TR5 the run countdown is visible and decreasing", async () => {
        if (!started) throw new Error("TR4 first segment did not open");
        const first = await timedRunPageText(session);
        if (first.countdownSeconds === null) throw new Error("countdown was not visible");
        await waitFor(
          "countdown to decrease",
          async () => {
            const next = await timedRunPageText(session);
            return next.countdownSeconds !== null && next.countdownSeconds < first.countdownSeconds
              ? next
              : false;
          },
          { timeoutMs: 5_000, everyMs: 250 },
        );
      });
      const switched = await tr(
        "TR6 answering the first segment switches the run to the second segment",
        async () => {
          if (!decreasing) throw new Error("TR5 countdown did not decrease");
          await answerTimedRunChapter(session, queensCards, "first-segment", async () => {
            await waitFor(
              "second timed-run segment after the switch",
              async () => {
                const snapshot = await timedRunPageText(session);
                return snapshot.tab.includes(TIMED_RUN_SECOND_SEGMENT) &&
                  snapshot.trainSelected &&
                  snapshot.countdownSeconds !== null
                  ? snapshot
                  : false;
              },
              { timeoutMs: TIMED_RUN_TIMEOUT_MS },
            );
          });
          await writeTimedRunScreenshot(screenshotDirectory, "second-segment.png", session);
          const page = await timedRunPageText(session);
          console.log(`  .. second segment: ${page.tab}`);
        },
      );
      await tr("TR7 finishing the second segment shows the run summary", async () => {
        if (!switched) throw new Error("TR6 segment switch did not happen");
        await answerTimedRunChapter(session, italianCards, "second-segment", async () => {
          await waitFor(
            "timed-run summary",
            async () => {
              const snapshot = await timedRunPageText(session);
              return snapshot.summary && snapshot.summary.positions > 0 ? snapshot : false;
            },
            { timeoutMs: TIMED_RUN_TIMEOUT_MS },
          );
        });
        const page = await timedRunPageText(session);
        if (!page.summary) throw new Error("run summary was not visible");
        if (page.summary.positions !== dueTotal || page.summary.correct !== dueTotal) {
          throw new Error(`unexpected summary: ${JSON.stringify(page.summary)}`);
        }
        await writeTimedRunScreenshot(screenshotDirectory, "summary.png", session);
        console.log(`  .. summary: ${JSON.stringify(page.summary)}`);
      });
      const closed = await closeApplicationThroughTitlebar(session, "timed-run");
      if (!closed.gone || closed.survivors.length > 0) {
        throw new Error(`timed-run processes survived close: ${closed.survivors.join(", ")}`);
      }
    } finally {
      if (session) {
        const quit = await session.quit();
        if (!quit.released) {
          console.log(`  .. timed-run WebDriver session release returned: ${quit.error}`);
        }
      }
    }
  } finally {
    await printTimedRunAppLog(profileDirectory);
  }
}

function pngChunk(type, data) {
  const typeBytes = Buffer.from(type, "ascii");
  const length = Buffer.allocUnsafe(4);
  length.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([typeBytes, data]);
  const crc = Buffer.allocUnsafe(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([length, body, crc]);
}

/** Generates a valid RGBA PNG buffer with a visible checkerboard pattern (at least 64x64). */
export function createScoresheetTestPng(width = 64, height = 64) {
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  const ihdr = Buffer.allocUnsafe(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // RGBA
  ihdr[10] = 0; // compression
  ihdr[11] = 0; // filter
  ihdr[12] = 0; // interlace

  const stride = 1 + width * 4;
  const raw = Buffer.allocUnsafe(stride * height);
  for (let y = 0; y < height; y += 1) {
    const rowOffset = y * stride;
    raw[rowOffset] = 0;
    for (let x = 0; x < width; x += 1) {
      const px = rowOffset + 1 + x * 4;
      const dark = ((x >> 3) + (y >> 3)) % 2 === 0;
      raw[px] = dark ? 24 : 240;
      raw[px + 1] = dark ? 36 : 235;
      raw[px + 2] = dark ? 72 : 210;
      raw[px + 3] = 255;
    }
  }

  return Buffer.concat([
    signature,
    pngChunk("IHDR", ihdr),
    pngChunk("IDAT", deflateSync(raw)),
    pngChunk("IEND", Buffer.alloc(0)),
  ]);
}

// `wl-copy --foreground` publishes its Wayland selection asynchronously after reading stdin EOF
// and prints no readiness signal; pause briefly so it registers the offer or exits on failure.
const WL_COPY_READY_SETTLE_MS = 200;
const PRIVATE_SECRET_SERVICE_TIMEOUT_MS = 20_000;
const COACH_KEYRING_SERVICE = "com.chessriddle.studio.coach";
const execFile = promisify(execFileCallback);

export function invokeJsonFailure(outcome) {
  return outcome?.error ?? outcome?.result?.rejected ?? outcome?.result?.error ?? null;
}

function isPathInsideDirectory(parentDirectory, candidatePath) {
  if (typeof parentDirectory !== "string" || typeof candidatePath !== "string") return false;
  if (!parentDirectory || !candidatePath) return false;
  const resolvedParent = resolve(parentDirectory);
  const resolvedCandidate = resolve(candidatePath);
  const rel = relative(resolvedParent, resolvedCandidate);
  return rel !== "" && rel !== ".." && !rel.startsWith(`..${sep}`) && !isAbsolute(rel);
}

export function generatePrivateDbusConfig({
  profileDirectory,
  listenDirectory = join(profileDirectory, "dbus"),
}) {
  if (!isPathInsideDirectory(profileDirectory, listenDirectory)) {
    throw new Error(
      `private D-Bus listen directory ${listenDirectory} must be inside profile ${profileDirectory}`,
    );
  }
  const escapedListenDir = resolve(listenDirectory)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
  return [
    "<busconfig>",
    "  <type>session</type>",
    `  <listen>unix:dir=${escapedListenDir}</listen>`,
    "  <auth>EXTERNAL</auth>",
    '  <policy context="default">',
    '    <allow send_destination="*" eavesdrop="true"/>',
    '    <allow eavesdrop="true"/>',
    '    <allow own="*"/>',
    "  </policy>",
    "</busconfig>",
    "",
  ].join("\n");
}

export function assertPrivateSecretServiceIsolation({
  profileDirectory,
  privateAddress,
  inheritedAddress,
  listenDirectory,
  controlDirectory,
}) {
  if (typeof privateAddress !== "string" || !privateAddress.startsWith("unix:")) {
    throw new Error(
      `private D-Bus address must start with "unix:", got ${JSON.stringify(privateAddress)}`,
    );
  }
  if (typeof inheritedAddress === "string" && inheritedAddress.length > 0) {
    if (privateAddress === inheritedAddress || privateAddress === inheritedAddress.trim()) {
      throw new Error(
        "refusing private Secret Service: DBUS_SESSION_BUS_ADDRESS matches the inherited session bus",
      );
    }
  }
  if (!isPathInsideDirectory(profileDirectory, listenDirectory)) {
    throw new Error(
      `refusing private Secret Service: listen directory ${listenDirectory} is outside profile ${profileDirectory}`,
    );
  }
  if (!isPathInsideDirectory(profileDirectory, controlDirectory)) {
    throw new Error(
      `refusing private Secret Service: keyring control directory ${controlDirectory} is outside profile ${profileDirectory}`,
    );
  }
}

export function requirePrivateSecretServicePrerequisites() {
  throwIfMissingPrerequisites(
    missingCommands([
      ["dbus-daemon", "sudo apt install dbus-daemon"],
      ["gnome-keyring-daemon", "sudo apt install gnome-keyring"],
      ["busctl", "systemd (provides busctl)"],
    ]),
  );
}

function parseBusctlJson(stdout, method) {
  try {
    return JSON.parse(stdout);
  } catch (error) {
    throw new Error(`malformed busctl ${method} JSON output: ${String(stdout).trim()}`, {
      cause: error,
    });
  }
}

export function parseBusctlReadAliasOutput(stdout) {
  const parsed = parseBusctlJson(stdout, "ReadAlias");
  const aliasPath = Array.isArray(parsed?.data) ? parsed.data[0] : null;
  if (typeof aliasPath !== "string" || !aliasPath.startsWith("/")) {
    throw new Error(`unexpected busctl ReadAlias payload: ${String(stdout).trim()}`);
  }
  return aliasPath === "/" ? null : aliasPath;
}

export function hasSecretServiceSearchItemsMatch(stdout) {
  const parsed = parseBusctlJson(stdout, "SearchItems");
  const data = parsed?.data;
  if (
    !Array.isArray(data) ||
    data.length < 2 ||
    !Array.isArray(data[0]) ||
    !Array.isArray(data[1])
  ) {
    throw new Error(`unexpected busctl SearchItems payload: ${String(stdout).trim()}`);
  }
  return [...data[0], ...data[1]].some(
    (itemPath) => typeof itemPath === "string" && itemPath.startsWith("/") && itemPath !== "/",
  );
}

async function runPrivateBusctl(privateAddress, args, env) {
  if (typeof privateAddress !== "string" || !privateAddress.startsWith("unix:")) {
    throw new Error(
      `refusing busctl call without a private unix: bus address: ${JSON.stringify(privateAddress)}`,
    );
  }
  try {
    const { stdout } = await execFile(
      "busctl",
      [`--address=${privateAddress}`, "--json=short", ...args],
      { env, timeout: 2_000 },
    );
    return stdout;
  } catch (error) {
    const stderr = typeof error?.stderr === "string" ? error.stderr.trim() : "";
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(stderr ? `${message}: ${stderr}` : message, { cause: error });
  }
}

function assertDaemonAlive(name, child, { spawnError = null, stdinError = null, output = "" }) {
  if (spawnError) {
    throw new Error(`${name} failed to start: ${spawnError.message}`, {
      cause: spawnError,
    });
  }
  if (stdinError) {
    throw new Error(`${name} stdin failed: ${stdinError.message}`, {
      cause: stdinError,
    });
  }
  if (child.exitCode !== null || child.signalCode !== null) {
    throw new Error(
      `${name} exited prematurely (exit ${child.exitCode ?? "none"}, signal ${child.signalCode ?? "none"}): ${output}`,
    );
  }
}

async function startPrivateSecretService(profileDirectory, baseEnv) {
  requirePrivateSecretServicePrerequisites();

  const listenDirectory = join(profileDirectory, "dbus");
  const controlDirectory = join(profileDirectory, "keyring-control");
  const configPath = join(profileDirectory, "dbus-session.conf");
  await mkdir(listenDirectory, { recursive: true, mode: 0o700 });
  await mkdir(controlDirectory, { recursive: true, mode: 0o700 });
  await writeFile(configPath, generatePrivateDbusConfig({ profileDirectory, listenDirectory }), {
    mode: 0o600,
  });

  const dbusStdout = outputBuffer();
  const dbusStderr = outputBuffer();
  let dbusSpawnError = null;
  const dbusChild = launch(
    "dbus-daemon",
    [`--config-file=${configPath}`, "--nofork", "--print-address=1"],
    {
      env: { ...baseEnv, HOME: profileDirectory },
      stdio: ["ignore", "pipe", "pipe"],
    },
  );
  dbusChild.on("error", (error) => {
    dbusSpawnError = error;
  });
  dbusChild.stdout?.on("data", (chunk) => dbusStdout.push(chunk));
  dbusChild.stderr?.on("data", (chunk) => dbusStderr.push(chunk));

  const privateAddress = await waitFor(
    "private dbus-daemon address",
    () => {
      assertDaemonAlive("dbus-daemon", dbusChild, {
        spawnError: dbusSpawnError,
        output: dbusStderr.text() || dbusStdout.text(),
      });
      const lineMatch = dbusStdout.text().match(/^([^\r\n]+)\r?\n/);
      if (lineMatch) {
        const address = lineMatch[1].trim();
        if (!address.startsWith("unix:")) {
          throw new Error(
            `dbus-daemon printed invalid private bus address ${JSON.stringify(address)}${
              dbusStderr.text() ? `: ${dbusStderr.text()}` : ""
            }`,
          );
        }
        return address;
      }
      return false;
    },
    { timeoutMs: PRIVATE_SECRET_SERVICE_TIMEOUT_MS, everyMs: 50 },
  );

  assertPrivateSecretServiceIsolation({
    profileDirectory,
    privateAddress,
    inheritedAddress: baseEnv.DBUS_SESSION_BUS_ADDRESS,
    listenDirectory,
    controlDirectory,
  });

  const privateBusEnv = {
    ...baseEnv,
    HOME: profileDirectory,
    DBUS_SESSION_BUS_ADDRESS: privateAddress,
  };
  const keyringOutput = outputBuffer();
  let keyringSpawnError = null;
  let keyringStdinError = null;
  const keyringChild = launch(
    "gnome-keyring-daemon",
    ["--unlock", "--foreground", "--components=secrets", `--control-directory=${controlDirectory}`],
    {
      env: privateBusEnv,
      stdio: ["pipe", "pipe", "pipe"],
    },
  );
  keyringChild.on("error", (error) => {
    keyringSpawnError = error;
  });
  keyringChild.stdin.on("error", (error) => {
    keyringStdinError = error;
  });
  keyringChild.stdout?.on("data", (chunk) => keyringOutput.push(chunk));
  keyringChild.stderr?.on("data", (chunk) => keyringOutput.push(chunk));

  await new Promise((resolvePromise, rejectPromise) => {
    let settled = false;
    const settle = (error) => {
      if (settled) return;
      settled = true;
      if (error) rejectPromise(error);
      else resolvePromise();
    };
    if (keyringSpawnError) {
      settle(
        new Error(`gnome-keyring-daemon failed to start: ${keyringSpawnError.message}`, {
          cause: keyringSpawnError,
        }),
      );
      return;
    }
    const onChildError = (error) =>
      settle(new Error(`gnome-keyring-daemon failed to start: ${error.message}`, { cause: error }));
    const onStdinError = (error) =>
      settle(
        new Error(
          `failed to write unlock password to gnome-keyring-daemon stdin: ${error.message}`,
          { cause: error },
        ),
      );
    keyringChild.once("error", onChildError);
    keyringChild.stdin.once("error", onStdinError);
    keyringChild.stdin.end("verify-throwaway-secret\n", () => {
      keyringChild.off("error", onChildError);
      keyringChild.stdin.off("error", onStdinError);
      settle();
    });
  });

  let lastBusctlError = null;
  try {
    await waitFor(
      "private Secret Service default collection",
      async () => {
        assertDaemonAlive("dbus-daemon", dbusChild, {
          spawnError: dbusSpawnError,
          output: dbusStderr.text() || dbusStdout.text(),
        });
        assertDaemonAlive("gnome-keyring-daemon", keyringChild, {
          spawnError: keyringSpawnError,
          stdinError: keyringStdinError,
          output: keyringOutput.text(),
        });
        try {
          const stdout = await runPrivateBusctl(
            privateAddress,
            [
              "call",
              "org.freedesktop.secrets",
              "/org/freedesktop/secrets",
              "org.freedesktop.Secret.Service",
              "ReadAlias",
              "s",
              "default",
            ],
            privateBusEnv,
          );
          const defaultCollection = parseBusctlReadAliasOutput(stdout);
          if (defaultCollection) return defaultCollection;
          lastBusctlError = 'ReadAlias("default") returned "/"';
          return false;
        } catch (error) {
          lastBusctlError = error instanceof Error ? error.message : String(error);
          return false;
        }
      },
      { timeoutMs: PRIVATE_SECRET_SERVICE_TIMEOUT_MS, everyMs: 100 },
    );
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (message.startsWith("timed out waiting for ")) {
      const details = [
        lastBusctlError ? `last busctl error: ${lastBusctlError}` : null,
        keyringOutput.text().trim()
          ? `gnome-keyring-daemon output: ${keyringOutput.text().trim()}`
          : null,
      ]
        .filter(Boolean)
        .join("; ");
      throw new Error(details ? `${message} (${details})` : message, { cause: error });
    }
    throw error;
  }

  return { DBUS_SESSION_BUS_ADDRESS: privateAddress };
}

async function waitForDialogShown(session, label = "the fully shown dialog") {
  // Mantine fades the modal in; reading or screenshotting before opacity reaches 1 misses it.
  await waitFor(label, () =>
    session.execute(`
      const content = document.querySelector('[role="dialog"]');
      if (!content) return false;
      let node = content;
      while (node && node !== document.body) {
        if (Number(getComputedStyle(node).opacity) < 1) return false;
        node = node.parentElement;
      }
      return true;
    `),
  );
}

async function startWaylandClipboardPng(pngBuffer, appEnvironment) {
  const output = outputBuffer();
  const clipboardOwner = launch("wl-copy", ["--foreground", "--type", "image/png"], {
    env: appEnvironment,
    stdio: ["pipe", "pipe", "pipe"],
  });
  clipboardOwner.stdout?.on("data", (chunk) => output.push(chunk));
  clipboardOwner.stderr?.on("data", (chunk) => output.push(chunk));
  await new Promise((resolve, reject) => {
    clipboardOwner.once("error", reject);
    clipboardOwner.stdin.end(pngBuffer, resolve);
  });
  await sleep(WL_COPY_READY_SETTLE_MS);
  if (clipboardOwner.exitCode !== null || clipboardOwner.signalCode !== null) {
    throw new Error(
      `wl-copy exited prematurely (exit ${clipboardOwner.exitCode ?? "none"}, signal ${clipboardOwner.signalCode ?? "none"}): ${output.text()}`,
    );
  }
  return clipboardOwner;
}

async function waitForScoresheetRendererReady(session, label) {
  await waitFor(`${label} renderer startup`, () => session.execute(closeControlProbe));
  await waitFor(`${label} Tauri IPC bridge`, () =>
    session.execute("return typeof window.__TAURI_INTERNALS__?.invoke === 'function'"),
  );
}

async function verifyScoresheetPaste(profileDirectory, appEnvironment, screenshotDirectory) {
  const clipboardOwner = await startWaylandClipboardPng(
    createScoresheetTestPng(64, 64),
    appEnvironment,
  );
  let session = null;
  try {
    session = await Session.open(APP_BINARY);
    const startupOk = await assertion(
      "SP0 scoresheet-paste renderer starts on the isolated profile",
      () => waitForScoresheetRendererReady(session, "scoresheet-paste"),
    );

    // SP-N: native clipboard route (always runs on startup success, independent of SP-P).
    await assertion(
      "SP-N native scoresheet_paste_photo returns a JPEG data URL that renders under the real CSP",
      async () => {
        if (!startupOk) throw new Error("SP0 renderer startup failed");
        const pasted = await invokeJsonAndWait(
          session,
          "scoresheet_paste_photo",
          "__verifyScoresheetNativePaste",
          'window.__TAURI_INTERNALS__.invoke("scoresheet_paste_photo")',
        );
        const pastedFailure = invokeJsonFailure(pasted);
        if (pastedFailure) {
          throw new Error(`scoresheet_paste_photo failed: ${pastedFailure}`);
        }
        const dataUrl = pasted.value?.dataUrl;
        if (typeof dataUrl !== "string" || !dataUrl.startsWith("data:image/jpeg;base64,")) {
          throw new Error(
            `expected JPEG data URL from scoresheet_paste_photo, got: ${JSON.stringify(pasted.value)}`,
          );
        }
        try {
          await session.execute(
            `
              const existing = document.getElementById('__verify-scoresheet-native-img');
              if (existing) existing.remove();
              const img = document.createElement('img');
              img.id = '__verify-scoresheet-native-img';
              img.alt = 'verify scoresheet native paste';
              img.style.cssText = 'position:fixed;top:16px;left:16px;z-index:999999;border:2px solid #000;background:#fff;';
              img.src = arguments[0];
              document.body.appendChild(img);
              return true;
            `,
            [dataUrl],
          );
          const decoded = await waitFor("native scoresheet JPEG image to render", () =>
            session.execute(`
              const img = document.getElementById('__verify-scoresheet-native-img');
              if (!img || !img.complete) return false;
              return {
                src: img.getAttribute('src') || '',
                naturalWidth: img.naturalWidth,
                naturalHeight: img.naturalHeight,
              };
            `),
          );
          if (
            !decoded.src.startsWith("data:image/jpeg;base64,") ||
            decoded.naturalWidth <= 0 ||
            decoded.naturalHeight <= 0
          ) {
            throw new Error(
              `native scoresheet image did not decode cleanly: ${JSON.stringify(decoded)}`,
            );
          }
          console.log(
            `  .. native clipboard image rendered: ${decoded.naturalWidth}x${decoded.naturalHeight} (src length ${decoded.src.length})`,
          );
          if (screenshotDirectory) {
            await mkdir(screenshotDirectory, { recursive: true });
            const nativeShotPath = join(screenshotDirectory, "scoresheet-native-paste.png");
            await writeFile(nativeShotPath, Buffer.from(await session.screenshot(), "base64"));
            console.log(`  .. scoresheet-native-paste screenshot: ${nativeShotPath}`);
          }
        } finally {
          await session
            .execute(
              "document.getElementById('__verify-scoresheet-native-img')?.remove(); return true;",
            )
            .catch(() => {});
        }
      },
    );

    if (startupOk) {
      // Save is non-idempotent (each call allocates a new handle), so invoke it exactly once.
      const saveOk = await assertion(
        "SP-Save coach_save_api_connection persists a local connection with durabilityUncertain === false",
        async () => {
          const saved = await invokeJsonAndWait(
            session,
            "coach_save_api_connection",
            "__verifyScoresheetSaveConnection",
            `window.__TAURI_INTERNALS__.invoke("coach_save_api_connection", ${JSON.stringify({
              connection: {
                label: "Verify Scoresheet Connection",
                address: "http://127.0.0.1:11434/v1",
                key: null,
              },
            })})`,
          );
          const savedFailure = invokeJsonFailure(saved);
          if (savedFailure) {
            throw new Error(`coach_save_api_connection failed: ${savedFailure}`);
          }
          if (
            saved.value === null ||
            typeof saved.value !== "object" ||
            saved.value.durabilityUncertain !== false ||
            typeof saved.value.connection?.handle !== "string" ||
            saved.value.connection.handle.length === 0
          ) {
            throw new Error(
              `expected ConnectionSaved with durabilityUncertain === false, got: ${JSON.stringify(saved.value)}`,
            );
          }
        },
      );

      let privateItemOk = false;
      if (saveOk) {
        privateItemOk = await assertion(
          "SP-Keyring private Secret Service holds an item for com.chessriddle.studio.coach",
          async () => {
            const privateAddress = appEnvironment?.DBUS_SESSION_BUS_ADDRESS;
            const stdout = await runPrivateBusctl(
              privateAddress,
              [
                "call",
                "org.freedesktop.secrets",
                "/org/freedesktop/secrets",
                "org.freedesktop.Secret.Service",
                "SearchItems",
                "a{ss}",
                "1",
                "service",
                COACH_KEYRING_SERVICE,
              ],
              appEnvironment,
            );
            if (!hasSecretServiceSearchItemsMatch(stdout)) {
              throw new Error(
                `private Secret Service returned no item for service ${COACH_KEYRING_SERVICE}: ${stdout.trim()}`,
              );
            }
          },
        );
      }

      let restartOk = false;
      if (saveOk && privateItemOk) {
        restartOk = await assertion(
          "SP-Restart application closes cleanly and restarts on the same profile and private bus",
          async () => {
            const closed = await closeApplicationThroughTitlebar(
              session,
              "scoresheet-paste-pre-restart",
            );
            if (!closed.gone || closed.survivors.length > 0) {
              throw new Error(
                `scoresheet-paste session 1 survived close: ${closed.survivors.join(", ")}`,
              );
            }
            // Session 1 has exited; no session is live until Session.open succeeds.
            const firstSession = session;
            session = null;
            const released = await firstSession.quit();
            if (!released.released) {
              throw new Error(`could not release scoresheet-paste session 1: ${released.error}`);
            }
            session = await Session.open(APP_BINARY);
            await waitForScoresheetRendererReady(session, "scoresheet-paste restarted");
          },
        );
      }

      let connectionOk = false;
      if (restartOk) {
        connectionOk = await assertion(
          "SP-Connection coach_available and coach_has_connection are true after startup reconcile",
          async () => {
            const available = await invokeJsonAndWait(
              session,
              "coach_available",
              "__verifyScoresheetCoachAvailable",
              'window.__TAURI_INTERNALS__.invoke("coach_available")',
            );
            const availableFailure = invokeJsonFailure(available);
            if (availableFailure || available.value !== true) {
              throw new Error(
                availableFailure
                  ? `coach_available failed: ${availableFailure}`
                  : `coach_available was ${JSON.stringify(available.value)}`,
              );
            }
            const hasConnection = await invokeJsonAndWait(
              session,
              "coach_has_connection",
              "__verifyScoresheetCoachHasConnection",
              'window.__TAURI_INTERNALS__.invoke("coach_has_connection")',
            );
            const hasConnectionFailure = invokeJsonFailure(hasConnection);
            if (hasConnectionFailure || hasConnection.value !== true) {
              throw new Error(
                hasConnectionFailure
                  ? `coach_has_connection failed: ${hasConnectionFailure}`
                  : `coach_has_connection was ${JSON.stringify(hasConnection.value)}`,
              );
            }
          },
        );
      }

      // SP-P: "Photo" pane route (only attempted when the saved connection survived restart).
      if (connectionOk) {
        const spPOpened = await assertion(
          "SP-P1 Import dialog opens and selects Photo in the connected state",
          async () => {
            await goToBoards(session);
            await clickButton(session, "Import");
            await waitForDialogShown(session, "the fully shown Import dialog");
            const fromPhotoPresent = await session.execute(
              `return [...document.querySelectorAll('[role="dialog"] button')].some(node => !node.disabled && node.textContent.trim() === 'Photo')`,
            );
            if (!fromPhotoPresent) {
              throw new Error(
                "'Photo' option is missing from the Import dialog even though coach_available was true",
              );
            }
            const fromPhotoCard = await reachableStableCoordinates(
              session,
              "Photo",
              `[...document.querySelectorAll('[role="dialog"] button')].find(node => !node.disabled && node.textContent.trim() === 'Photo')`,
            );
            await clickAt(session, fromPhotoCard.x, fromPhotoCard.y);

            let lastPaneState = "not-rendered";
            try {
              await waitFor("Photo pane to settle in connected state", async () => {
                const state = await session.execute(`
                  const dialog = document.querySelector('[role="dialog"]');
                  if (!dialog) return "no-dialog";
                  if (dialog.querySelector('[data-scoresheet-intake-pane]')) return "connected";
                  if (dialog.querySelector('[data-scoresheet-no-connection]')) return "no-connection";
                  return "pending";
                `);
                lastPaneState = state;
                return state === "connected";
              });
            } catch (error) {
              throw new Error(`${error.message} (last observed pane state: ${lastPaneState})`, {
                cause: error,
              });
            }
          },
        );

        const spPPasted = await assertion(
          "SP-P2 Paste from clipboard renders a JPEG data-URL thumbnail with naturalWidth > 0",
          async () => {
            if (!spPOpened) throw new Error("SP-P1 Import dialog did not open the Photo pane");
            const pasteButton = await reachableStableCoordinates(
              session,
              "Paste from clipboard",
              `[...document.querySelectorAll('[data-scoresheet-intake-pane] button')].find(node => !node.disabled && node.textContent.trim() === 'Paste from clipboard')`,
            );
            await clickAt(session, pasteButton.x, pasteButton.y);

            const thumbnail = await waitFor("pasted scoresheet JPEG thumbnail", async () => {
              const state = await session.execute(`
                const img = document.querySelector('[data-scoresheet-thumbnails] img');
                const status = document.querySelector('[data-scoresheet-intake-status]')?.textContent?.trim() ?? null;
                if (!img) return status ? { status, missing: true } : false;
                return {
                  src: img.getAttribute('src') || '',
                  complete: img.complete,
                  naturalWidth: img.naturalWidth,
                  naturalHeight: img.naturalHeight,
                  status,
                };
              `);
              if (!state) return false;
              if (state.missing) {
                throw new Error(
                  `clipboard paste reported intake status without thumbnail: ${state.status}`,
                );
              }
              if (!state.src.startsWith("data:image/jpeg;base64,")) return false;
              if (!state.complete || state.naturalWidth <= 0) return false;
              return state;
            });
            console.log(
              `  .. scoresheet thumbnail rendered: ${thumbnail.naturalWidth}x${thumbnail.naturalHeight} (src length ${thumbnail.src.length})`,
            );
          },
        );

        if (screenshotDirectory) {
          await assertion("SP-P3 scoresheet-paste screenshot is written", async () => {
            if (!spPPasted) throw new Error("SP-P2 thumbnail did not render");
            await mkdir(screenshotDirectory, { recursive: true });
            const path = join(screenshotDirectory, "scoresheet-paste.png");
            await writeFile(path, Buffer.from(await session.screenshot(), "base64"));
            console.log(`  .. scoresheet-paste screenshot: ${path}`);
          });
        }
      }
    }

    if (session) {
      await assertion("SP-Close scoresheet-paste application exits cleanly", async () => {
        const closed = await closeApplicationThroughTitlebar(session, "scoresheet-paste");
        if (!closed.gone || closed.survivors.length > 0) {
          throw new Error(
            `scoresheet-paste processes survived close: ${closed.survivors.join(", ")}`,
          );
        }
      });
    }
  } finally {
    if (session) {
      const quit = await session.quit();
      if (!quit.released) {
        console.log(`  .. scoresheet-paste WebDriver session release returned: ${quit.error}`);
      }
    }
    await stopLaunchedChild(clipboardOwner).catch((error) => {
      console.log(`  .. wl-copy cleanup returned: ${error.message}`);
    });
  }
}

const XDG_OPEN_STUB_LOG_NAME = "xdg-open-calls.log";
// Allow any asynchronous WebKitGTK navigation attempt after a link click to settle before checking `location.href`.
const EXTERNAL_LINK_LOCATION_SETTLE_MS = 150;
// Allow a detached `open::that_detached` child time to append to the stub log before asserting no invocation occurred.
const EXTERNAL_LINK_STUB_SETTLE_MS = 250;

function shSingleQuote(value) {
  return `'${String(value).replaceAll("'", "'\\''")}'`;
}

async function installXdgOpenStub(profileDirectory, baseEnv) {
  const stubDir = join(profileDirectory, "bin");
  const stubPath = join(stubDir, "xdg-open");
  const logPath = join(profileDirectory, XDG_OPEN_STUB_LOG_NAME);
  await mkdir(stubDir, { recursive: true, mode: 0o700 });
  const script = [
    "#!/bin/sh",
    'if [ "$#" -eq 1 ]; then',
    `  printf '%s\\n' "$1" >> ${shSingleQuote(logPath)}`,
    "else",
    `  printf 'UNEXPECTED_ARGC_%s:%s\\n' "$#" "$*" >> ${shSingleQuote(logPath)}`,
    "fi",
    "",
  ].join("\n");
  await writeFile(stubPath, script, { mode: 0o755 });
  chmodSync(stubPath, 0o755);
  return {
    PATH: baseEnv.PATH ? `${stubDir}:${baseEnv.PATH}` : stubDir,
  };
}

async function readXdgOpenStubCalls(logPath) {
  try {
    const raw = await readFile(logPath, "utf8");
    return raw
      .split("\n")
      .map((line) => line.replace(/\r$/, ""))
      .filter((line) => line.length > 0);
  } catch (error) {
    if (error?.code === "ENOENT") return [];
    throw error;
  }
}

function assertStubCallsUnchanged(actual, expected, context) {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(
      `stub xdg-open calls changed during ${context}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`,
    );
  }
}

async function invokeIpcRefusal(session, { label, globalName, command, args, assertRejection }) {
  const outcome = await invokeJsonAndWait(
    session,
    label,
    globalName,
    `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)}, ${JSON.stringify(args)})`,
  );
  const rejection = outcome.result?.rejected;
  if (typeof rejection !== "string" || rejection.length === 0) {
    throw new Error(`expected ${label} to reject, got ${JSON.stringify(outcome)}`);
  }
  assertRejection(rejection);
  return rejection;
}

async function verifyExternalLink(profileDirectory, appEnvironment) {
  const logPath = join(profileDirectory, XDG_OPEN_STUB_LOG_NAME);
  const expectedStubDir = join(profileDirectory, "bin");
  const pathEntries = (appEnvironment?.PATH ?? "").split(":");
  if (pathEntries[0] !== expectedStubDir) {
    throw new Error(
      `expected stub directory ${expectedStubDir} first on PATH, got ${appEnvironment?.PATH ?? "(unset)"}`,
    );
  }

  const externalLinkCommentUrl = "https://example.invalid/external-link-comment";
  const seededPgn = [
    '[Event "verify:external-link"]',
    '[Site "?"]',
    '[Date "2026.11.26"]',
    '[Round "1"]',
    '[White "A"]',
    '[Black "B"]',
    '[Result "*"]',
    "",
    `1. e4 { [External check](${externalLinkCommentUrl}) } *`,
  ].join("\n");

  const session = await Session.open(APP_BINARY);
  try {
    const startupOk = await assertion(
      "EL0 external-link renderer starts on a fresh profile",
      async () => {
        await waitFor("external-link renderer startup", () => session.execute(closeControlProbe));
        await waitFor("Tauri IPC bridge", () =>
          session.execute("return typeof window.__TAURI_INTERNALS__ === 'object'"),
        );
      },
    );

    let locationBefore = null;
    await assertion(
      "EL1 clicking a PGN comment link on an Analysis Board opens exactly that URL via stub xdg-open without changing window location",
      async () => {
        if (!startupOk) throw new Error("EL0 renderer startup failed");
        await clickButton(session, "Analysis Board");
        await waitFor("Analysis Board to render", () =>
          session.execute("return !!document.querySelector('cg-board')"),
        );
        await updateActiveTreePgnInEditor(session, seededPgn, {
          keyboardId: "external-link-keyboard",
          readyLabel: "seeded PGN value in editor",
        });

        const commentLink = await reachableStableCoordinates(
          session,
          "PGN comment external link",
          `document.querySelector('a[href=' + JSON.stringify(arguments[0]) + ']')`,
          [externalLinkCommentUrl],
        );
        locationBefore = await session.execute("return location.href");
        await clickAt(session, commentLink.x, commentLink.y);

        const recordedCalls = await waitFor("stub xdg-open to record the clicked URL", async () => {
          const calls = await readXdgOpenStubCalls(logPath);
          return calls.length > 0 ? calls : false;
        });
        if (recordedCalls.length !== 1 || recordedCalls[0] !== externalLinkCommentUrl) {
          throw new Error(
            `expected stub xdg-open to record [${JSON.stringify(externalLinkCommentUrl)}], got ${JSON.stringify(recordedCalls)}`,
          );
        }
        await sleep(EXTERNAL_LINK_LOCATION_SETTLE_MS);
        const locationAfter = await session.execute("return location.href");
        if (locationAfter !== locationBefore) {
          throw new Error(
            `main window location changed after link click: before=${locationBefore}, after=${locationAfter}`,
          );
        }
        console.log(
          `  .. stub xdg-open recorded URL: ${recordedCalls[0]} (location unchanged: ${locationBefore})`,
        );
      },
    );

    const baselineCalls = await readXdgOpenStubCalls(logPath);

    await assertion(
      "EL2 open_external_url refuses file: and javascript: URLs without invoking stub xdg-open",
      async () => {
        if (!startupOk) throw new Error("EL0 renderer startup failed");
        const refusedUrls = [
          { url: "file:///etc/passwd", globalName: "__verifyExternalLinkFileRefusal" },
          { url: "javascript:alert(1)", globalName: "__verifyExternalLinkJsRefusal" },
        ];
        const refusals = [];
        for (const { url, globalName } of refusedUrls) {
          const rejection = await invokeIpcRefusal(session, {
            label: `open_external_url ${url}`,
            globalName,
            command: "open_external_url",
            args: { url },
            assertRejection(raw) {
              let payload;
              try {
                payload = JSON.parse(raw);
              } catch (error) {
                throw new Error(
                  `expected JSON ErrorPayload from open_external_url(${url}), got ${raw}`,
                  { cause: error },
                );
              }
              if (payload?.category !== "invalid-input") {
                throw new Error(
                  `expected invalid-input category from open_external_url(${url}), got ${raw}`,
                );
              }
            },
          });
          refusals.push({ url, rejection });
        }

        await sleep(EXTERNAL_LINK_STUB_SETTLE_MS);
        assertStubCallsUnchanged(
          await readXdgOpenStubCalls(logPath),
          baselineCalls,
          "refused open_external_url invocations",
        );
        for (const { url, rejection } of refusals) {
          console.log(`  .. open_external_url refused ${url}: ${rejection}`);
        }
      },
    );

    await assertion("EL3 plugin:opener|open_url is refused by the ACL", async () => {
      if (!startupOk) throw new Error("EL0 renderer startup failed");
      const aclRejection = await invokeIpcRefusal(session, {
        label: "plugin:opener|open_url ACL probe",
        globalName: "__verifyExternalLinkAclRefusal",
        command: "plugin:opener|open_url",
        args: { url: "https://example.invalid/acl-probe" },
        assertRejection(raw) {
          if (!/not allowed by ACL/iu.test(raw)) {
            throw new Error(`expected plugin:opener|open_url to be refused by ACL, got ${raw}`);
          }
        },
      });
      await sleep(EXTERNAL_LINK_STUB_SETTLE_MS);
      assertStubCallsUnchanged(
        await readXdgOpenStubCalls(logPath),
        baselineCalls,
        "ACL-refused plugin:opener|open_url probe",
      );
      console.log(`  .. plugin:opener|open_url ACL refusal: ${aclRejection}`);
    });

    await assertion(
      'EL4 opener plugin injected click listener is absent on synthetic target="_blank" click',
      async () => {
        if (!startupOk) throw new Error("EL0 renderer startup failed");
        const locationAtStart = locationBefore ?? (await session.execute("return location.href"));
        try {
          await session.execute(`
            document.getElementById('__verify-external-link-synthetic')?.remove();
            if (window.__verifyExternalLinkListener) {
              window.removeEventListener('click', window.__verifyExternalLinkListener);
            }
            window.__verifyExternalLinkSyntheticClick = null;
            const anchor = document.createElement('a');
            anchor.id = '__verify-external-link-synthetic';
            anchor.href = 'https://example.invalid/synthetic-plugin-probe';
            anchor.target = '_blank';
            anchor.rel = 'noreferrer';
            anchor.textContent = 'Synthetic External Probe';
            anchor.style.cssText = 'position:fixed;top:16px;left:16px;z-index:999999;padding:8px 12px;background:#fff;color:#000;border:2px solid #000;';
            const listener = (event) => {
              const targetAnchor = event.target instanceof Element ? event.target.closest('a') : null;
              if (targetAnchor !== anchor) return;
              window.__verifyExternalLinkSyntheticClick = {
                defaultPreventedOnArrival: event.defaultPrevented,
                href: anchor.getAttribute('href'),
              };
              event.preventDefault();
            };
            window.__verifyExternalLinkListener = listener;
            window.addEventListener('click', listener);
            document.body.appendChild(anchor);
            return true;
          `);
          const syntheticPoint = await reachableStableCoordinates(
            session,
            'synthetic target="_blank" anchor',
            "document.getElementById('__verify-external-link-synthetic')",
          );
          await clickAt(session, syntheticPoint.x, syntheticPoint.y);
          const observation = await waitFor("synthetic anchor click observation", () =>
            session.execute("return window.__verifyExternalLinkSyntheticClick || false"),
          );
          if (observation.defaultPreventedOnArrival !== false) {
            throw new Error(
              `expected defaultPrevented to be false on arrival at post-load window listener, got ${JSON.stringify(observation)}`,
            );
          }
          await sleep(EXTERNAL_LINK_STUB_SETTLE_MS);
          const afterCalls = await readXdgOpenStubCalls(logPath);
          assertStubCallsUnchanged(
            afterCalls,
            baselineCalls,
            'synthetic target="_blank" anchor click',
          );
          const locationAfter = await session.execute("return location.href");
          if (locationAfter !== locationAtStart) {
            throw new Error(
              `main window location changed on synthetic click: before=${locationAtStart}, after=${locationAfter}`,
            );
          }
          console.log(
            `  .. opener plugin click listener absent: synthetic target="_blank" click arrived with defaultPrevented=${observation.defaultPreventedOnArrival}, stub calls=${afterCalls.length}`,
          );
        } finally {
          await session
            .execute(`
              document.getElementById('__verify-external-link-synthetic')?.remove();
              if (window.__verifyExternalLinkListener) {
                window.removeEventListener('click', window.__verifyExternalLinkListener);
              }
              delete window.__verifyExternalLinkListener;
              delete window.__verifyExternalLinkSyntheticClick;
              return true;
            `)
            .catch(() => {});
        }
      },
    );

    if (startupOk) {
      await assertion("EL-Close external-link application exits cleanly", async () => {
        const closed = await closeApplicationThroughTitlebar(session, "external-link");
        if (!closed.gone || closed.survivors.length > 0) {
          throw new Error(`external-link processes survived close: ${closed.survivors.join(", ")}`);
        }
      });
    }
  } finally {
    const quit = await session.quit();
    if (!quit.released) {
      console.log(`  .. external-link WebDriver session release returned: ${quit.error}`);
    }
  }
}

async function main() {
  process.on("exit", () => {
    restoreRootPermissionsForCleanup("exit");
    if (!cleanupSettled) console.error("cleanup did not finish before process exit");
  });
  for (const signal of ["SIGINT", "SIGTERM", "SIGHUP"]) process.on(signal, handleSignal);
  try {
    assertExclusiveFlowModes(process.argv);
    if (
      screenshotDirIndex !== -1 &&
      (!screenshotDirectory || screenshotDirectory.startsWith("--"))
    ) {
      throw new Error("--screenshot-dir requires a directory path");
    }
    if (!isAbsolute(progressApplication) || !existsSync(progressApplication)) {
      throw new Error("progress application must name an existing absolute binary path");
    }
    if (
      expectedProgressGeneration !== undefined &&
      !canonicalProgressGeneration(expectedProgressGeneration)
    ) {
      throw new Error(
        "expected progress generation must be a canonical unsigned u64 decimal string",
      );
    }
    if (
      !progressContractOnly &&
      (applicationIndex !== -1 || progressGenerationIndex !== -1 || expectClearRejection)
    ) {
      throw new Error("disposable progress measurement options require --progress-contract");
    }
    requirePrerequisites(progressContractOnly ? progressApplication : APP_BINARY);

    const { socket } = await startCompositor();
    const { profileDirectory, appEnvironment } = await startDriver({
      waylandDisplay: socket,
      env: externalLinkOnly
        ? ({ profileDirectory: home, env }) => installXdgOpenStub(home, env)
        : scoresheetPasteOnly
          ? ({ profileDirectory: home, env }) => startPrivateSecretService(home, env)
          : undefined,
    });
    if (externalLinkOnly) {
      await verifyExternalLink(profileDirectory, appEnvironment);
    } else if (progressContractOnly) {
      const progressSession = await Session.open(progressApplication);
      try {
        await waitFor("progress renderer startup", () =>
          progressSession.execute(closeControlProbe),
        );
        await verifyProgressContract(progressSession);
        if (screenshotPath && !expectClearRejection) {
          await writeFile(
            screenshotPath,
            Buffer.from(await progressSession.screenshot(), "base64"),
          );
        }
      } finally {
        await progressSession.quit();
      }
    } else if (fallbackEngineInstallOnly || gameReportOnly) {
      const fallbackSession = await Session.open(APP_BINARY);
      try {
        await verifyFallbackEngineInstall(fallbackSession, { screenshot: !gameReportOnly });
        if (gameReportOnly) await verifyGameReport(fallbackSession);
      } finally {
        await fallbackSession.quit();
      }
    } else if (scoresheetPasteOnly) {
      await verifyScoresheetPaste(profileDirectory, appEnvironment, screenshotDirectory);
    } else if (timedRunOnly) {
      const timedRunScreenshotDirectory =
        screenshotDirectory ?? join(profileDirectory, "timed-run-screenshots");
      await mkdir(timedRunScreenshotDirectory, { recursive: true });
      console.log(`  .. timed-run screenshots: ${timedRunScreenshotDirectory}`);
      await verifyTimedRun(profileDirectory, timedRunScreenshotDirectory);
    } else if (workspaceRestoreOnly) {
      await verifyWorkspaceRestore(profileDirectory);
    } else {
      await verifyFullApplication(profileDirectory, appEnvironment);
    }
  } catch (error) {
    console.error(`\nverify:app could not run: ${error.message}`);
    if (error.stack) console.error(error.stack);
    const diagnostics = driverDiagnostics();
    if (diagnostics) console.error(`  .. tauri-driver output:\n${diagnostics}`);
    process.exitCode = 1;
  } finally {
    restoreRootPermissionsForCleanup("normal/fatal");
    try {
      await shutdown();
    } catch (error) {
      console.error(`\nverify:app cleanup failed: ${error.message}`);
      process.exitCode = 1;
    } finally {
      cleanupSettled = true;
    }
  }

  if (failures.length > 0) {
    console.error(`\n${failures.length} check(s) failed`);
    process.exitCode = 1;
  } else if (process.exitCode !== 1) {
    console.log("\nall checks passed");
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) await main();
